fn alias_service_from_iso_config(
    config: &iroha_config::parameters::actual::IsoBridge,
    attester: AliasAttester,
) -> Option<Arc<AliasService>> {
    if !config.enabled {
        return None;
    }
    let service = AliasService::new(attester);
    let mut inserted = 0usize;
    for (index, alias_cfg) in config.account_aliases.iter().enumerate() {
        let canonical = normalise_alias(&alias_cfg.iban);
        if canonical.is_empty() {
            iroha_logger::warn!(
                iban = %alias_cfg.iban,
                "ISO bridge alias produced empty canonical representation"
            );
            continue;
        }
        let alias_name = match Name::from_str(&canonical) {
            Ok(name) => name,
            Err(err) => {
                iroha_logger::warn!(
                    iban = %alias_cfg.iban,
                    %err,
                    "ISO bridge alias is not a valid Name"
                );
                continue;
            }
        };
        let account_id: AccountId = match AccountId::parse_encoded(&alias_cfg.account_id) {
            Ok(account_id) => account_id,
            Err(err) => {
                iroha_logger::warn!(
                    iban = %alias_cfg.iban,
                    account = %alias_cfg.account_id,
                    %err,
                    "ISO bridge alias refers to an invalid account identifier"
                );
                continue;
            }
        };
        let record = AliasRecord::new(
            alias_name.clone(),
            account_id.clone(),
            AliasTarget::Account(account_id),
            AliasIndex(index as u64),
        );
        match service.storage().put(record) {
            Ok(_) => inserted += 1,
            Err(err) => {
                iroha_logger::warn!(
                    iban = %alias_cfg.iban,
                    ?err,
                    "failed to insert ISO bridge alias into alias service storage"
                );
            }
        }
    }
    if inserted == 0 {
        None
    } else {
        Some(Arc::new(service))
    }
}
const ALIAS_METRIC_LANE: &str = "torii";
#[cfg(feature = "app_api")]
const EXACT_ALIAS_READ_MAX_BODY_BYTES: usize = 4 * 1024;
const EXACT_ALIAS_LOOKUP_MAX_ITEMS: usize = 64;
fn alias_json_response<T>(status: StatusCode, payload: T) -> Result<AxResponse, Error>
where
    T: JsonSerialize,
{
    let body = norito::json::to_vec(&payload).map_err(|err| {
        Error::Query(iroha_data_model::ValidationFail::InternalError(
            err.to_string(),
        ))
    })?;
    let mut resp = axum::response::Response::new(axum::body::Body::from(body));
    *resp.status_mut() = status;
    resp.headers_mut().insert(
        axum::http::header::CONTENT_TYPE,
        axum::http::HeaderValue::from_static("application/json"),
    );
    Ok(resp)
}
fn json_ok<T>(payload: T) -> Result<AxResponse, Error>
where
    T: JsonSerialize,
{
    alias_json_response(StatusCode::OK, payload)
}
fn alias_resolve_ok(
    alias: &str,
    account_id: &str,
    index: Option<u64>,
    source: &'static str,
) -> Result<AxResponse, Error> {
    let payload = routing::AliasResolveResponseDto {
        alias: alias.to_owned(),
        account_id: account_id.to_owned(),
        index,
        source: Some(source.to_owned()),
    };
    alias_json_response(StatusCode::OK, payload)
}
fn alias_resolve_index_ok(
    index: u64,
    alias: &str,
    account_id: &str,
    source: &'static str,
) -> Result<AxResponse, Error> {
    let payload = routing::AliasResolveIndexResponseDto {
        index,
        alias: alias.to_owned(),
        account_id: account_id.to_owned(),
        source: Some(source.to_owned()),
    };
    alias_json_response(StatusCode::OK, payload)
}
fn alias_lookup_by_account_ok(
    account_id: &str,
    mut items: Vec<routing::AliasLookupByAccountItemDto>,
    source: &'static str,
) -> Result<AxResponse, Error> {
    if items.len() > EXACT_ALIAS_LOOKUP_MAX_ITEMS {
        return Err(Error::Query(iroha_data_model::ValidationFail::QueryFailed(
            iroha_data_model::query::error::QueryExecutionFail::CapacityLimit,
        )));
    }
    items.sort_by(|left, right| {
        left.alias
            .cmp(&right.alias)
            .then_with(|| left.dataspace.cmp(&right.dataspace))
            .then_with(|| left.domain.cmp(&right.domain))
            .then_with(|| right.is_primary.cmp(&left.is_primary))
    });
    let total = u64::try_from(items.len()).map_err(|_| {
        Error::Query(iroha_data_model::ValidationFail::InternalError(
            "alias lookup result count does not fit in u64".to_owned(),
        ))
    })?;
    let payload = routing::AliasLookupByAccountResponseDto {
        account_id: account_id.to_owned(),
        total,
        items,
        source: Some(source.to_owned()),
    };
    alias_json_response(StatusCode::OK, payload)
}
