#[cfg(all(feature = "app_api", feature = "push"))]
fn push_error_response(
    status: StatusCode,
    code: &'static str,
    message: impl Into<String>,
) -> AxResponse {
    let payload = ErrorEnvelope::new(code, message.into());
    (status, utils::NoritoBody(payload)).into_response()
}
#[cfg(all(feature = "app_api", feature = "push"))]
async fn handler_push_register_device(
    State(app): State<SharedAppState>,
    method: HttpMethod,
    uri: axum::http::Uri,
    headers: HeaderMap,
    body: Bytes,
) -> AxResponse {
    let verified =
        match push_authenticate_device_request(&app, &method, &uri, &headers, body.as_ref()) {
            Ok(verified) => verified,
            Err(response) => return response,
        };
    if let Err(response) = require_push_bridge(&app) {
        return response;
    }
    let format = match utils::typed_request_content_format(&headers) {
        Ok(format) => format,
        Err(response) => return response,
    };
    let mut req = match utils::extractors::decode_body_as_norito_or_json::<
        push::RegisterDeviceRequest,
    >(&body, format)
    {
        Ok(req) => req,
        Err(response) => return response,
    };
    let account_id = match push_authorize_device_account(&app, &verified, &req.account_id) {
        Ok(account_id) => account_id,
        Err(response) => return response,
    };
    req.account_id = account_id.to_string();
    let rate_key = format!("push:{}", req.account_id);
    if !app.push_rate_limiter.allow(&rate_key).await {
        return push_error_response(
            StatusCode::TOO_MANY_REQUESTS,
            "push_rate_limited",
            "push registrations are rate limited",
        );
    }
    let bridge = app.push.as_ref().expect("checked push presence");
    match bridge.register_device(req) {
        Ok(()) => StatusCode::ACCEPTED.into_response(),
        Err(push::PushError::Disabled) => push_error_response(
            StatusCode::SERVICE_UNAVAILABLE,
            "push_disabled",
            "push bridge disabled",
        ),
        Err(push::PushError::MissingCredentials { platform }) => push_error_response(
            StatusCode::SERVICE_UNAVAILABLE,
            "push_missing_credentials",
            format!("missing credentials for {}", platform.label()),
        ),
        Err(push::PushError::InvalidAccount(value)) => push_error_response(
            StatusCode::BAD_REQUEST,
            "invalid_account",
            format!("invalid account id `{value}`"),
        ),
        Err(push::PushError::InvalidPlatform(value)) => push_error_response(
            StatusCode::BAD_REQUEST,
            "invalid_platform",
            format!("unsupported platform `{value}`"),
        ),
        Err(push::PushError::TooManyTopics { max }) => push_error_response(
            StatusCode::BAD_REQUEST,
            "too_many_topics",
            format!("topics exceed configured maximum ({max})"),
        ),
        Err(push::PushError::EmptyToken) => push_error_response(
            StatusCode::BAD_REQUEST,
            "empty_token",
            "token must not be empty",
        ),
        Err(push::PushError::InvalidToken) => push_error_response(
            StatusCode::BAD_REQUEST,
            "invalid_token",
            "token is not valid for the selected push platform",
        ),
        Err(push::PushError::InvalidTopic { index }) => push_error_response(
            StatusCode::BAD_REQUEST,
            "invalid_topic",
            format!("topic at index {index} is invalid"),
        ),
        Err(push::PushError::DuplicateTopic { index }) => push_error_response(
            StatusCode::BAD_REQUEST,
            "duplicate_topic",
            format!("topic at index {index} duplicates an earlier topic"),
        ),
        Err(push::PushError::TopicsTooLarge { max_bytes }) => push_error_response(
            StatusCode::BAD_REQUEST,
            "topics_too_large",
            format!("topic payload exceeds the hard limit ({max_bytes} bytes)"),
        ),
        Err(push::PushError::InvalidEnvironment(value)) => push_error_response(
            StatusCode::SERVICE_UNAVAILABLE,
            "push_invalid_environment",
            format!("unsupported APNs environment `{value}`"),
        ),
        Err(push::PushError::Storage(value)) => push_error_response(
            StatusCode::INTERNAL_SERVER_ERROR,
            "push_storage_error",
            value,
        ),
    }
}
