fn parse_transaction_hash(raw: &str) -> Result<HashOf<TransactionEntrypoint>, Error> {
    raw.trim()
        .parse::<HashOf<TransactionEntrypoint>>()
        .map_err(|_| conversion_error("invalid transaction hash".to_owned()))
}
