#[derive(Debug)]
struct ZkIvmProveJobBudgetInner {
    max_bytes: usize,
    used_bytes: AtomicUsize,
    admission: std::sync::Mutex<()>,
}
struct ZkIvmProveJobSupervisorRegistration {
    sender: Option<tokio::sync::mpsc::Sender<ZkIvmProveJob>>,
    task: Option<tokio::task::JoinHandle<ToriiCriticalWorkerExit>>,
}
struct ZkIvmProveJobBudget {
    inner: Arc<ZkIvmProveJobBudgetInner>,
    supervisor: std::sync::Mutex<ZkIvmProveJobSupervisorRegistration>,
}
impl ZkIvmProveJobBudget {
    fn new(max_bytes: usize) -> Self {
        Self {
            inner: Arc::new(ZkIvmProveJobBudgetInner {
                max_bytes: max_bytes.max(1),
                used_bytes: AtomicUsize::new(0),
                admission: std::sync::Mutex::new(()),
            }),
            supervisor: std::sync::Mutex::new(ZkIvmProveJobSupervisorRegistration {
                sender: None,
                task: None,
            }),
        }
    }
    fn used_bytes(&self) -> usize {
        self.inner.used_bytes.load(AtomicOrdering::Acquire)
    }
    fn try_reserve(self: &Arc<Self>, bytes: usize) -> Option<Arc<ZkIvmProveJobReservation>> {
        self.try_reserve_bytes(bytes)
            .then(|| Arc::new(ZkIvmProveJobReservation::new(self.inner.clone(), bytes)))
    }
    fn try_reserve_bytes(&self, bytes: usize) -> bool {
        self.inner.try_reserve_bytes(bytes)
    }
}
impl ZkIvmProveJobBudgetInner {
    fn try_reserve_bytes(&self, bytes: usize) -> bool {
        if bytes > self.max_bytes {
            return false;
        }
        self.used_bytes
            .fetch_update(AtomicOrdering::AcqRel, AtomicOrdering::Acquire, |used| {
                let next = used.checked_add(bytes)?;
                (next <= self.max_bytes).then_some(next)
            })
            .is_ok()
    }
    fn release_bytes(&self, bytes: usize) {
        if bytes == 0 {
            return;
        }
        let released =
            self.used_bytes
                .fetch_update(AtomicOrdering::AcqRel, AtomicOrdering::Acquire, |used| {
                    used.checked_sub(bytes)
                });
        debug_assert!(released.is_ok(), "IVM prove job budget released twice");
        if released.is_err() {
            iroha_logger::error!(bytes, "IVM prove job budget release underflow prevented");
        }
    }
}
#[derive(Debug)]
struct ZkIvmProveJobReservation {
    budget: Arc<ZkIvmProveJobBudgetInner>,
    bytes: AtomicUsize,
}
impl ZkIvmProveJobReservation {
    fn new(budget: Arc<ZkIvmProveJobBudgetInner>, bytes: usize) -> Self {
        Self {
            budget,
            bytes: AtomicUsize::new(bytes),
        }
    }
    fn retained_bytes(&self) -> usize {
        self.bytes.load(AtomicOrdering::Acquire)
    }
    fn try_resize(&self, new_bytes: usize) -> bool {
        loop {
            let old_bytes = self.bytes.load(AtomicOrdering::Acquire);
            if new_bytes == old_bytes {
                return true;
            }
            if new_bytes > old_bytes {
                let delta = new_bytes - old_bytes;
                if !self.budget.try_reserve_bytes(delta) {
                    return false;
                }
                match self.bytes.compare_exchange(
                    old_bytes,
                    new_bytes,
                    AtomicOrdering::AcqRel,
                    AtomicOrdering::Acquire,
                ) {
                    Ok(_) => return true,
                    Err(_) => self.budget.release_bytes(delta),
                }
            } else if self
                .bytes
                .compare_exchange(
                    old_bytes,
                    new_bytes,
                    AtomicOrdering::AcqRel,
                    AtomicOrdering::Acquire,
                )
                .is_ok()
            {
                self.budget.release_bytes(old_bytes - new_bytes);
                return true;
            }
        }
    }
}
impl Drop for ZkIvmProveJobReservation {
    fn drop(&mut self) {
        let bytes = self.bytes.swap(0, AtomicOrdering::AcqRel);
        self.budget.release_bytes(bytes);
    }
}
#[derive(Clone)]
struct ZkIvmProveJobState {
    owner: AccountId,
    created_ms: u64,
    last_access_ms: u64,
    status: ZkIvmProveJobStatus,
    response_body: Bytes,
    retention: Arc<ZkIvmProveJobReservation>,
    cancel: tokio::sync::watch::Sender<bool>,
}
fn zk_ivm_prove_now_ms() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_millis() as u64
}
fn zk_ivm_prove_job_id() -> Result<String, Error> {
    zk_ivm_prove_job_id_with_rng(&mut rand::rngs::OsRng)
}
fn zk_ivm_prove_job_id_with_rng<R: rand::rand_core::TryCryptoRng>(
    rng: &mut R,
) -> Result<String, Error> {
    let mut job_id_bytes = [0_u8; 16];
    rand::rand_core::TryRngCore::try_fill_bytes(rng, &mut job_id_bytes).map_err(|error| {
        Error::Query(iroha_data_model::ValidationFail::InternalError(format!(
            "zk IVM prove job-id OS RNG failed: {error}"
        )))
    })?;
    Ok(hex::encode(job_id_bytes))
}
fn zk_ivm_synthetic_signer() -> Result<iroha_crypto::KeyPair, String> {
    // Local proof derivation replaces the signed authority before use; this
    // signer only satisfies transaction construction for non-broadcast payloads.
    iroha_crypto::KeyPair::try_from_seed(vec![0x5d; 32], iroha_crypto::Algorithm::Ed25519)
        .map_err(|err| format!("failed to derive synthetic IVM transaction signer: {err}"))
}
fn zk_ivm_prove_gc_jobs_at(
    jobs: &DashMap<String, ZkIvmProveJobState>,
    now_ms: u64,
    ttl_ms: u64,
    _max_entries: usize,
) {
    if ttl_ms > 0 {
        let expire_before = now_ms.saturating_sub(ttl_ms);
        let expired = jobs
            .iter()
            .filter_map(|entry| {
                let state = entry.value();
                (state.created_ms < expire_before)
                    .then(|| (entry.key().clone(), Arc::clone(&state.retention)))
            })
            .collect::<Vec<_>>();
        for (key, retention) in expired {
            if let Some((_key, state)) = jobs.remove_if(&key, |_, state| {
                Arc::ptr_eq(&state.retention, &retention) && state.created_ms < expire_before
            }) {
                // Best-effort cancellation. Proving (`spawn_blocking`) is not preemptible;
                // capacity remains reserved until the supervisor joins physical completion.
                let _ = state.cancel.send(true);
            }
        }
    }
    // Count and memory admission are enforced synchronously when an owner creates a job.
    // GC only expires entries by policy; it must never choose another tenant's completed result
    // merely because a global count was crossed concurrently.
}
fn zk_ivm_prove_evict_terminal_lru(
    jobs: &DashMap<String, ZkIvmProveJobState>,
    owner: &AccountId,
    exclude_job_id: Option<&str>,
) -> bool {
    let oldest = jobs
        .iter()
        .filter_map(|entry| {
            let state = entry.value();
            (matches!(
                state.status,
                ZkIvmProveJobStatus::Done | ZkIvmProveJobStatus::Error
            ) && &state.owner == owner
                && exclude_job_id != Some(entry.key().as_str()))
            .then(|| {
                (
                    entry.key().clone(),
                    state.last_access_ms,
                    Arc::clone(&state.retention),
                )
            })
        })
        .min_by_key(|(_, last_access_ms, _)| *last_access_ms);
    oldest
        .and_then(|(key, _, retention)| {
            jobs.remove_if(&key, |_, state| {
                &state.owner == owner
                    && matches!(
                        state.status,
                        ZkIvmProveJobStatus::Done | ZkIvmProveJobStatus::Error
                    )
                    && Arc::ptr_eq(&state.retention, &retention)
            })
        })
        .is_some()
}
fn zk_ivm_prove_owner_usage(
    jobs: &DashMap<String, ZkIvmProveJobState>,
    owner: &AccountId,
) -> (usize, usize) {
    jobs.iter()
        .filter(|entry| &entry.value().owner == owner)
        .fold((0_usize, 0_usize), |(count, bytes), entry| {
            (
                count.saturating_add(1),
                bytes.saturating_add(entry.value().retention.retained_bytes()),
            )
        })
}
fn zk_ivm_prove_owner_bytes_admit(
    current_bytes: usize,
    additional_bytes: usize,
    max_bytes: usize,
) -> bool {
    max_bytes == 0
        || current_bytes
            .checked_add(additional_bytes)
            .is_some_and(|next| next <= max_bytes)
}
fn zk_ivm_prove_insert_pending(
    app: &AppState,
    owner: AccountId,
    job_id: String,
    created_ms: u64,
    response_body: Bytes,
    retained_bytes: usize,
    cancel: tokio::sync::watch::Sender<bool>,
) -> Option<Arc<ZkIvmProveJobReservation>> {
    // Serialize count admission and memory reservation so simultaneous clients
    // cannot race past either aggregate cap.
    let _admission = app
        .zk_ivm_prove_job_budget
        .inner
        .admission
        .lock()
        .unwrap_or_else(std::sync::PoisonError::into_inner);
    loop {
        let (owner_count, owner_bytes) =
            zk_ivm_prove_owner_usage(app.zk_ivm_prove_jobs.as_ref(), &owner);
        let owner_count_full = app.zk_ivm_prove_job_max_entries_per_owner > 0
            && owner_count >= app.zk_ivm_prove_job_max_entries_per_owner;
        let global_count_full = app.zk_ivm_prove_job_max_entries > 0
            && app.zk_ivm_prove_jobs.len() >= app.zk_ivm_prove_job_max_entries;
        let owner_bytes_full = !zk_ivm_prove_owner_bytes_admit(
            owner_bytes,
            retained_bytes,
            app.zk_ivm_prove_job_max_retained_bytes_per_owner,
        );
        if owner_count_full || global_count_full || owner_bytes_full {
            if !zk_ivm_prove_evict_terminal_lru(app.zk_ivm_prove_jobs.as_ref(), &owner, None) {
                return None;
            }
            continue;
        }
        if let Some(reservation) = app.zk_ivm_prove_job_budget.try_reserve(retained_bytes) {
            match app.zk_ivm_prove_jobs.entry(job_id) {
                DashEntry::Vacant(entry) => {
                    entry.insert(ZkIvmProveJobState {
                        owner,
                        created_ms,
                        last_access_ms: created_ms,
                        status: ZkIvmProveJobStatus::Pending,
                        response_body,
                        retention: Arc::clone(&reservation),
                        cancel,
                    });
                    return Some(reservation);
                }
                DashEntry::Occupied(_) => {
                    // A random identifier collision must never replace another
                    // account's retained result. Release the reservation and
                    // force the caller to retry with a newly generated request.
                    return None;
                }
            }
        }
        if !zk_ivm_prove_evict_terminal_lru(app.zk_ivm_prove_jobs.as_ref(), &owner, None) {
            return None;
        }
    }
}
fn zk_ivm_prove_gc_jobs(app: &AppState) {
    zk_ivm_prove_gc_jobs_at(
        app.zk_ivm_prove_jobs.as_ref(),
        zk_ivm_prove_now_ms(),
        app.zk_ivm_prove_job_ttl_ms,
        app.zk_ivm_prove_job_max_entries,
    );
}
fn zk_ivm_prove_observe_queue_metrics(
    telemetry: &crate::routing::MaybeTelemetry,
    slots: &tokio::sync::Semaphore,
    slots_total: usize,
    inflight: &tokio::sync::Semaphore,
    inflight_total: usize,
) {
    let used_slots = slots_total.saturating_sub(slots.available_permits());
    let used_inflight = inflight_total.saturating_sub(inflight.available_permits());
    let queued = used_slots.saturating_sub(used_inflight);
    telemetry.with_metrics(|tel| {
        tel.set_torii_zk_ivm_prove_inflight(used_inflight as u64);
        tel.set_torii_zk_ivm_prove_queued(queued as u64);
    });
}
fn zk_ivm_prove_status_label(status: ZkIvmProveJobStatus) -> &'static str {
    match status {
        ZkIvmProveJobStatus::Pending => "pending",
        ZkIvmProveJobStatus::Running => "running",
        ZkIvmProveJobStatus::Done => "done",
        ZkIvmProveJobStatus::Error => "error",
    }
}
fn encode_zk_ivm_proved_json_bounded(
    proved: &iroha_data_model::transaction::IvmProved,
) -> Result<Vec<u8>, String> {
    let encoded = norito::json::to_vec(proved)
        .map_err(|err| format!("failed to encode derived IvmProved payload: {err}"))?;
    if encoded.len() > ZK_IVM_MAX_PROVED_JSON_BYTES {
        return Err(format!(
            "derived IvmProved JSON exceeds the {ZK_IVM_MAX_PROVED_JSON_BYTES}-byte API transport limit"
        ));
    }
    Ok(encoded)
}
fn encode_zk_ivm_derive_response_bounded(
    proved: &iroha_data_model::transaction::IvmProved,
) -> Result<Bytes, String> {
    let proved_json = encode_zk_ivm_proved_json_bounded(proved)?;
    const PREFIX: &[u8] = b"{\"proved\":";
    const SUFFIX: &[u8] = b"}";
    let total = PREFIX
        .len()
        .checked_add(proved_json.len())
        .and_then(|len| len.checked_add(SUFFIX.len()))
        .ok_or_else(|| "derived response length overflow".to_owned())?;
    let mut body = Vec::with_capacity(total);
    body.extend_from_slice(PREFIX);
    body.extend_from_slice(&proved_json);
    body.extend_from_slice(SUFFIX);
    Ok(Bytes::from(body))
}
fn zk_ivm_prove_job_json_dto(
    job_id: String,
    status: ZkIvmProveJobStatus,
    error: Option<String>,
    proved: Option<iroha_data_model::transaction::IvmProved>,
    attachment: Option<iroha_data_model::proof::ProofAttachment>,
) -> Result<ZkIvmProveJobJsonDto, Error> {
    let invalid_state = |message: &str| {
        Error::Query(iroha_data_model::ValidationFail::InternalError(format!(
            "invalid IVM prove job state: {message}"
        )))
    };
    match status {
        ZkIvmProveJobStatus::Pending | ZkIvmProveJobStatus::Running => {
            if error.is_some() || proved.is_some() || attachment.is_some() {
                return Err(invalid_state(
                    "pending/running jobs must not contain result material",
                ));
            }
            Ok(ZkIvmProveJobJsonDto {
                job_id,
                status: zk_ivm_prove_status_label(status).to_owned(),
                error: None,
                proved: None,
                attachment: None,
            })
        }
        ZkIvmProveJobStatus::Error => {
            if error.as_deref().is_none_or(str::is_empty)
                || proved.is_some()
                || attachment.is_some()
            {
                return Err(invalid_state(
                    "error jobs require a non-empty error and no result material",
                ));
            }
            Ok(ZkIvmProveJobJsonDto {
                job_id,
                status: zk_ivm_prove_status_label(status).to_owned(),
                error,
                proved: None,
                attachment: None,
            })
        }
        ZkIvmProveJobStatus::Done => {
            if error.is_some() {
                return Err(invalid_state("done jobs must not contain an error"));
            }
            let proved =
                proved.ok_or_else(|| invalid_state("done job is missing proved payload"))?;
            encode_zk_ivm_proved_json_bounded(&proved)
                .map_err(|message| invalid_state(&message))?;
            let attachment = attachment
                .ok_or_else(|| invalid_state("done job is missing proof attachment"))?
                .try_into()
                .map_err(|message: String| invalid_state(&message))?;
            Ok(ZkIvmProveJobJsonDto {
                job_id,
                status: zk_ivm_prove_status_label(status).to_owned(),
                error: None,
                proved: Some(proved),
                attachment: Some(attachment),
            })
        }
    }
}
fn zk_ivm_prove_bounded_error(mut error: String) -> String {
    if error.len() <= ZK_IVM_PROVE_JOB_MAX_ERROR_BYTES {
        return error;
    }
    let mut boundary = ZK_IVM_PROVE_JOB_MAX_ERROR_BYTES;
    while !error.is_char_boundary(boundary) {
        boundary -= 1;
    }
    error.truncate(boundary);
    error.push_str(" [truncated]");
    error
}
fn zk_ivm_prove_public_error(error: String) -> String {
    iroha_logger::warn!(internal_error = %error, "IVM prove job failed");
    let filesystem_failure = [
        "failed to inspect verifying key",
        "failed to open verifying key",
        "failed to read verifying key",
        "verifying key path",
        "opened verifying key",
        "failed to inspect proving key",
        "failed to open proving key",
        "failed to read proving key",
        "proving key path",
        "opened proving key",
    ]
    .iter()
    .any(|prefix| error.starts_with(prefix));
    let safe = if error == "provided `proved` payload does not match node-derived execution payload"
    {
        error
    } else if error.starts_with("failed to decode proving key archive") {
        "failed to decode proving key archive".to_owned()
    } else if filesystem_failure {
        "proof key material is unavailable or invalid".to_owned()
    } else if error.starts_with("invalid IVM header")
        || error.starts_with("ivm prove requires bytecode")
        || error.starts_with("verifying key ")
        || error.starts_with("registry verifying key ")
        || error.starts_with("generated IVM proof ")
        || error.starts_with("generated proof exceeds ")
        || error.starts_with("unsupported backend")
        || error.starts_with("stark/fri prove requested")
        || error.starts_with("IVM tooling output budget exceeded")
        || error.starts_with("derived IvmProved JSON exceeds")
    {
        error
            .chars()
            .filter(|character| !character.is_control())
            .collect()
    } else {
        "IVM proof generation failed".to_owned()
    };
    zk_ivm_prove_bounded_error(safe)
}
fn zk_ivm_prove_job_response_body(
    job_id: String,
    status: ZkIvmProveJobStatus,
    error: Option<String>,
    proved: Option<iroha_data_model::transaction::IvmProved>,
    attachment: Option<iroha_data_model::proof::ProofAttachment>,
) -> Result<Bytes, Error> {
    if status == ZkIvmProveJobStatus::Done {
        let invalid = |message: &str| {
            Error::Query(iroha_data_model::ValidationFail::InternalError(format!(
                "invalid IVM prove job state: {message}"
            )))
        };
        if error.is_some() {
            return Err(invalid("done jobs must not contain an error"));
        }
        let proved = proved.ok_or_else(|| invalid("done job is missing proved payload"))?;
        let proved_json =
            encode_zk_ivm_proved_json_bounded(&proved).map_err(|message| invalid(&message))?;
        let attachment: ZkIvmProofAttachmentJsonDto = attachment
            .ok_or_else(|| invalid("done job is missing proof attachment"))?
            .try_into()
            .map_err(|message: String| invalid(&message))?;
        let attachment_json = norito::json::to_vec(&attachment).map_err(|err| {
            Error::Query(iroha_data_model::ValidationFail::InternalError(
                err.to_string(),
            ))
        })?;
        let job_id_json = norito::json::to_vec(&job_id).map_err(|err| {
            Error::Query(iroha_data_model::ValidationFail::InternalError(
                err.to_string(),
            ))
        })?;
        const JOB_ID_PREFIX: &[u8] = b"{\"job_id\":";
        const STATUS_AND_PROVED: &[u8] = b",\"status\":\"done\",\"proved\":";
        const ATTACHMENT: &[u8] = b",\"attachment\":";
        const SUFFIX: &[u8] = b"}";
        let total = JOB_ID_PREFIX
            .len()
            .checked_add(job_id_json.len())
            .and_then(|len| len.checked_add(STATUS_AND_PROVED.len()))
            .and_then(|len| len.checked_add(proved_json.len()))
            .and_then(|len| len.checked_add(ATTACHMENT.len()))
            .and_then(|len| len.checked_add(attachment_json.len()))
            .and_then(|len| len.checked_add(SUFFIX.len()))
            .ok_or_else(|| invalid("done response length overflow"))?;
        if total > ZK_IVM_MAX_JOB_RESPONSE_BYTES {
            return Err(Error::Query(
                iroha_data_model::ValidationFail::InternalError(format!(
                    "IVM prove job response exceeds the {ZK_IVM_MAX_JOB_RESPONSE_BYTES}-byte transport limit"
                )),
            ));
        }
        let mut body = Vec::with_capacity(total);
        body.extend_from_slice(JOB_ID_PREFIX);
        body.extend_from_slice(&job_id_json);
        body.extend_from_slice(STATUS_AND_PROVED);
        body.extend_from_slice(&proved_json);
        body.extend_from_slice(ATTACHMENT);
        body.extend_from_slice(&attachment_json);
        body.extend_from_slice(SUFFIX);
        return Ok(Bytes::from(body));
    }
    let payload = zk_ivm_prove_job_json_dto(job_id, status, error, proved, attachment)?;
    let body = norito::json::to_vec(&payload).map_err(|err| {
        Error::Query(iroha_data_model::ValidationFail::InternalError(
            err.to_string(),
        ))
    })?;
    if body.len() > ZK_IVM_MAX_JOB_RESPONSE_BYTES {
        return Err(Error::Query(
            iroha_data_model::ValidationFail::InternalError(format!(
                "IVM prove job response exceeds the {ZK_IVM_MAX_JOB_RESPONSE_BYTES}-byte transport limit"
            )),
        ));
    }
    Ok(Bytes::from(body))
}
fn zk_ivm_prove_terminal_body(
    job_id: String,
    outcome: Result<
        (
            iroha_data_model::transaction::IvmProved,
            iroha_data_model::proof::ProofAttachment,
        ),
        String,
    >,
) -> (ZkIvmProveJobStatus, Bytes) {
    let encoded = match outcome {
        Ok((proved, attachment)) => zk_ivm_prove_job_response_body(
            job_id.clone(),
            ZkIvmProveJobStatus::Done,
            None,
            Some(proved),
            Some(attachment),
        )
        .map(|body| (ZkIvmProveJobStatus::Done, body)),
        Err(error) => zk_ivm_prove_job_response_body(
            job_id.clone(),
            ZkIvmProveJobStatus::Error,
            Some(zk_ivm_prove_public_error(error)),
            None,
            None,
        )
        .map(|body| (ZkIvmProveJobStatus::Error, body)),
    };
    encoded.unwrap_or_else(|error| {
        iroha_logger::error!(%error, "failed to retain IVM prove result");
        let fallback = zk_ivm_prove_job_response_body(
            job_id,
            ZkIvmProveJobStatus::Error,
            Some("proof result could not be retained".to_owned()),
            None,
            None,
        )
        .expect("bounded IVM prove error response must serialize");
        (ZkIvmProveJobStatus::Error, fallback)
    })
}
fn zk_ivm_prove_store_terminal(
    jobs: &DashMap<String, ZkIvmProveJobState>,
    budget: &ZkIvmProveJobBudget,
    owner_max_bytes: usize,
    job_id: &str,
    expected_reservation: &Arc<ZkIvmProveJobReservation>,
    status: ZkIvmProveJobStatus,
    body: Bytes,
) {
    zk_ivm_prove_store_terminal_inner(
        jobs,
        budget.inner.as_ref(),
        owner_max_bytes,
        job_id,
        expected_reservation,
        status,
        body,
    );
}
fn zk_ivm_prove_store_terminal_inner(
    jobs: &DashMap<String, ZkIvmProveJobState>,
    budget: &ZkIvmProveJobBudgetInner,
    owner_max_bytes: usize,
    job_id: &str,
    expected_reservation: &Arc<ZkIvmProveJobReservation>,
    status: ZkIvmProveJobStatus,
    body: Bytes,
) {
    let _admission = budget
        .admission
        .lock()
        .unwrap_or_else(std::sync::PoisonError::into_inner);
    let Some(owner) = jobs.get(job_id).and_then(|entry| {
        Arc::ptr_eq(&entry.retention, expected_reservation).then(|| entry.owner.clone())
    }) else {
        return;
    };
    loop {
        let (_, owner_bytes) = zk_ivm_prove_owner_usage(jobs, &owner);
        let Some(mut entry) = jobs.get_mut(job_id) else {
            return;
        };
        if !Arc::ptr_eq(&entry.retention, expected_reservation) {
            return;
        }
        let owner_bytes_without_job = owner_bytes.saturating_sub(entry.retention.retained_bytes());
        if zk_ivm_prove_owner_bytes_admit(owner_bytes_without_job, body.len(), owner_max_bytes)
            && entry.retention.try_resize(body.len())
        {
            entry.status = status;
            entry.response_body = body;
            entry.last_access_ms = zk_ivm_prove_now_ms();
            return;
        }
        drop(entry);
        if zk_ivm_prove_evict_terminal_lru(jobs, &owner, Some(job_id)) {
            continue;
        }
        let discarded = zk_ivm_prove_job_response_body(
            job_id.to_owned(),
            ZkIvmProveJobStatus::Error,
            Some("prove result discarded: retained-job memory budget exhausted".to_owned()),
            None,
            None,
        )
        .expect("bounded IVM prove capacity error must serialize");
        if let Some(mut retry_entry) = jobs.get_mut(job_id) {
            if !Arc::ptr_eq(&retry_entry.retention, expected_reservation) {
                return;
            }
            // Pending reservations have a fixed floor larger than this bounded
            // fallback, so this transition always releases memory.
            if retry_entry.retention.try_resize(discarded.len()) {
                retry_entry.status = ZkIvmProveJobStatus::Error;
                retry_entry.response_body = discarded;
                retry_entry.last_access_ms = zk_ivm_prove_now_ms();
            }
        }
        return;
    }
}
type ZkIvmProveOutcome = Result<
    (
        iroha_data_model::transaction::IvmProved,
        iroha_data_model::proof::ProofAttachment,
    ),
    String,
>;
type ZkIvmProveTerminalResult = Result<(ZkIvmProveJobStatus, Bytes), String>;
type ZkIvmProvePhysicalTask =
    tokio::task::JoinHandle<std::thread::Result<ZkIvmProveTerminalResult>>;

#[derive(Default)]
struct ZkIvmProvePhysicalJob {
    tasks: std::sync::Mutex<Vec<ZkIvmProvePhysicalTask>>,
}
impl ZkIvmProvePhysicalJob {
    fn install(&self, task: ZkIvmProvePhysicalTask) {
        self.tasks
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .push(task);
    }
    fn poll(
        &self,
        context: &mut std::task::Context<'_>,
    ) -> std::task::Poll<
        Option<Result<std::thread::Result<ZkIvmProveTerminalResult>, tokio::task::JoinError>>,
    > {
        let mut tasks = self
            .tasks
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        let Some(task) = tasks.first_mut() else {
            return std::task::Poll::Ready(None);
        };
        let result = std::future::Future::poll(std::pin::Pin::new(task), context);
        if result.is_ready() {
            tasks.remove(0);
        }
        result.map(Some)
    }
    fn has_task(&self) -> bool {
        !self
            .tasks
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .is_empty()
    }
    async fn await_started(
        &self,
        cancel_rx: &mut tokio::sync::watch::Receiver<bool>,
    ) -> (ZkIvmProveTerminalResult, bool) {
        let physical = std::future::poll_fn(|context| self.poll(context));
        tokio::pin!(physical);
        let (joined, discard) = tokio::select! {
            result = &mut physical => (result, false),
            _ = cancel_rx.changed() => {
                // Physical proving is not preemptible. Cancellation changes
                // result retention only; capacity remains held until the task exits.
                (physical.as_mut().await, true)
            }
        };
        (zk_ivm_prove_flatten_physical_join(joined), discard)
    }
    async fn join_remaining(&self) -> bool {
        let mut joined_any = false;
        while self.has_task() {
            joined_any = true;
            let joined = std::future::poll_fn(|context| self.poll(context)).await;
            if let Err(error) = zk_ivm_prove_flatten_physical_join(joined) {
                iroha_logger::warn!(%error, "recovered IVM prove wrapper joined physical work");
            }
        }
        joined_any
    }
}

fn zk_ivm_prove_flatten_physical_join(
    result: Option<Result<std::thread::Result<ZkIvmProveTerminalResult>, tokio::task::JoinError>>,
) -> ZkIvmProveTerminalResult {
    match result {
        Some(Ok(Ok(outcome))) => outcome,
        Some(Ok(Err(_))) => Err("prove job panicked".to_owned()),
        Some(Err(error)) => Err(format!("prove job could not be joined: {error}")),
        None => Err("prove job physical work was not installed".to_owned()),
    }
}

struct ZkIvmProveJobControl {
    job_id: String,
    jobs: Arc<DashMap<String, ZkIvmProveJobState>>,
    budget: Arc<ZkIvmProveJobBudgetInner>,
    owner_max_bytes: usize,
    retention: Arc<ZkIvmProveJobReservation>,
    physical: Arc<ZkIvmProvePhysicalJob>,
    telemetry: routing::MaybeTelemetry,
    slots: Arc<tokio::sync::Semaphore>,
    slots_total: usize,
    slot_permit: Option<tokio::sync::OwnedSemaphorePermit>,
    inflight: Arc<tokio::sync::Semaphore>,
    inflight_total: usize,
}
impl ZkIvmProveJobControl {
    fn observe_capacity(&self) {
        zk_ivm_prove_observe_queue_metrics(
            &self.telemetry,
            self.slots.as_ref(),
            self.slots_total,
            self.inflight.as_ref(),
            self.inflight_total,
        );
    }
    fn terminalize_wrapper_failure(&self) {
        let (status, body) = zk_ivm_prove_terminal_body(
            self.job_id.clone(),
            Err("IVM prove async wrapper panicked".to_owned()),
        );
        zk_ivm_prove_store_terminal_inner(
            self.jobs.as_ref(),
            self.budget.as_ref(),
            self.owner_max_bytes,
            &self.job_id,
            &self.retention,
            status,
            body,
        );
    }
    async fn finish(mut self, outcome: std::thread::Result<()>) {
        let physical_was_left_running = self.physical.join_remaining().await;
        if outcome.is_err() || physical_was_left_running {
            if outcome.is_err() {
                iroha_logger::warn!(
                    job_id = %self.job_id,
                    "recovered panic in IVM prove async wrapper"
                );
            } else {
                iroha_logger::error!(
                    job_id = %self.job_id,
                    "IVM prove wrapper exited without joining physical work"
                );
            }
            self.terminalize_wrapper_failure();
        }
        drop(self.slot_permit.take());
        self.observe_capacity();
    }
}

type ZkIvmProveJobFuture =
    std::pin::Pin<Box<dyn std::future::Future<Output = ()> + Send + 'static>>;
struct ZkIvmProveJob {
    control: ZkIvmProveJobControl,
    future: ZkIvmProveJobFuture,
}

fn zk_ivm_prove_cancel_active_jobs(jobs: &DashMap<String, ZkIvmProveJobState>) {
    let cancellations = jobs
        .iter()
        .filter(|entry| {
            matches!(
                entry.status,
                ZkIvmProveJobStatus::Pending | ZkIvmProveJobStatus::Running
            )
        })
        .map(|entry| entry.cancel.clone())
        .collect::<Vec<_>>();
    for cancel in cancellations {
        let _ = cancel.send(true);
    }
}

fn zk_ivm_prove_spawn_supervised_job(workers: &mut tokio::task::JoinSet<()>, job: ZkIvmProveJob) {
    let ZkIvmProveJob { control, future } = job;
    workers.spawn(async move {
        let outcome = panic_recovery::catch_async_recoverable(future).await;
        control.finish(outcome).await;
    });
}

async fn zk_ivm_prove_supervisor(
    mut receiver: tokio::sync::mpsc::Receiver<ZkIvmProveJob>,
    jobs: Arc<DashMap<String, ZkIvmProveJobState>>,
    telemetry: routing::MaybeTelemetry,
    slots: Arc<tokio::sync::Semaphore>,
    slots_total: usize,
    inflight: Arc<tokio::sync::Semaphore>,
    inflight_total: usize,
    shutdown_signal: ShutdownSignal,
) -> ToriiCriticalWorkerExit {
    let mut workers = tokio::task::JoinSet::new();
    let mut failed = false;
    loop {
        tokio::select! {
            biased;
            () = shutdown_signal.receive() => break,
            completion = workers.join_next(), if !workers.is_empty() => {
                if let Some(Err(error)) = completion {
                    iroha_logger::error!(
                        ?error,
                        "IVM prove job recovery boundary failed"
                    );
                    failed = true;
                    shutdown_signal.send();
                    break;
                }
            }
            job = receiver.recv() => match job {
                Some(job) => zk_ivm_prove_spawn_supervised_job(&mut workers, job),
                None => {
                    failed = true;
                    shutdown_signal.send();
                    break;
                }
            },
        }
    }

    receiver.close();
    zk_ivm_prove_cancel_active_jobs(jobs.as_ref());
    while let Ok(job) = receiver.try_recv() {
        zk_ivm_prove_spawn_supervised_job(&mut workers, job);
    }
    while let Some(completion) = workers.join_next().await {
        if let Err(error) = completion {
            iroha_logger::error!(
                ?error,
                "IVM prove job recovery boundary failed during shutdown"
            );
            failed = true;
        }
    }
    jobs.clear();
    zk_ivm_prove_observe_queue_metrics(
        &telemetry,
        slots.as_ref(),
        slots_total,
        inflight.as_ref(),
        inflight_total,
    );
    if failed {
        ToriiCriticalWorkerExit::UnexpectedExit
    } else {
        ToriiCriticalWorkerExit::StoppedByShutdown
    }
}

fn zk_ivm_prove_ensure_supervisor(app: &SharedAppState) {
    let mut registration = app
        .zk_ivm_prove_job_budget
        .supervisor
        .lock()
        .unwrap_or_else(std::sync::PoisonError::into_inner);
    if registration.sender.is_some() {
        return;
    }
    let (sender, receiver) = tokio::sync::mpsc::channel(app.zk_ivm_prove_slots_total);
    let task = tokio::spawn(zk_ivm_prove_supervisor(
        receiver,
        app.zk_ivm_prove_jobs.clone(),
        app.telemetry.clone(),
        app.zk_ivm_prove_slots.clone(),
        app.zk_ivm_prove_slots_total,
        app.zk_ivm_prove_inflight.clone(),
        app.zk_ivm_prove_inflight_total,
        app.shutdown_signal.clone(),
    ));
    registration.sender = Some(sender);
    registration.task = Some(task);
}

fn zk_ivm_prove_take_supervisor(
    app: &AppState,
) -> Option<tokio::task::JoinHandle<ToriiCriticalWorkerExit>> {
    app.zk_ivm_prove_job_budget
        .supervisor
        .lock()
        .unwrap_or_else(std::sync::PoisonError::into_inner)
        .task
        .take()
}

enum ZkIvmProveEnqueueError {
    NotStarted(ZkIvmProveJob),
    Full(ZkIvmProveJob),
    Closed(ZkIvmProveJob),
}

fn zk_ivm_prove_enqueue(
    app: &SharedAppState,
    job: ZkIvmProveJob,
) -> Result<(), ZkIvmProveEnqueueError> {
    let sender = app
        .zk_ivm_prove_job_budget
        .supervisor
        .lock()
        .unwrap_or_else(std::sync::PoisonError::into_inner)
        .sender
        .clone();
    let Some(sender) = sender else {
        return Err(ZkIvmProveEnqueueError::NotStarted(job));
    };
    sender.try_send(job).map_err(|error| match error {
        tokio::sync::mpsc::error::TrySendError::Full(job) => ZkIvmProveEnqueueError::Full(job),
        tokio::sync::mpsc::error::TrySendError::Closed(job) => ZkIvmProveEnqueueError::Closed(job),
    })
}
fn normalize_halo2_ipa_circuit_id(raw: &str) -> Option<String> {
    let trimmed = raw.trim();
    if trimmed.is_empty() {
        return None;
    }
    if let Some(rest) = trimmed.strip_prefix("halo2/pasta/ipa-v1/") {
        return (!rest.is_empty()).then(|| trimmed.to_string());
    }
    if let Some(rest) = trimmed.strip_prefix("halo2/pasta/") {
        return (!rest.is_empty()).then(|| format!("halo2/pasta/ipa-v1/{rest}"));
    }
    if let Some(rest) = trimmed.strip_prefix(iroha_core::zk::ZK_BACKEND_HALO2_IPA) {
        if let Some(rest) = rest.strip_prefix("::") {
            return (!rest.is_empty()).then(|| format!("halo2/pasta/ipa-v1/{rest}"));
        }
        if let Some(rest) = rest.strip_prefix(':') {
            return (!rest.is_empty()).then(|| format!("halo2/pasta/ipa-v1/{rest}"));
        }
        if let Some(rest) = rest.strip_prefix('/') {
            return (!rest.is_empty()).then(|| format!("halo2/pasta/ipa-v1/{rest}"));
        }
    }
    Some(format!("halo2/pasta/ipa-v1/{trimmed}"))
}
fn halo2_ipa_circuit_id_matches(record_id: &str, env_id: &str) -> bool {
    match (
        normalize_halo2_ipa_circuit_id(record_id),
        normalize_halo2_ipa_circuit_id(env_id),
    ) {
        (Some(rec), Some(env)) => rec == env,
        _ => record_id == env_id,
    }
}
fn normalize_stark_fri_circuit_id(backend: &str, raw: &str) -> Option<String> {
    let trimmed = raw.trim();
    if trimmed.is_empty() || trimmed == backend {
        return None;
    }
    if let Some(rest) = trimmed.strip_prefix(backend) {
        if let Some(rest) = rest.strip_prefix(':') {
            return (!rest.is_empty()).then(|| trimmed.to_string());
        }
        if let Some(rest) = rest.strip_prefix('/') {
            return (!rest.is_empty()).then(|| format!("{backend}:{rest}"));
        }
    }
    Some(format!("{backend}:{trimmed}"))
}
fn is_stark_fri_v1_backend(backend: &str) -> bool {
    iroha_data_model::zk::is_stark_fri_v1_backend_label(backend)
}
fn circuit_id_matches(backend: &str, record_id: &str, env_id: &str) -> bool {
    if backend == iroha_core::zk::ZK_BACKEND_HALO2_IPA {
        halo2_ipa_circuit_id_matches(record_id, env_id)
    } else if is_stark_fri_v1_backend(backend) {
        match (
            normalize_stark_fri_circuit_id(backend, record_id),
            normalize_stark_fri_circuit_id(backend, env_id),
        ) {
            (Some(rec), Some(env)) => rec == env,
            _ => record_id == env_id,
        }
    } else {
        record_id == env_id
    }
}
const ZK_KEY_ID_PATH_DOMAIN_V1: &[u8] = b"iroha:torii:zk-key-id:v1";
fn zk_key_store_stem(id: &iroha_data_model::proof::VerifyingKeyId) -> String {
    use sha2::Digest as _;

    fn put_component(hasher: &mut sha2::Sha256, component: &str) {
        let bytes = component.as_bytes();
        let len = u32::try_from(bytes.len())
            .expect("Norito VerifyingKeyId components fit the u32 wire-length domain");
        hasher.update(len.to_be_bytes());
        hasher.update(bytes);
    }

    let mut hasher = sha2::Sha256::new();
    hasher.update(ZK_KEY_ID_PATH_DOMAIN_V1);
    put_component(&mut hasher, id.backend.as_ref());
    put_component(&mut hasher, &id.name);
    format!("zkid-v1-{}", hex::encode(hasher.finalize()))
}
fn zk_vk_store_path(keys_dir: &Path, id: &iroha_data_model::proof::VerifyingKeyId) -> PathBuf {
    keys_dir.join(format!("{}.vk", zk_key_store_stem(id)))
}
fn zk_pk_store_path(keys_dir: &Path, id: &iroha_data_model::proof::VerifyingKeyId) -> PathBuf {
    keys_dir.join(format!("{}.pk", zk_key_store_stem(id)))
}
#[cfg(feature = "app_api")]
fn open_zk_key_file_direct(path: &Path) -> std::io::Result<std::fs::File> {
    #[cfg(windows)]
    {
        return crate::secure_file_metadata::open_direct_file(path);
    }
    #[cfg(unix)]
    {
        use std::os::unix::fs::OpenOptionsExt as _;

        return std::fs::OpenOptions::new()
            .read(true)
            .custom_flags(libc::O_NOFOLLOW | libc::O_CLOEXEC | libc::O_NONBLOCK | libc::O_NOCTTY)
            .open(path);
    }
    #[cfg(not(any(unix, windows)))]
    Err(std::io::Error::new(
        std::io::ErrorKind::Unsupported,
        "secure direct-file opening is unsupported on this platform",
    ))
}
#[cfg(feature = "app_api")]
fn read_zk_key_file_bounded(path: &Path, label: &str, max_bytes: usize) -> Result<Vec<u8>, String> {
    use crate::secure_file_metadata::{
        from_file, from_path, is_direct_file, number_of_links, same_file, unchanged,
    };
    use std::io::Read as _;

    let named_before = from_path(path).map_err(|err| {
        format!(
            "failed to inspect {label} bytes at {}: {err}",
            path.display()
        )
    })?;
    if !is_direct_file(&named_before) || number_of_links(&named_before) != Some(1) {
        return Err(format!(
            "{label} path must be a direct, single-link regular file: {}",
            path.display()
        ));
    }
    let path_len = usize::try_from(named_before.len()).unwrap_or(usize::MAX);
    if path_len > max_bytes {
        return Err(format!(
            "{label} file exceeds the {max_bytes}-byte tooling limit before read"
        ));
    }
    let mut file = open_zk_key_file_direct(path)
        .map_err(|err| format!("failed to open {label} bytes at {}: {err}", path.display()))?;
    let opened_before = from_file(&file).map_err(|err| {
        format!(
            "failed to inspect opened {label} at {}: {err}",
            path.display()
        )
    })?;
    let named_after_open = from_path(path).map_err(|err| {
        format!(
            "failed to inspect {label} bytes at {} after opening: {err}",
            path.display()
        )
    })?;
    if !is_direct_file(&opened_before)
        || !is_direct_file(&named_after_open)
        || number_of_links(&opened_before) != Some(1)
        || number_of_links(&named_after_open) != Some(1)
    {
        return Err(format!(
            "opened {label} path is not a direct, single-link regular file: {}",
            path.display()
        ));
    }
    if !same_file(&named_before, &opened_before)
        || !unchanged(&named_before, &opened_before)
        || !same_file(&opened_before, &named_after_open)
        || !unchanged(&opened_before, &named_after_open)
    {
        return Err(format!(
            "{label} path changed while it was being opened: {}",
            path.display()
        ));
    }
    let opened_len = usize::try_from(opened_before.len()).unwrap_or(usize::MAX);
    if opened_len > max_bytes {
        return Err(format!(
            "opened {label} file exceeds the {max_bytes}-byte tooling limit before read"
        ));
    }
    // Metadata can race with file growth. A bounded reader is the actual
    // allocation boundary and reads one sentinel byte to detect overflow.
    let sentinel_limit = u64::try_from(max_bytes)
        .unwrap_or(u64::MAX)
        .saturating_add(1);
    let mut bytes = Vec::with_capacity(opened_len.min(max_bytes));
    (&mut file)
        .take(sentinel_limit)
        .read_to_end(&mut bytes)
        .map_err(|err| format!("failed to read {label} bytes at {}: {err}", path.display()))?;
    if bytes.len() > max_bytes {
        return Err(format!(
            "{label} exceeds the {max_bytes}-byte tooling limit while reading"
        ));
    }
    let opened_after = from_file(&file).map_err(|err| {
        format!(
            "failed to inspect opened {label} at {} after reading: {err}",
            path.display()
        )
    })?;
    let named_after_read = from_path(path).map_err(|err| {
        format!(
            "failed to inspect {label} bytes at {} after reading: {err}",
            path.display()
        )
    })?;
    if !is_direct_file(&opened_after)
        || !is_direct_file(&named_after_read)
        || number_of_links(&opened_after) != Some(1)
        || number_of_links(&named_after_read) != Some(1)
        || !same_file(&opened_before, &opened_after)
        || !unchanged(&opened_before, &opened_after)
        || !same_file(&opened_after, &named_after_read)
        || !unchanged(&opened_after, &named_after_read)
        || !same_file(&named_before, &named_after_read)
        || !unchanged(&named_before, &named_after_read)
        || u64::try_from(bytes.len()).ok() != Some(opened_before.len())
    {
        return Err(format!(
            "{label} path changed while it was being read: {}",
            path.display()
        ));
    }
    Ok(bytes)
}
#[cfg(all(test, feature = "app_api", any(unix, windows)))]
mod zk_key_file_security_tests {
    use super::read_zk_key_file_bounded;

    #[test]
    fn bounded_key_reader_accepts_the_exact_limit_and_rejects_hard_links() {
        let directory = tempfile::tempdir().expect("create key reader fixture directory");
        let path = directory.path().join("fixture.key");
        let link = directory.path().join("fixture.link.key");
        std::fs::write(&path, b"key!").expect("write key reader fixture");

        assert_eq!(
            read_zk_key_file_bounded(&path, "verifying key", 4).expect("read exact-size key"),
            b"key!"
        );
        std::fs::hard_link(&path, &link).expect("create key fixture hard link");
        assert!(read_zk_key_file_bounded(&path, "verifying key", 4).is_err());
    }
}
#[cfg(feature = "app_api")]
fn validate_zk_ivm_fee_payment(
    fee_payment: &iroha_data_model::transaction::FeePaymentIntent,
    metadata: &iroha_data_model::metadata::Metadata,
) -> Result<(), Error> {
    let invalid = |message: String| {
        Error::Query(iroha_data_model::ValidationFail::QueryFailed(
            iroha_data_model::query::error::QueryExecutionFail::Conversion(message),
        ))
    };
    fee_payment
        .validate()
        .map_err(|err| invalid(format!("invalid fee_payment: {err}")))?;
    if fee_payment.gas_limit().is_none() {
        return Err(invalid(
            "fee_payment.gas_limit is required for IVM derive/prove".to_owned(),
        ));
    }
    for key in ["fee_sponsor", "gas_limit", "gas_asset_id"] {
        if metadata.get(key).is_some() {
            return Err(invalid(format!(
                "legacy metadata key `{key}` is not supported; use fee_payment"
            )));
        }
    }
    Ok(())
}
#[cfg(feature = "app_api")]
async fn handler_zk_ivm_derive(
    State(app): State<SharedAppState>,
    Extension(verified): Extension<crate::app_auth::VerifiedCanonicalRequest>,
    headers: axum::http::HeaderMap,
    axum::extract::ConnectInfo(remote): axum::extract::ConnectInfo<std::net::SocketAddr>,
    body: axum::body::Bytes,
) -> Result<impl IntoResponse, Error> {
    let remote_ip = remote.ip();
    enforce_proof_body_limit(&app, body.len(), "v1/zk/ivm/derive")?;
    check_proof_access(
        &app,
        &headers,
        Some(remote_ip),
        "v1/zk/ivm/derive",
        PROOF_REQUEST_RATE_COST,
        true,
    )
    .await?;
    require_proof_json_content_type(&headers, "v1/zk/ivm/derive")?;
    let mut req: ZkIvmDeriveRequestDto =
        norito::json::from_slice(body.as_ref()).map_err(|err| {
            Error::Query(iroha_data_model::ValidationFail::QueryFailed(
                iroha_data_model::query::error::QueryExecutionFail::Conversion(format!(
                    "invalid derive JSON request body: {err}"
                )),
            ))
        })?;
    require_zk_ivm_derive_authority(&req.authority, &verified)?;
    validate_zk_ivm_fee_payment(&req.fee_payment, &req.metadata)?;
    let backend = req.vk_ref.backend.as_str();
    if !iroha_core::zk::is_ivm_execution_backend(backend) {
        return Err(Error::Query(iroha_data_model::ValidationFail::QueryFailed(
            iroha_data_model::query::error::QueryExecutionFail::Conversion(
                "ivm derive requires vk_ref.backend == `halo2/ipa` or `stark/fri`".to_owned(),
            ),
        )));
    }
    if req.bytecode.as_ref().len() > ZK_IVM_MAX_BYTECODE_BYTES {
        return Err(Error::Query(iroha_data_model::ValidationFail::QueryFailed(
            iroha_data_model::query::error::QueryExecutionFail::Conversion(format!(
                "IVM bytecode exceeds the {ZK_IVM_MAX_BYTECODE_BYTES}-byte tooling limit"
            )),
        )));
    }
    let parsed = ivm::ProgramMetadata::parse(req.bytecode.as_ref()).map_err(|_| {
        Error::Query(iroha_data_model::ValidationFail::QueryFailed(
            iroha_data_model::query::error::QueryExecutionFail::Conversion(
                "invalid IVM header".to_owned(),
            ),
        ))
    })?;
    if parsed.metadata.mode & ivm::ivm_mode::ZK == 0 {
        return Err(Error::Query(iroha_data_model::ValidationFail::QueryFailed(
            iroha_data_model::query::error::QueryExecutionFail::Conversion(
                "ivm derive requires bytecode ZK mode bit (mode & ZK != 0)".to_owned(),
            ),
        )));
    }
    routing::normalize_contract_call_metadata_for_bytecode(
        &mut req.metadata,
        req.bytecode.as_ref(),
    )?;
    let retry_after_secs = app.proof_limits.retry_after.as_secs().max(1);
    let tooling_permit = app
        .zk_ivm_prove_inflight
        .clone()
        .try_acquire_owned()
        .map_err(|_| Error::ProofRateLimited {
            endpoint: "v1/zk/ivm/derive",
            retry_after_secs,
        })?;
    let network_id = *app.state.network_id_ref();
    let state = Arc::clone(&app.state);
    let ZkIvmDeriveRequestDto {
        vk_ref,
        authority,
        fee_payment,
        metadata,
        bytecode,
    } = req;
    let derive_task = panic_recovery::spawn_blocking_recoverable(
        move || -> Result<Bytes, String> {
            // The owned permit lives inside the physical blocking task, so
            // request cancellation/timeout cannot detach unaccounted VM work.
            let _tooling_permit = tooling_permit;
            let synthetic_signer = zk_ivm_synthetic_signer()?;
            let tx = iroha_data_model::transaction::signed::TransactionBuilder::new(
                network_id,
                authority.clone(),
                fee_payment,
            )
            .with_metadata(metadata)
            .with_executable(iroha_data_model::transaction::Executable::Ivm(bytecode))
            .try_sign(synthetic_signer.private_key())
            .map_err(|err| format!("failed to sign synthetic IVM derive transaction: {err}"))?
            // Proof derivation needs a stable authority, but signature validity is not required here.
            .with_authority(authority);
            // Resolve lifecycle and policy from the same snapshot used to execute the IVM.
            let view = state.query_view();
            let execution_height = zk_ivm_next_execution_height(view.height())?;
            let vk_record = view.world().verifying_keys().get(&vk_ref).ok_or_else(|| {
                format!(
                    "verifying key not found: {}::{}",
                    vk_ref.backend, vk_ref.name
                )
            })?;
            if !vk_record.is_active_at(execution_height) {
                return Err("verifying key is not active at the execution height".to_owned());
            }
            if !circuit_id_matches(
                vk_ref.backend.as_str(),
                &vk_record.circuit_id,
                iroha_core::zk::IVM_EXECUTION_V1_CIRCUIT_ID,
            ) {
                return Err(format!(
                    "verifying key circuit_id is not compatible with `ivm-execution-v1` for backend `{}` (got `{}`)",
                    vk_ref.backend, vk_record.circuit_id,
                ));
            }
            if vk_record.public_inputs_schema_hash
                != iroha_core::zk::ivm_execution_public_inputs_schema_hash()
            {
                return Err(
                    "verifying key schema hash is not compatible with `ivm-execution-v1`"
                        .to_owned(),
                );
            }
            let gas_schedule_id = vk_record
                .gas_schedule_id
                .as_deref()
                .ok_or_else(|| "verifying key missing gas_schedule_id".to_owned())?;
            let proved = iroha_core::pipeline::overlay::derive_ivm_proved_payload_from_ivm_execution_bounded_with_vk_context(
                &view,
                &tx,
                &vk_record.circuit_id,
                vk_record.version,
                Some(gas_schedule_id),
                ZK_IVM_MAX_PROVED_JSON_BYTES,
            )
            .map_err(|err| err.to_string())?;
            encode_zk_ivm_derive_response_bounded(&proved)
        },
    );
    let body = tokio::time::timeout(
        app.ivm_tooling_timeout,
        panic_recovery::join_recoverable(derive_task),
    )
    .await
    .map_err(|_| {
        Error::Query(iroha_data_model::ValidationFail::QueryFailed(
            iroha_data_model::query::error::QueryExecutionFail::Conversion(
                "IVM derive execution timed out; capacity remains reserved until the worker exits"
                    .to_owned(),
            ),
        ))
    })?
    .map_err(|err| {
        Error::Query(iroha_data_model::ValidationFail::QueryFailed(
            iroha_data_model::query::error::QueryExecutionFail::Conversion(format!(
                "derive task failed: {err}"
            )),
        ))
    })?
    .map_err(|msg| {
        iroha_logger::warn!(
            error = %msg,
            "failed to derive IVM proved executable payload"
        );
        Error::Query(iroha_data_model::ValidationFail::QueryFailed(
            iroha_data_model::query::error::QueryExecutionFail::Conversion(msg),
        ))
    })?;
    proof_cached_json_response_with_egress(
        &app,
        &headers,
        Some(remote_ip),
        "v1/zk/ivm/derive",
        body,
        true,
    )
    .await
}
#[cfg(feature = "app_api")]
async fn handler_zk_ivm_prove(
    State(app): State<SharedAppState>,
    method: axum::http::Method,
    uri: axum::http::Uri,
    headers: axum::http::HeaderMap,
    axum::extract::ConnectInfo(remote): axum::extract::ConnectInfo<std::net::SocketAddr>,
    body: axum::body::Bytes,
) -> Result<impl IntoResponse, Error> {
    let remote_ip = remote.ip();
    check_proof_access(
        &app,
        &headers,
        Some(remote_ip),
        "v1/zk/ivm/prove",
        PROOF_REQUEST_RATE_COST,
        true,
    )
    .await?;
    enforce_proof_body_limit(&app, body.len(), "v1/zk/ivm/prove")?;
    require_proof_json_content_type(&headers, "v1/zk/ivm/prove")?;
    let owner = require_signed_account_request(
        &app,
        &headers,
        &method,
        &uri,
        body.as_ref(),
        "zk_ivm_prove_auth_required",
        "signed account headers are required to create an IVM prove job",
    )?;
    zk_ivm_prove_gc_jobs(&app);
    let mut req: ZkIvmProveRequestDto = norito::json::from_slice(body.as_ref()).map_err(|err| {
        Error::Query(iroha_data_model::ValidationFail::QueryFailed(
            iroha_data_model::query::error::QueryExecutionFail::Conversion(format!(
                "invalid prove JSON request body: {err}"
            )),
        ))
    })?;
    if req.authority != owner {
        return Err(Error::Query(
            iroha_data_model::ValidationFail::NotPermitted(
                "signed account must match the IVM prove request authority".to_owned(),
            ),
        ));
    }
    validate_zk_ivm_fee_payment(&req.fee_payment, &req.metadata)?;
    let backend = req.vk_ref.backend.as_str();
    if !iroha_core::zk::is_ivm_execution_backend(backend) {
        return Err(Error::Query(iroha_data_model::ValidationFail::QueryFailed(
            iroha_data_model::query::error::QueryExecutionFail::Conversion(
                "ivm prove requires vk_ref.backend == `halo2/ipa` or `stark/fri`".to_owned(),
            ),
        )));
    }
    if req.bytecode.as_ref().len() > ZK_IVM_MAX_BYTECODE_BYTES {
        return Err(Error::Query(iroha_data_model::ValidationFail::QueryFailed(
            iroha_data_model::query::error::QueryExecutionFail::Conversion(format!(
                "IVM bytecode exceeds the {ZK_IVM_MAX_BYTECODE_BYTES}-byte tooling limit"
            )),
        )));
    }
    let parsed = ivm::ProgramMetadata::parse(req.bytecode.as_ref()).map_err(|_| {
        Error::Query(iroha_data_model::ValidationFail::QueryFailed(
            iroha_data_model::query::error::QueryExecutionFail::Conversion(
                "invalid IVM header".to_owned(),
            ),
        ))
    })?;
    if parsed.metadata.mode & ivm::ivm_mode::ZK == 0 {
        return Err(Error::Query(iroha_data_model::ValidationFail::QueryFailed(
            iroha_data_model::query::error::QueryExecutionFail::Conversion(
                "ivm prove requires bytecode ZK mode bit (mode & ZK != 0)".to_owned(),
            ),
        )));
    }
    routing::normalize_contract_call_metadata_for_bytecode(
        &mut req.metadata,
        req.bytecode.as_ref(),
    )?;
    // Queue admission is independent of physical execution admission. Only
    // inspect lightweight registry policy here; the potentially 64 MiB inline
    // key is cloned, read, and hashed later inside the admitted blocking job.
    let retry_after_secs = app.proof_limits.retry_after.as_secs().max(1);
    let slot_permit = app
        .zk_ivm_prove_slots
        .clone()
        .try_acquire_owned()
        .map_err(|_| Error::ProofRateLimited {
            endpoint: "v1/zk/ivm/prove",
            retry_after_secs,
        })?;
    {
        let view = app.state.query_view();
        let execution_height = zk_ivm_next_execution_height(view.height()).map_err(|message| {
            Error::Query(iroha_data_model::ValidationFail::QueryFailed(
                iroha_data_model::query::error::QueryExecutionFail::Conversion(message),
            ))
        })?;
        let vk_record = view
            .world()
            .verifying_keys()
            .get(&req.vk_ref)
            .ok_or_else(|| {
                Error::Query(iroha_data_model::ValidationFail::QueryFailed(
                    iroha_data_model::query::error::QueryExecutionFail::Conversion(format!(
                        "verifying key not found: {}::{}",
                        req.vk_ref.backend, req.vk_ref.name
                    )),
                ))
            })?;
        if !vk_record.is_active_at(execution_height) {
            return Err(Error::Query(iroha_data_model::ValidationFail::QueryFailed(
                iroha_data_model::query::error::QueryExecutionFail::Conversion(
                    "verifying key is not active at the execution height".to_owned(),
                ),
            )));
        }
        if !circuit_id_matches(
            backend,
            &vk_record.circuit_id,
            iroha_core::zk::IVM_EXECUTION_V1_CIRCUIT_ID,
        ) {
            return Err(Error::Query(iroha_data_model::ValidationFail::QueryFailed(
                iroha_data_model::query::error::QueryExecutionFail::Conversion(format!(
                    "verifying key circuit_id is not compatible with `ivm-execution-v1` for backend `{backend}` (got `{}`)",
                    vk_record.circuit_id,
                )),
            )));
        }
        if vk_record.public_inputs_schema_hash
            != iroha_core::zk::ivm_execution_public_inputs_schema_hash()
        {
            return Err(Error::Query(iroha_data_model::ValidationFail::QueryFailed(
                iroha_data_model::query::error::QueryExecutionFail::Conversion(
                    "verifying key schema hash is not compatible with `ivm-execution-v1`"
                        .to_owned(),
                ),
            )));
        }
        let registry_vk_len = usize::try_from(vk_record.vk_len).unwrap_or(usize::MAX);
        if registry_vk_len > ZK_IVM_MAX_VERIFYING_KEY_BYTES {
            return Err(Error::Query(iroha_data_model::ValidationFail::QueryFailed(
                iroha_data_model::query::error::QueryExecutionFail::Conversion(format!(
                    "registry verifying key length exceeds the {ZK_IVM_MAX_VERIFYING_KEY_BYTES}-byte tooling limit"
                )),
            )));
        }
        if vk_record.gas_schedule_id.is_none() {
            return Err(Error::Query(iroha_data_model::ValidationFail::QueryFailed(
                iroha_data_model::query::error::QueryExecutionFail::Conversion(
                    "verifying key missing gas_schedule_id".to_owned(),
                ),
            )));
        }
    }
    let job_id = zk_ivm_prove_job_id()?;
    let created_ms = zk_ivm_prove_now_ms();
    let ZkIvmProveRequestDto {
        vk_ref,
        authority,
        fee_payment,
        metadata,
        bytecode,
        proved: maybe_client_proved,
    } = req;
    let (cancel_tx, cancel_rx) = tokio::sync::watch::channel(false);
    let pending_body = zk_ivm_prove_job_response_body(
        job_id.clone(),
        ZkIvmProveJobStatus::Pending,
        None,
        None,
        None,
    )?;
    let pending_retained_bytes = body
        .len()
        .saturating_add(pending_body.len())
        .max(ZK_IVM_PROVE_JOB_MIN_PENDING_RESERVATION_BYTES);
    let retention = zk_ivm_prove_insert_pending(
        &app,
        owner,
        job_id.clone(),
        created_ms,
        pending_body,
        pending_retained_bytes,
        cancel_tx,
    )
    .ok_or(Error::ProofRateLimited {
        endpoint: "v1/zk/ivm/prove",
        retry_after_secs,
    })?;
    zk_ivm_prove_observe_queue_metrics(
        &app.telemetry,
        app.zk_ivm_prove_slots.as_ref(),
        app.zk_ivm_prove_slots_total,
        app.zk_ivm_prove_inflight.as_ref(),
        app.zk_ivm_prove_inflight_total,
    );
    let backend = vk_ref.backend.clone();
    let keys_dir = app.zk_prover_keys_dir.clone();
    let network_id = *app.state.network_id_ref();
    let state = Arc::clone(&app.state);
    let job_id_for_task = job_id.clone();
    let telemetry = app.telemetry.clone();
    let slots = app.zk_ivm_prove_slots.clone();
    let slots_total = app.zk_ivm_prove_slots_total;
    let inflight = app.zk_ivm_prove_inflight.clone();
    let inflight_total = app.zk_ivm_prove_inflight_total;
    let jobs = app.zk_ivm_prove_jobs.clone();
    let job_budget = app.zk_ivm_prove_job_budget.inner.clone();
    let owner_max_bytes = app.zk_ivm_prove_job_max_retained_bytes_per_owner;
    let physical = Arc::new(ZkIvmProvePhysicalJob::default());
    let control = ZkIvmProveJobControl {
        job_id: job_id.clone(),
        jobs: jobs.clone(),
        budget: job_budget.clone(),
        owner_max_bytes,
        retention: retention.clone(),
        physical: physical.clone(),
        telemetry: telemetry.clone(),
        slots: slots.clone(),
        slots_total,
        slot_permit: Some(slot_permit),
        inflight: inflight.clone(),
        inflight_total,
    };
    let jobs_for_task = jobs.clone();
    let physical_for_task = physical.clone();
    let future: ZkIvmProveJobFuture = Box::pin(async move {
        // Keep the pending request reservation alive even if a client deletes
        // the status entry while non-preemptible proving work is still running.
        let retention_for_task = retention;
        let mut cancel_rx = cancel_rx;
        if *cancel_rx.borrow() {
            return;
        }
        let Some(inflight_permit) = (tokio::select! {
            biased;
            _ = cancel_rx.changed() => None,
            permit = inflight.clone().acquire_owned() => match permit {
                Ok(permit) => Some(permit),
                Err(_) => None,
            },
        }) else {
            return;
        };
        if let Some(mut entry) = jobs_for_task.get_mut(&job_id_for_task) {
            entry.status = ZkIvmProveJobStatus::Running;
            if let Ok(body) = zk_ivm_prove_job_response_body(
                job_id_for_task.clone(),
                ZkIvmProveJobStatus::Running,
                None,
                None,
                None,
            ) {
                entry.response_body = body;
            }
        }
        zk_ivm_prove_observe_queue_metrics(
            &telemetry,
            slots.as_ref(),
            slots_total,
            inflight.as_ref(),
            inflight_total,
        );
        let job_id_for_worker = job_id_for_task.clone();
        let prove_job = panic_recovery::spawn_blocking_recoverable(move || {
            // The physical-work permit lives in this blocking task across key
            // loading, execution, proving, and terminal serialization.
            let _inflight_permit = inflight_permit;
            let outcome = (|| -> ZkIvmProveOutcome {
                // Bind verifier admission and derived execution to one committed snapshot.
                let view = state.query_view();
                let execution_height = zk_ivm_next_execution_height(view.height())?;
                let vk_record = view
                    .world()
                    .verifying_keys()
                    .get(&vk_ref)
                    .cloned()
                    .ok_or_else(|| {
                        format!(
                            "verifying key not found: {}::{}",
                            vk_ref.backend, vk_ref.name
                        )
                    })?;
                if !vk_record.is_active_at(execution_height) {
                    return Err("verifying key is not active at the execution height".to_owned());
                }
                if !circuit_id_matches(
                    backend.as_str(),
                    &vk_record.circuit_id,
                    iroha_core::zk::IVM_EXECUTION_V1_CIRCUIT_ID,
                ) {
                    return Err(format!(
                        "verifying key circuit_id is not compatible with `ivm-execution-v1` for backend `{}` (got `{}`)",
                        backend.as_str(),
                        vk_record.circuit_id,
                    ));
                }
                if vk_record.public_inputs_schema_hash
                    != iroha_core::zk::ivm_execution_public_inputs_schema_hash()
                {
                    return Err(
                        "verifying key schema hash is not compatible with `ivm-execution-v1`"
                            .to_owned(),
                    );
                }
                let registry_vk_len = usize::try_from(vk_record.vk_len).unwrap_or(usize::MAX);
                if registry_vk_len > ZK_IVM_MAX_VERIFYING_KEY_BYTES {
                    return Err(format!(
                        "registry verifying key length exceeds the {ZK_IVM_MAX_VERIFYING_KEY_BYTES}-byte tooling limit"
                    ));
                }
                let circuit_id = vk_record.circuit_id;
                let vk_version = vk_record.version;
                let gas_schedule_id = vk_record
                    .gas_schedule_id
                    .ok_or_else(|| "verifying key missing gas_schedule_id".to_owned())?;
                let max_proof_bytes = vk_record.max_proof_bytes;
                let expected_commitment = vk_record.commitment;
                let inline_vk = vk_record.key;
                let vk_box = if let Some(vk_box) = inline_vk {
                    vk_box
                } else {
                    let path = zk_vk_store_path(&keys_dir, &vk_ref);
                    let admitted_len = if registry_vk_len > 0 {
                        registry_vk_len
                    } else {
                        ZK_IVM_MAX_VERIFYING_KEY_BYTES
                    };
                    let bytes = read_zk_key_file_bounded(&path, "verifying key", admitted_len)?;
                    iroha_data_model::proof::VerifyingKeyBox::new(
                        vk_ref.backend.as_str().to_owned(),
                        bytes,
                    )
                };
                if vk_box.backend.as_str() != vk_ref.backend.as_str() {
                    return Err("verifying key backend does not match vk_ref backend".to_owned());
                }
                if vk_box.bytes.len() > ZK_IVM_MAX_VERIFYING_KEY_BYTES {
                    return Err(format!(
                        "verifying key exceeds the {ZK_IVM_MAX_VERIFYING_KEY_BYTES}-byte tooling limit"
                    ));
                }
                if registry_vk_len > 0 && vk_box.bytes.len() != registry_vk_len {
                    return Err(format!(
                        "verifying key length {} does not match registry vk_len {registry_vk_len}",
                        vk_box.bytes.len()
                    ));
                }
                let vk_commitment = iroha_core::zk::hash_vk(&vk_box);
                if vk_commitment != expected_commitment {
                    return Err("verifying key commitment mismatch".to_owned());
                }
                let parsed = ivm::ProgramMetadata::parse(bytecode.as_ref())
                    .map_err(|_| "invalid IVM header".to_owned())?;
                if parsed.metadata.mode & ivm::ivm_mode::ZK == 0 {
                    return Err(
                        "ivm prove requires bytecode ZK mode bit (mode & ZK != 0)".to_owned()
                    );
                }
                let code_hash = ivm::contract_code_hash(bytecode.as_ref());
                let synthetic_signer = zk_ivm_synthetic_signer()?;
                let tx = iroha_data_model::transaction::signed::TransactionBuilder::new(
                    network_id,
                    authority.clone(),
                    fee_payment,
                )
                .with_metadata(metadata.clone())
                .with_executable(iroha_data_model::transaction::Executable::Ivm(
                    bytecode.clone(),
                ))
                .try_sign(synthetic_signer.private_key())
                .map_err(|err| format!("failed to sign synthetic IVM prove transaction: {err}"))?
                // Proof derivation needs stable authority; signature validity is not required.
                .with_authority(authority.clone());
                let derived_proved = iroha_core::pipeline::overlay::derive_ivm_proved_payload_from_ivm_execution_bounded_with_vk_context(
                    &view,
                    &tx,
                    &circuit_id,
                    vk_version,
                    Some(&gas_schedule_id),
                    ZK_IVM_MAX_PROVED_JSON_BYTES,
                )
                .map_err(|err| err.to_string())?;
                if let Some(client_proved) = maybe_client_proved.as_ref()
                    && client_proved != &derived_proved
                {
                    return Err(
                        "provided `proved` payload does not match node-derived execution payload"
                            .to_owned(),
                    );
                }
                let overlay_bytes = norito::to_bytes(&derived_proved.overlay)
                    .map_err(|_| "failed to encode derived proved overlay".to_owned())?;
                let overlay_hash = iroha_crypto::Hash::new(&overlay_bytes);
                let proof_box = if backend.as_str() == iroha_core::zk::ZK_BACKEND_HALO2_IPA {
                    let pk_path = zk_pk_store_path(&keys_dir, &vk_ref);
                    let pk_bytes = read_zk_key_file_bounded(
                        &pk_path,
                        "proving key",
                        ZK_IVM_MAX_VERIFYING_KEY_BYTES,
                    )?;
                    iroha_core::zk::prove_halo2_ipa_ivm_execution_envelope(
                        circuit_id.as_str(),
                        &vk_box,
                        code_hash,
                        overlay_hash,
                        derived_proved.events_commitment,
                        derived_proved.gas_policy_commitment,
                        Some(pk_bytes.as_slice()),
                    )?
                } else if is_stark_fri_v1_backend(backend.as_str()) {
                    #[cfg(feature = "zk-stark")]
                    {
                        iroha_core::zk::prove_stark_fri_ivm_execution_envelope(
                            backend.as_str(),
                            circuit_id.as_str(),
                            &vk_box,
                            code_hash,
                            overlay_hash,
                            derived_proved.events_commitment,
                            derived_proved.gas_policy_commitment,
                        )?
                    }
                    #[cfg(not(feature = "zk-stark"))]
                    {
                        return Err(
                            "stark/fri prove requested but binary lacks `zk-stark`".to_owned()
                        );
                    }
                } else {
                    return Err("unsupported backend for ivm prove".to_owned());
                };
                if proof_box.bytes.len() > ZK_IVM_MAX_PROOF_BYTES {
                    return Err(format!(
                        "generated IVM proof exceeds the {ZK_IVM_MAX_PROOF_BYTES}-byte API limit"
                    ));
                }
                if max_proof_bytes > 0 && proof_box.bytes.len() > max_proof_bytes as usize {
                    return Err("generated proof exceeds verifying key max_proof_bytes".to_owned());
                }
                let mut attachment = iroha_data_model::proof::ProofAttachment::new_ref(
                    backend.clone(),
                    proof_box,
                    vk_ref,
                );
                attachment.vk_commitment = Some(vk_commitment);
                Ok((derived_proved, attachment))
            })();
            Ok::<_, String>(zk_ivm_prove_terminal_body(job_id_for_worker, outcome))
        });
        physical_for_task.install(prove_job);
        // Keep both permits and the request-memory reservation until physical
        // completion; cancellation after start is discard-only. The physical
        // handle remains recoverable by the supervisor if this wrapper panics.
        let (outcome, discard) = physical_for_task.await_started(&mut cancel_rx).await;
        if !discard {
            let (status, response_body) = outcome.unwrap_or_else(|error| {
                zk_ivm_prove_terminal_body(job_id_for_task.clone(), Err(error))
            });
            zk_ivm_prove_store_terminal_inner(
                &jobs_for_task,
                job_budget.as_ref(),
                owner_max_bytes,
                &job_id_for_task,
                &retention_for_task,
                status,
                response_body,
            );
        }
        drop(retention_for_task);
    });
    let job = ZkIvmProveJob { control, future };
    if let Err(error) = zk_ivm_prove_enqueue(&app, job) {
        let (job, response_error) = match error {
            ZkIvmProveEnqueueError::Full(job) => (
                job,
                Error::ProofRateLimited {
                    endpoint: "v1/zk/ivm/prove",
                    retry_after_secs,
                },
            ),
            ZkIvmProveEnqueueError::NotStarted(job) | ZkIvmProveEnqueueError::Closed(job) => (
                job,
                Error::AppServiceUnavailable {
                    code: "zk_ivm_prove_supervisor_unavailable",
                    message: "IVM proof generation is unavailable".to_owned(),
                },
            ),
        };
        let expected_retention = job.control.retention.clone();
        if let Some((_job_id, state)) = jobs.remove_if(&job_id, |_, state| {
            Arc::ptr_eq(&state.retention, &expected_retention)
        }) {
            let _ = state.cancel.send(true);
        }
        drop(job);
        zk_ivm_prove_observe_queue_metrics(
            &app.telemetry,
            app.zk_ivm_prove_slots.as_ref(),
            app.zk_ivm_prove_slots_total,
            app.zk_ivm_prove_inflight.as_ref(),
            app.zk_ivm_prove_inflight_total,
        );
        return Err(response_error);
    }
    let mut response = crate::utils::respond_with_format(
        ZkIvmProveJobCreatedDto { job_id },
        crate::utils::ResponseFormat::Json,
    );
    install_canonical_account_private_cache_headers(&mut response);
    Ok(response)
}
fn validate_zk_ivm_prove_job_id(job_id: &str) -> Result<(), Error> {
    if job_id.len() == 32
        && job_id
            .bytes()
            .all(|byte| byte.is_ascii_digit() || matches!(byte, b'a'..=b'f'))
    {
        return Ok(());
    }
    Err(Error::Query(iroha_data_model::ValidationFail::QueryFailed(
        iroha_data_model::query::error::QueryExecutionFail::Conversion(
            "prove job_id must be exactly 32 lowercase hexadecimal characters".to_owned(),
        ),
    )))
}
#[cfg(feature = "app_api")]
async fn handler_zk_ivm_prove_get(
    State(app): State<SharedAppState>,
    method: axum::http::Method,
    uri: axum::http::Uri,
    headers: axum::http::HeaderMap,
    axum::extract::ConnectInfo(remote): axum::extract::ConnectInfo<std::net::SocketAddr>,
    job_id: axum::extract::Path<String>,
) -> Result<impl IntoResponse, Error> {
    let remote_ip = remote.ip();
    check_proof_access(
        &app,
        &headers,
        Some(remote_ip),
        "v1/zk/ivm/prove/{job_id}",
        1,
        true,
    )
    .await?;
    let owner = require_signed_account_request(
        &app,
        &headers,
        &method,
        &uri,
        &[],
        "zk_ivm_prove_auth_required",
        "signed account headers are required to read an IVM prove job",
    )?;
    zk_ivm_prove_gc_jobs(&app);
    let job_id = job_id.0;
    validate_zk_ivm_prove_job_id(&job_id)?;
    let Some(entry) = app
        .zk_ivm_prove_jobs
        .get(&job_id)
        .filter(|entry| &entry.value().owner == &owner)
    else {
        let mut response = (
            StatusCode::NOT_FOUND,
            "prove job not found; submit a new job via POST /v1/zk/ivm/prove",
        )
            .into_response();
        install_canonical_account_private_cache_headers(&mut response);
        return Ok(response);
    };
    let body = entry.response_body.clone();
    drop(entry);
    let mut response = proof_cached_json_response_with_egress(
        &app,
        &headers,
        Some(remote_ip),
        "v1/zk/ivm/prove/{job_id}",
        body,
        true,
    )
    .await?;
    install_canonical_account_private_cache_headers(&mut response);
    // A throttled poll must not pin a large terminal response in the LRU.
    if let Some(mut entry) = app.zk_ivm_prove_jobs.get_mut(&job_id) {
        if &entry.value().owner == &owner {
            entry.last_access_ms = zk_ivm_prove_now_ms();
        }
    }
    Ok(response)
}
#[cfg(feature = "app_api")]
async fn handler_zk_ivm_prove_delete(
    State(app): State<SharedAppState>,
    method: axum::http::Method,
    uri: axum::http::Uri,
    headers: axum::http::HeaderMap,
    axum::extract::ConnectInfo(remote): axum::extract::ConnectInfo<std::net::SocketAddr>,
    job_id: axum::extract::Path<String>,
) -> Result<impl IntoResponse, Error> {
    let remote_ip = remote.ip();
    check_proof_access(
        &app,
        &headers,
        Some(remote_ip),
        "v1/zk/ivm/prove/{job_id}",
        1,
        true,
    )
    .await?;
    let owner = require_signed_account_request(
        &app,
        &headers,
        &method,
        &uri,
        &[],
        "zk_ivm_prove_auth_required",
        "signed account headers are required to delete an IVM prove job",
    )?;
    zk_ivm_prove_gc_jobs(&app);
    let job_id = job_id.0;
    validate_zk_ivm_prove_job_id(&job_id)?;
    let Some((_key, state)) = app
        .zk_ivm_prove_jobs
        .remove_if(&job_id, |_, state| &state.owner == &owner)
    else {
        let mut response = (StatusCode::NOT_FOUND, "prove job not found").into_response();
        install_canonical_account_private_cache_headers(&mut response);
        return Ok(response);
    };
    let _ = state.cancel.send(true);
    let mut response = crate::utils::respond_with_format(
        ZkIvmProveJobCreatedDto { job_id },
        crate::utils::ResponseFormat::Json,
    );
    install_canonical_account_private_cache_headers(&mut response);
    Ok(response)
}
