fn torii_account_assets_read_routes(
    app: &AppState,
    target_account: &AccountId,
    caller: Option<&AccountId>,
    use_target_account_routes: bool,
) -> Result<Vec<RoutingDecision>, Response> {
    torii_account_read_routes(app, target_account, caller, use_target_account_routes)
}
#[cfg(feature = "app_api")]
fn torii_account_permissions_read_routes(
    app: &AppState,
    target_account: &AccountId,
    caller: Option<&AccountId>,
    use_target_account_routes: bool,
) -> Result<Vec<RoutingDecision>, Response> {
    torii_account_read_routes(app, target_account, caller, use_target_account_routes)
}
#[cfg(feature = "app_api")]
fn torii_account_permissions_route_scope(
    target_account: &AccountId,
    caller: Option<&AccountId>,
    use_target_account_routes: bool,
) -> ToriiFanoutRouteScopeV1 {
    torii_account_read_route_scope(target_account, caller, use_target_account_routes)
}
fn torii_nexus_route(app: &AppState) -> Result<RoutingDecision, Response> {
    resolve_torii_route_for_dataspace_id(app, DataSpaceId::UNIVERSAL).map_err(|error| {
        torii_proxy_error_response(
            StatusCode::SERVICE_UNAVAILABLE,
            "route_unavailable",
            format!("failed to resolve Nexus fanout route: {error}"),
        )
    })
}
fn parse_internal_fanout_account_id(
    account_id: &str,
    context: &'static str,
) -> Result<AccountId, Response> {
    if account_id.trim() != account_id {
        return Err(torii_proxy_error_response(
            StatusCode::BAD_REQUEST,
            "invalid_proxy_request",
            format!("invalid {context} account id: surrounding whitespace is not allowed"),
        ));
    }
    AccountId::parse_encoded(account_id).map_err(|error| {
        torii_proxy_error_response(
            StatusCode::BAD_REQUEST,
            "invalid_proxy_request",
            format!("invalid {context} account id `{account_id}`: {error}"),
        )
    })
}
#[cfg(feature = "app_api")]
fn torii_fanout_scope_routes(
    app: &AppState,
    scope: &ToriiFanoutRouteScopeV1,
) -> Result<Vec<RoutingDecision>, Response> {
    match scope {
        ToriiFanoutRouteScopeV1::AllDataspaces => Ok(torii_all_dataspace_routes(app)),
        ToriiFanoutRouteScopeV1::TargetAccount { account_id, .. } => {
            let account_id = parse_internal_fanout_account_id(account_id, "target")?;
            torii_target_account_routes(app, &account_id)
        }
        ToriiFanoutRouteScopeV1::VisibleAccount { caller_account_id } => {
            let caller = match caller_account_id {
                Some(account_id) => Some(parse_internal_fanout_account_id(account_id, "caller")?),
                None => None,
            };
            Ok(torii_visible_account_read_routes(app, caller.as_ref()))
        }
    }
}
#[cfg(feature = "app_api")]
fn torii_account_read_route_scope(
    target_account: &AccountId,
    caller: Option<&AccountId>,
    use_target_account_routes: bool,
) -> ToriiFanoutRouteScopeV1 {
    if use_target_account_routes {
        ToriiFanoutRouteScopeV1::TargetAccount {
            account_id: target_account.to_string(),
            caller_account_id: caller.map(ToString::to_string),
        }
    } else {
        ToriiFanoutRouteScopeV1::VisibleAccount {
            caller_account_id: caller.map(ToString::to_string),
        }
    }
}
fn torii_all_dataspace_routes(app: &AppState) -> Vec<RoutingDecision> {
    let state_view = app.state.view();
    let nexus = state_view.nexus();
    let mut routes =
        BTreeMap::<iroha_data_model::nexus::DataSpaceId, iroha_data_model::nexus::LaneId>::new();
    for lane in nexus.lane_catalog.lanes() {
        if !torii_lane_active_for_routing(app, lane.id) {
            continue;
        }
        routes
            .entry(lane.dataspace_id)
            .and_modify(|current| {
                if lane.id < *current {
                    *current = lane.id;
                }
            })
            .or_insert(lane.id);
    }
    routes
        .into_iter()
        .map(|(dataspace_id, lane_id)| RoutingDecision::new(lane_id, dataspace_id))
        .collect()
}
#[cfg(any(feature = "app_api", feature = "connect"))]
fn torii_proxy_response_format(format: ResponseFormat) -> ToriiProxyResponseFormatV1 {
    match format {
        ResponseFormat::Norito => ToriiProxyResponseFormatV1::Norito,
        ResponseFormat::Json => ToriiProxyResponseFormatV1::Json,
    }
}
#[cfg(any(feature = "app_api", feature = "connect"))]
fn response_format_from_torii_proxy(format: ToriiProxyResponseFormatV1) -> ResponseFormat {
    match format {
        ToriiProxyResponseFormatV1::Norito => ResponseFormat::Norito,
        ToriiProxyResponseFormatV1::Json => ResponseFormat::Json,
    }
}
fn current_torii_queue_pressure(app: &AppState) -> queue::QueuePressureSnapshot {
    let block_time = app.state.sumeragi_block_cadence();
    app.queue
        .refresh_pressure_budget_from_block_time(block_time)
}
fn current_torii_backpressure(app: &AppState) -> queue::BackpressureState {
    current_torii_queue_pressure(app).into_backpressure()
}
#[cfg(feature = "connect")]
fn try_new_torii_proxy_session_id_with_rng<R>(rng: &mut R) -> Result<Hash, ToriiBuildError>
where
    R: rand::rand_core::TryCryptoRng + ?Sized,
{
    use rand::rand_core::TryRngCore as _;

    let mut nonce = [0_u8; Hash::LENGTH];
    rng.try_fill_bytes(&mut nonce).map_err(|error| {
        ToriiBuildError::component_initialization(
            "torii_proxy.session_entropy",
            format!("operating-system randomness is unavailable: {error}"),
        )
    })?;
    Ok(Hash::new(nonce))
}
#[cfg(feature = "connect")]
fn try_new_torii_proxy_session_id() -> Result<Hash, ToriiBuildError> {
    try_new_torii_proxy_session_id_with_rng(&mut rand::rngs::OsRng)
}
#[cfg(all(test, feature = "connect"))]
fn new_torii_proxy_session_id() -> Hash {
    try_new_torii_proxy_session_id()
        .expect("test Torii proxy process-session entropy must be available")
}
#[cfg(all(test, feature = "connect"))]
mod torii_proxy_session_id_tests {
    use super::*;

    #[derive(Debug)]
    struct FailingEntropy;

    impl core::fmt::Display for FailingEntropy {
        fn fmt(&self, formatter: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
            formatter.write_str("injected entropy failure")
        }
    }

    struct FailingRng;

    impl rand::rand_core::TryRngCore for FailingRng {
        type Error = FailingEntropy;

        fn try_next_u32(&mut self) -> core::result::Result<u32, Self::Error> {
            Err(FailingEntropy)
        }

        fn try_next_u64(&mut self) -> core::result::Result<u64, Self::Error> {
            Err(FailingEntropy)
        }

        fn try_fill_bytes(&mut self, _dst: &mut [u8]) -> core::result::Result<(), Self::Error> {
            Err(FailingEntropy)
        }
    }

    impl rand::rand_core::TryCryptoRng for FailingRng {}

    #[test]
    fn process_session_entropy_failure_is_a_startup_error() {
        let error = try_new_torii_proxy_session_id_with_rng(&mut FailingRng)
            .expect_err("entropy failure must not unwind");
        assert!(matches!(
            error,
            ToriiBuildError::ComponentInitialization {
                component: "torii_proxy.session_entropy",
                ..
            }
        ));
    }
}
#[cfg(feature = "connect")]
type OwnedToriiProxyRequestIdPreimage = (&'static str, Hash, PeerId, u64, ToriiProxyRequestKindV1);
/// Borrowed wire-equivalent of [`OwnedToriiProxyRequestIdPreimage`].
///
/// Each tuple field keeps the historical length prefix, but the potentially
/// large request arm is streamed directly instead of being cloned merely to
/// derive its request id.
#[cfg(feature = "connect")]
#[repr(C)]
struct BorrowedToriiProxyRequestIdPreimage<'a> {
    process_session_id: &'a Hash,
    local_peer_id: &'a PeerId,
    sequence: u64,
    request: &'a ToriiProxyRequestKindV1,
}
#[cfg(feature = "connect")]
impl norito::core::NoritoSerialize for BorrowedToriiProxyRequestIdPreimage<'_> {
    fn schema_hash() -> [u8; 16] {
        <OwnedToriiProxyRequestIdPreimage as norito::core::NoritoSerialize>::schema_hash()
    }
    fn serialize(&self, writer: &mut norito::core::Encoder<'_>) -> Result<(), norito::core::Error> {
        const DOMAIN: &str = "torii:proxy:v1";
        let mut scratch = norito::core::SmallBuf::<384>::new();
        norito::core::write_len_prefixed_exact(writer, &DOMAIN, &mut scratch)?;
        norito::core::write_len_prefixed_exact(writer, self.process_session_id, &mut scratch)?;
        norito::core::write_len_prefixed_exact(writer, self.local_peer_id, &mut scratch)?;
        norito::core::write_len_prefixed_exact(writer, &self.sequence, &mut scratch)?;
        if self.request.encoded_len_exact().is_none() {
            // The generic fallback stages the entire request field. Request-id
            // derivation is admitted only when the request enum can use the
            // proven direct-streaming path.
            return Err(norito::core::Error::LengthMismatch);
        }
        norito::core::write_len_prefixed_exact(writer, self.request, &mut scratch)?;
        Ok(())
    }
    fn encoded_len_exact(&self) -> Option<usize> {
        fn field(value: &dyn norito::core::NoritoSerialize) -> Option<usize> {
            let bytes = value.encoded_len_exact()?;
            norito::core::len_prefix_len(bytes).checked_add(bytes)
        }
        const DOMAIN: &str = "torii:proxy:v1";
        [
            field(&DOMAIN)?,
            field(self.process_session_id)?,
            field(self.local_peer_id)?,
            field(&self.sequence)?,
            field(self.request)?,
        ]
        .into_iter()
        .try_fold(0_usize, usize::checked_add)
    }
}
#[cfg(feature = "connect")]
fn torii_proxy_request_id_for_session_sequence(
    process_session_id: &Hash,
    local_peer_id: &PeerId,
    sequence: u64,
    request: &ToriiProxyRequestKindV1,
) -> Hash {
    let preimage = BorrowedToriiProxyRequestIdPreimage {
        process_session_id,
        local_peer_id,
        sequence,
        request,
    };
    debug_assert_eq!(
        core::mem::align_of::<BorrowedToriiProxyRequestIdPreimage<'_>>(),
        core::mem::align_of::<OwnedToriiProxyRequestIdPreimage>(),
        "borrowed proxy request-id preimage must preserve frame padding",
    );
    Hash::new(
        norito::to_bytes(&preimage).expect("Torii proxy request id encoding should be infallible"),
    )
}
#[cfg(feature = "connect")]
fn next_torii_proxy_request_id(
    app: &AppState,
    local_peer_id: &PeerId,
    request: &ToriiProxyRequestKindV1,
) -> Result<Hash, &'static str> {
    let sequence = app
        .torii_proxy_sequence
        .fetch_update(
            std::sync::atomic::Ordering::Relaxed,
            std::sync::atomic::Ordering::Relaxed,
            |sequence| sequence.checked_add(1),
        )
        .map_err(|_| "Torii proxy request sequence is exhausted")?;
    Ok(torii_proxy_request_id_for_session_sequence(
        &app.torii_proxy_session_id,
        local_peer_id,
        sequence,
        request,
    ))
}
#[cfg(feature = "connect")]
fn queue_plan_synced_proxy_request_id(
    app: &AppState,
    request: &ToriiProxyRequestKindV1,
) -> Option<Hash> {
    match request {
        ToriiProxyRequestKindV1::SubmitTransaction {
            transaction,
            admission: ToriiProxyTransactionAdmissionV1::QueuePlanSynced,
            ..
        } => Some(queue_plan_synced_proxy_request_id_for_entrypoint(
            app,
            transaction.hash(),
        )),
        _ => None,
    }
}
#[cfg(feature = "connect")]
fn queue_plan_synced_proxy_request_id_for_entrypoint(
    app: &AppState,
    entrypoint_hash: HashOf<TransactionEntrypoint>,
) -> Hash {
    iroha_core::torii_proxy::queue_plan_synced_request_id(
        app.state.network_id_ref(),
        entrypoint_hash,
    )
}
#[cfg(feature = "connect")]
fn torii_proxy_hedge_delay(app: &AppState) -> Duration {
    app.state
        .sumeragi_block_cadence()
        .checked_div(2)
        .unwrap_or(Duration::ZERO)
        .clamp(Duration::from_millis(50), Duration::from_millis(250))
}
#[cfg(feature = "connect")]
fn torii_proxy_candidate_launch_delay(
    queue_plan_synced: bool,
    hedge_delay: Duration,
    candidate_index: usize,
) -> Duration {
    if queue_plan_synced || candidate_index == 0 {
        return Duration::ZERO;
    }
    hedge_delay.saturating_mul(u32::try_from(candidate_index).unwrap_or(u32::MAX))
}
#[cfg(feature = "connect")]
async fn prune_completed_torii_proxy_requests(app: &SharedAppState) {
    let now = Instant::now();
    let mut completed = app.torii_proxy_completed.lock().await;
    completed.prune(now);
}
#[cfg(feature = "connect")]
async fn register_torii_proxy_pending_waiter(
    app: &SharedAppState,
    pending_key: (Hash, PeerId),
    sender: tokio::sync::oneshot::Sender<ToriiProxyHttpResponseV1>,
    max_body_bytes: usize,
    strict_queue_plan_synced: bool,
) -> Arc<()> {
    let waiter_token = Arc::new(());
    app.torii_proxy_pending
        .lock()
        .await
        .entry(pending_key)
        .or_default()
        .push(PendingToriiProxyRequest {
            waiter_token: Arc::clone(&waiter_token),
            sender,
            max_body_bytes,
            strict_queue_plan_synced,
        });
    waiter_token
}
#[cfg(feature = "connect")]
async fn remove_torii_proxy_pending_waiter(
    app: &SharedAppState,
    pending_key: &(Hash, PeerId),
    waiter_token: &Arc<()>,
) {
    let mut pending = app.torii_proxy_pending.lock().await;
    let remove_key = pending.get_mut(pending_key).is_some_and(|waiters| {
        waiters.retain(|waiter| !Arc::ptr_eq(&waiter.waiter_token, waiter_token));
        waiters.is_empty()
    });
    if remove_key {
        pending.remove(pending_key);
    }
}
#[cfg(feature = "connect")]
async fn mark_torii_proxy_request_completed(app: &SharedAppState, request_id: Hash) {
    // A deterministic semantic request id can have multiple independent local callers. Their
    // response waiters are removed by their own response or attempt cleanup, never by another
    // caller completing the same request id.
    let mut completed = app.torii_proxy_completed.lock().await;
    completed.record(request_id, Instant::now());
}
#[cfg(feature = "connect")]
fn new_torii_proxy_request(
    app: &AppState,
    request: ToriiProxyRequestKindV1,
) -> Result<ToriiProxyRequestV1, Response> {
    let Some(local_peer_id) = app.local_peer_id.as_ref() else {
        return Err(torii_proxy_error_response(
            StatusCode::SERVICE_UNAVAILABLE,
            "route_unavailable",
            "Torii ingress routing requires a configured local peer id",
        ));
    };
    let request_id = match queue_plan_synced_proxy_request_id(app, &request) {
        Some(request_id) => request_id,
        None => next_torii_proxy_request_id(app, local_peer_id, &request).map_err(|error| {
            torii_proxy_error_response(StatusCode::SERVICE_UNAVAILABLE, "route_unavailable", error)
        })?,
    };
    if let ToriiProxyRequestKindV1::SubmitTransaction {
        admission: ToriiProxyTransactionAdmissionV1::QueuePlanSynced,
        admission_binding: Some(binding),
        ..
    } = &request
        && binding.request_id != request_id
    {
        return Err(torii_proxy_error_response(
            StatusCode::BAD_REQUEST,
            "invalid_proxy_request",
            "QueuePlanSynced binding request ID differs from its deterministic proxy identity",
        ));
    }
    let now_unix_ms = torii_proxy_now_unix_ms().map_err(|error| {
        torii_proxy_error_response(StatusCode::SERVICE_UNAVAILABLE, "route_unavailable", error)
    })?;
    let deadline_unix_ms = now_unix_ms
        .checked_add(
            u64::try_from(TORII_PROXY_EXECUTION_BUDGET.as_millis())
                .expect("the fixed proxy execution budget fits u64 milliseconds"),
        )
        .ok_or_else(|| {
            torii_proxy_error_response(
                StatusCode::SERVICE_UNAVAILABLE,
                "route_unavailable",
                "Torii proxy absolute deadline overflowed",
            )
        })?;
    Ok(ToriiProxyRequestV1 {
        schema_version: TORII_PROXY_REQUEST_VERSION_V1,
        request_id,
        deadline_unix_ms,
        hop_count: 1,
        max_hops: TORII_PROXY_DEFAULT_MAX_HOPS,
        visited_peer_ids: vec![local_peer_id.clone()],
        request,
    })
}
#[cfg(feature = "connect")]
fn torii_proxy_now_unix_ms() -> Result<u64, &'static str> {
    let millis = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map_err(|_| "system clock is before the Unix epoch")?
        .as_millis();
    u64::try_from(millis).map_err(|_| "system clock milliseconds exceed the proxy wire field")
}
#[cfg(feature = "connect")]
fn torii_proxy_remaining_budget(
    deadline_unix_ms: u64,
    now_unix_ms: u64,
) -> Result<Duration, &'static str> {
    let remaining_ms = deadline_unix_ms
        .checked_sub(now_unix_ms)
        .ok_or("Torii proxy request deadline has expired")?;
    if remaining_ms == 0 {
        return Err("Torii proxy request deadline has expired");
    }
    let remaining = Duration::from_millis(remaining_ms);
    if remaining > TORII_PROXY_MAX_DEADLINE_HORIZON {
        return Err("Torii proxy request deadline exceeds the permitted horizon");
    }
    Ok(remaining)
}
#[cfg(feature = "connect")]
fn validate_torii_proxy_deadline(deadline_unix_ms: u64) -> Result<Duration, &'static str> {
    torii_proxy_remaining_budget(deadline_unix_ms, torii_proxy_now_unix_ms()?)
}
#[cfg(test)]
fn torii_proxy_test_deadline_unix_ms() -> u64 {
    torii_proxy_now_unix_ms()
        .expect("test clock must be representable as Unix milliseconds")
        .checked_add(60_000)
        .expect("test Torii proxy deadline must fit u64")
}
#[cfg(feature = "connect")]
fn forwarded_torii_proxy_request_owned(
    mut request: ToriiProxyRequestV1,
    local_peer_id: &PeerId,
) -> ToriiProxyRequestV1 {
    if !request
        .visited_peer_ids
        .iter()
        .any(|peer_id| peer_id == local_peer_id)
    {
        request.visited_peer_ids.push(local_peer_id.clone());
    }
    request.schema_version = TORII_PROXY_REQUEST_VERSION_V1;
    request.hop_count = request.hop_count.saturating_add(1);
    request
}
#[cfg(test)]
fn forwarded_torii_proxy_request(
    request: &ToriiProxyRequestV1,
    local_peer_id: &PeerId,
) -> ToriiProxyRequestV1 {
    forwarded_torii_proxy_request_owned(request.clone(), local_peer_id)
}
fn insert_routed_by_header(response: &mut Response, routed_by: &'static str) {
    response.headers_mut().insert(
        HeaderName::from_static("x-iroha-routed-by"),
        HeaderValue::from_static(routed_by),
    );
}
fn insert_usize_header(response: &mut Response, name: &'static str, value: usize) {
    if let Ok(header) = HeaderValue::from_str(&value.to_string()) {
        response
            .headers_mut()
            .insert(HeaderName::from_static(name), header);
    }
}
#[derive(Clone, Debug, PartialEq, Eq)]
enum SignedQueryScope {
    PublicControlPlane,
    LocalReplicated,
    AuthorityRouted,
    CrossDataspaceFanout,
    TargetAccount(AccountId),
    TargetAlias(iroha_data_model::account::AccountAlias),
    TargetDomain(iroha_data_model::domain::DomainId),
}
fn torii_signed_query_permission_denied_response(
    authority: &AccountId,
    denied_routes: usize,
) -> Response {
    torii_proxy_error_response(
        StatusCode::FORBIDDEN,
        "permission_denied",
        format!(
            "signed query authority {authority} cannot read {denied_routes} requested restricted dataspace route(s)"
        ),
    )
}
fn torii_intersect_signed_query_routes(
    routes: Vec<RoutingDecision>,
    allowed_routes: Vec<RoutingDecision>,
) -> (Vec<RoutingDecision>, usize) {
    let allowed_dataspaces = allowed_routes
        .into_iter()
        .map(|route| route.dataspace_id)
        .collect::<BTreeSet<_>>();
    let mut allowed = Vec::new();
    let mut denied = 0usize;
    for route in routes {
        if allowed_dataspaces.contains(&route.dataspace_id) {
            allowed.push(route);
        } else {
            denied = denied.saturating_add(1);
        }
    }
    (allowed, denied)
}
fn torii_authorize_signed_query_routes(
    app: &AppState,
    request: &impl SignedQueryScopeInput,
    scope: &SignedQueryScope,
    routes: Vec<RoutingDecision>,
) -> Result<Vec<RoutingDecision>, Response> {
    let authority = &request.request_with_authority().authority;
    match scope {
        SignedQueryScope::PublicControlPlane => Ok(Vec::new()),
        SignedQueryScope::LocalReplicated => Ok(routes),
        SignedQueryScope::CrossDataspaceFanout => {
            let (allowed, denied) = torii_intersect_signed_query_routes(
                routes,
                torii_global_signed_query_read_routes(app, authority),
            );
            if denied == 0 {
                Ok(allowed)
            } else {
                Err(torii_signed_query_permission_denied_response(
                    authority, denied,
                ))
            }
        }
        SignedQueryScope::AuthorityRouted => {
            let (allowed, denied) = torii_intersect_signed_query_routes(
                routes,
                torii_global_signed_query_read_routes(app, authority),
            );
            if denied == 0 {
                Ok(allowed)
            } else {
                Err(torii_signed_query_permission_denied_response(
                    authority, denied,
                ))
            }
        }
        SignedQueryScope::TargetAccount(target) => {
            let readable_routes = if torii_same_account_read_identity(app, authority, target) {
                torii_visible_account_read_routes(app, Some(authority))
            } else {
                torii_global_signed_query_read_routes(app, authority)
            };
            let (allowed, denied) = torii_intersect_signed_query_routes(routes, readable_routes);
            if denied == 0 {
                Ok(allowed)
            } else {
                Err(torii_signed_query_permission_denied_response(
                    authority, denied,
                ))
            }
        }
        SignedQueryScope::TargetAlias(alias) => {
            let state_view = app.state.view();
            if torii_authority_can_resolve_account_alias(state_view.world(), authority, alias) {
                Ok(routes)
            } else {
                Err(torii_signed_query_permission_denied_response(
                    authority,
                    routes.len().max(1),
                ))
            }
        }
        SignedQueryScope::TargetDomain(_) => {
            let (allowed, denied) = torii_intersect_signed_query_routes(
                routes,
                torii_global_signed_query_read_routes(app, authority),
            );
            if denied == 0 {
                Ok(allowed)
            } else {
                Err(torii_signed_query_permission_denied_response(
                    authority, denied,
                ))
            }
        }
    }
}
fn payload_matches_query<Query>(payload: &[u8]) -> bool
where
    Query: norito::codec::Decode + norito::codec::Encode,
{
    let mut cursor = payload;
    let Ok(query) = <Query as norito::codec::Decode>::decode(&mut cursor) else {
        return false;
    };
    cursor.is_empty() && norito::codec::Encode::encode(&query) == payload
}
fn canonical_iterable_query_parts(
    query: &iroha_data_model::query::QueryWithParams,
) -> (iroha_data_model::query::QueryItemKind, &[u8], &[u8], &[u8]) {
    query.parts()
}
fn is_trigger_inventory_query(query: &iroha_data_model::query::QueryWithParams) -> bool {
    use iroha_data_model::query::{
        QueryItemKind,
        trigger::prelude::{FindActiveTriggerIds, FindTriggers},
    };
    match query.item {
        QueryItemKind::Trigger => payload_matches_query::<FindTriggers>(&query.query_payload),
        QueryItemKind::TriggerId => {
            payload_matches_query::<FindActiveTriggerIds>(&query.query_payload)
        }
        _ => false,
    }
}
fn is_public_control_plane_query(query: &iroha_data_model::query::QueryWithParams) -> bool {
    use iroha_data_model::query::{QueryItemKind, peer::prelude::FindPeers};
    query.item == QueryItemKind::PeerId && payload_matches_query::<FindPeers>(&query.query_payload)
}
fn decode_query_payload<Query>(payload: &[u8]) -> Option<Query>
where
    Query: norito::codec::Decode + norito::codec::Encode,
{
    let mut cursor = payload;
    let query = <Query as norito::codec::Decode>::decode(&mut cursor).ok()?;
    (cursor.is_empty() && norito::codec::Encode::encode(&query) == payload).then_some(query)
}
fn decode_query_payload_bounded<Query>(
    payload: &[u8],
    memory_limits: QueryScopeMemoryLimits,
) -> Result<Option<Query>, Response>
where
    Query: norito::codec::Decode + norito::codec::Encode + norito::core::NoritoSerialize,
{
    let limits = memory_limits.decode_limits(payload.len())?;
    if payload.len() > limits.max_total_allocated_bytes() {
        return Err(torii_proxy_error_response(
            StatusCode::PAYLOAD_TOO_LARGE,
            "query_capacity_exceeded",
            "signed-query routing scope payload exceeds its bounded decode allowance",
        ));
    }
    let query = match norito::with_decode_limits(limits, || {
        // Decode directly from the already-owned erased payload. `Decode::decode`
        // first copies the complete input with `read_to_end`, before the schema
        // decoder can charge that allocation; the slice entry point keeps any
        // alignment copy inside the active DecodeLimits budget.
        norito::codec::decode_adaptive::<Query>(payload)
    }) {
        Ok(query) => query,
        Err(error) if error.is_decode_resource_limit() => {
            return Err(torii_proxy_error_response(
                StatusCode::PAYLOAD_TOO_LARGE,
                "query_capacity_exceeded",
                "signed-query routing scope payload exceeds its bounded decode allowance",
            ));
        }
        Err(_) => {
            // Item kinds are intentionally shared by several concrete queries,
            // so a schema mismatch is normal during classification. Only a
            // non-resource failure may fall through to the next concrete query.
            return Ok(None);
        }
    };
    let encoded_len =
        norito::codec::encode_adaptive_into(&query, &mut std::io::sink()).map_err(|_| {
            torii_proxy_error_response(
                StatusCode::INTERNAL_SERVER_ERROR,
                "query_encoding_failed",
                "failed to count the canonical signed-query routing scope payload",
            )
        })?;
    if encoded_len > memory_limits.canonical_encoded_bytes {
        return Err(torii_proxy_error_response(
            StatusCode::PAYLOAD_TOO_LARGE,
            "query_capacity_exceeded",
            "signed-query routing scope payload exceeds its bounded canonical encoding allowance",
        ));
    }
    let mut canonical = Vec::new();
    canonical.try_reserve_exact(encoded_len).map_err(|_| {
        torii_proxy_error_response(
            StatusCode::PAYLOAD_TOO_LARGE,
            "query_capacity_exceeded",
            "failed to reserve the bounded signed-query routing scope frame",
        )
    })?;
    let written = {
        let mut writer = FixedCapacityNoritoWriter {
            bytes: &mut canonical,
            max_bytes: encoded_len,
        };
        norito::codec::encode_adaptive_into(&query, &mut writer).map_err(|_| {
            torii_proxy_error_response(
                StatusCode::INTERNAL_SERVER_ERROR,
                "query_encoding_failed",
                "failed to encode the canonical signed-query routing scope payload",
            )
        })?
    };
    if written != encoded_len || canonical.len() != encoded_len {
        return Err(torii_proxy_error_response(
            StatusCode::INTERNAL_SERVER_ERROR,
            "query_encoding_failed",
            "signed-query routing scope length changed after bounded preflight",
        ));
    }
    Ok((canonical.as_slice() == payload).then_some(query))
}
fn bounded_unit_query_payload_matches(payload: &[u8]) -> bool {
    // Every fanout-classifiable unit query has an empty fixed-v1 payload. Do
    // not invoke the generic erased-query decoder here: `Decode::decode`
    // copies the complete attacker-controlled slice before it can reject a
    // non-unit query that shares the same output item kind.
    payload.is_empty()
}
fn target_scope_singular_query(
    query: &iroha_data_model::query::SingularQueryBox,
) -> Option<SignedQueryScope> {
    use iroha_data_model::query::SingularQueryBox;
    match query {
        SingularQueryBox::FindAssetById(query) => {
            Some(SignedQueryScope::TargetAccount(query.id.account().clone()))
        }
        SingularQueryBox::FindAssetDefinitionById(query) => {
            target_asset_definition_scope(&query.id)
        }
        SingularQueryBox::FindAccountById(query) => {
            Some(SignedQueryScope::TargetAccount(query.account_id().clone()))
        }
        SingularQueryBox::FindAliasesByAccountId(query) => {
            Some(SignedQueryScope::TargetAccount(query.account_id().clone()))
        }
        SingularQueryBox::FindAccountByAlias(query) => {
            Some(SignedQueryScope::TargetAlias(query.alias().clone()))
        }
        SingularQueryBox::FindAccountRecoveryPolicyByAlias(query) => {
            Some(SignedQueryScope::TargetAlias(query.alias().clone()))
        }
        SingularQueryBox::FindAccountRecoveryRequestByAlias(query) => {
            Some(SignedQueryScope::TargetAlias(query.alias().clone()))
        }
        SingularQueryBox::FindDomainById(query) => {
            Some(SignedQueryScope::TargetDomain(query.domain_id().clone()))
        }
        SingularQueryBox::FindNftById(query) => Some(SignedQueryScope::TargetDomain(
            query.nft_id().domain().clone(),
        )),
        _ => None,
    }
}
fn target_asset_definition_scope(
    _asset_definition_id: &iroha_data_model::asset::AssetDefinitionId,
) -> Option<SignedQueryScope> {
    None
}
fn resolve_asset_definition_scope(
    app: &AppState,
    asset_definition_id: &iroha_data_model::asset::AssetDefinitionId,
) -> Option<SignedQueryScope> {
    app.state
        .world_view()
        .asset_definition_domains()
        .get(asset_definition_id)
        .cloned()
        .map(SignedQueryScope::TargetDomain)
}
#[cfg(feature = "app_api")]
fn asset_definition_domain_snapshot(
    app: &AppState,
) -> BTreeMap<iroha_data_model::asset::AssetDefinitionId, iroha_data_model::domain::DomainId> {
    app.state
        .world_view()
        .asset_definition_domains()
        .iter()
        .map(|(definition_id, domain_id)| (definition_id.clone(), domain_id.clone()))
        .collect()
}
fn target_account_iterable_query(
    query: &iroha_data_model::query::QueryWithParams,
) -> Option<AccountId> {
    use iroha_data_model::{
        prelude::{
            FindAssetsByAccountId, FindDomainsByAccountId, FindNftsByAccountId,
            FindPermissionsByAccountId, FindRolesByAccountId,
        },
        query::{
            QueryItemKind,
            escrow::prelude::{FindAssetEscrowsByBuyer, FindAssetEscrowsBySeller},
        },
    };
    match query.item {
        QueryItemKind::Domain => {
            decode_query_payload::<FindDomainsByAccountId>(&query.query_payload)
                .map(|query| query.account_id().clone())
        }
        QueryItemKind::Asset => decode_query_payload::<FindAssetsByAccountId>(&query.query_payload)
            .map(|query| query.account_id().clone()),
        QueryItemKind::Nft => decode_query_payload::<FindNftsByAccountId>(&query.query_payload)
            .map(|query| query.account_id().clone()),
        QueryItemKind::Permission => {
            decode_query_payload::<FindPermissionsByAccountId>(&query.query_payload)
                .map(|query| query.account_id().clone())
        }
        QueryItemKind::RoleId => decode_query_payload::<FindRolesByAccountId>(&query.query_payload)
            .map(|query| query.account_id().clone()),
        QueryItemKind::AssetEscrowsBySeller => {
            decode_query_payload::<FindAssetEscrowsBySeller>(&query.query_payload)
                .map(|query| query.seller)
        }
        QueryItemKind::AssetEscrowsByBuyer => {
            decode_query_payload::<FindAssetEscrowsByBuyer>(&query.query_payload)
                .map(|query| query.buyer)
        }
        _ => None,
    }
}
fn target_domain_iterable_query(
    _query: &iroha_data_model::query::QueryWithParams,
) -> Option<iroha_data_model::domain::DomainId> {
    None
}
fn target_scope_singular_query_for_app(
    app: &AppState,
    query: &iroha_data_model::query::SingularQueryBox,
) -> Option<SignedQueryScope> {
    use iroha_data_model::query::SingularQueryBox;
    match query {
        SingularQueryBox::FindAssetById(query) => {
            Some(SignedQueryScope::TargetAccount(query.id.account().clone()))
        }
        SingularQueryBox::FindAssetDefinitionById(query) => {
            resolve_asset_definition_scope(app, &query.id)
        }
        _ => target_scope_singular_query(query),
    }
}
fn target_domain_iterable_query_for_app(
    app: &AppState,
    query: &iroha_data_model::query::QueryWithParams,
) -> Option<iroha_data_model::domain::DomainId> {
    use iroha_data_model::prelude::FindAccountsWithAsset;
    (query.item == iroha_data_model::query::QueryItemKind::Account)
        .then(|| decode_query_payload::<FindAccountsWithAsset>(&query.query_payload))
        .flatten()
        .and_then(|query| {
            resolve_asset_definition_scope(app, query.asset_definition_id()).and_then(|scope| {
                let SignedQueryScope::TargetDomain(domain_id) = scope else {
                    return None;
                };
                Some(domain_id)
            })
        })
}
fn is_authority_routed_iterable_query(query: &iroha_data_model::query::QueryWithParams) -> bool {
    use iroha_data_model::query::{QueryItemKind, transaction::prelude::FindTransactions};
    query.item == QueryItemKind::CommittedTransaction
        && payload_matches_query::<FindTransactions>(&query.query_payload)
}
fn is_trigger_inventory_query_bounded(
    query: &iroha_data_model::query::QueryWithParams,
    _memory_limits: QueryScopeMemoryLimits,
) -> Result<bool, Response> {
    use iroha_data_model::query::QueryItemKind;
    let (item_kind, _, _, payload) = canonical_iterable_query_parts(query);
    match item_kind {
        QueryItemKind::Trigger | QueryItemKind::TriggerId => {
            Ok(bounded_unit_query_payload_matches(payload))
        }
        _ => Ok(false),
    }
}
fn is_public_control_plane_query_bounded(
    query: &iroha_data_model::query::QueryWithParams,
    _memory_limits: QueryScopeMemoryLimits,
) -> Result<bool, Response> {
    use iroha_data_model::query::QueryItemKind;
    let (item_kind, _, _, payload) = canonical_iterable_query_parts(query);
    if item_kind == QueryItemKind::PeerId {
        Ok(bounded_unit_query_payload_matches(payload))
    } else {
        Ok(false)
    }
}
fn target_account_iterable_query_bounded(
    query: &iroha_data_model::query::QueryWithParams,
    memory_limits: QueryScopeMemoryLimits,
) -> Result<Option<AccountId>, Response> {
    use iroha_data_model::{
        prelude::{
            FindAssetsByAccountId, FindDomainsByAccountId, FindNftsByAccountId,
            FindPermissionsByAccountId, FindRolesByAccountId,
        },
        query::{
            QueryItemKind,
            escrow::prelude::{FindAssetEscrowsByBuyer, FindAssetEscrowsBySeller},
        },
    };
    macro_rules! target_account {
        ($query:ty, $payload:expr) => {
            decode_query_payload_bounded::<$query>($payload, memory_limits)?
                .map(|query| query.account_id().clone())
        };
    }
    let (item_kind, _, _, payload) = canonical_iterable_query_parts(query);
    Ok(match item_kind {
        QueryItemKind::Domain => target_account!(FindDomainsByAccountId, payload),
        QueryItemKind::Asset => target_account!(FindAssetsByAccountId, payload),
        QueryItemKind::Nft => target_account!(FindNftsByAccountId, payload),
        QueryItemKind::Permission => target_account!(FindPermissionsByAccountId, payload),
        QueryItemKind::RoleId => target_account!(FindRolesByAccountId, payload),
        QueryItemKind::AssetEscrowsBySeller => {
            decode_query_payload_bounded::<FindAssetEscrowsBySeller>(payload, memory_limits)?
                .map(|query| query.seller)
        }
        QueryItemKind::AssetEscrowsByBuyer => {
            decode_query_payload_bounded::<FindAssetEscrowsByBuyer>(payload, memory_limits)?
                .map(|query| query.buyer)
        }
        _ => None,
    })
}
fn target_domain_iterable_query_for_app_bounded(
    app: &AppState,
    query: &iroha_data_model::query::QueryWithParams,
    memory_limits: QueryScopeMemoryLimits,
) -> Result<Option<iroha_data_model::domain::DomainId>, Response> {
    use iroha_data_model::prelude::FindAccountsWithAsset;
    let (item_kind, _, _, payload) = canonical_iterable_query_parts(query);
    if item_kind != iroha_data_model::query::QueryItemKind::Account {
        return Ok(None);
    }
    let Some(query) =
        decode_query_payload_bounded::<FindAccountsWithAsset>(payload, memory_limits)?
    else {
        return Ok(None);
    };
    Ok(
        resolve_asset_definition_scope(app, query.asset_definition_id()).and_then(|scope| {
            let SignedQueryScope::TargetDomain(domain_id) = scope else {
                return None;
            };
            Some(domain_id)
        }),
    )
}
fn is_authority_routed_iterable_query_bounded(
    query: &iroha_data_model::query::QueryWithParams,
    _memory_limits: QueryScopeMemoryLimits,
) -> Result<bool, Response> {
    use iroha_data_model::query::QueryItemKind;
    let (item_kind, _, _, payload) = canonical_iterable_query_parts(query);
    if item_kind == QueryItemKind::CommittedTransaction {
        Ok(bounded_unit_query_payload_matches(payload))
    } else {
        Ok(false)
    }
}
trait SignedQueryScopeInput {
    fn request_with_authority(&self) -> &iroha_data_model::query::QueryRequestWithAuthority;
}
impl SignedQueryScopeInput for iroha_data_model::query::QueryRequestWithAuthority {
    fn request_with_authority(&self) -> &iroha_data_model::query::QueryRequestWithAuthority {
        self
    }
}
impl SignedQueryScopeInput for iroha_data_model::query::SignedQuery {
    fn request_with_authority(&self) -> &iroha_data_model::query::QueryRequestWithAuthority {
        &self.payload
    }
}
fn signed_query_scope(request: &impl SignedQueryScopeInput) -> SignedQueryScope {
    match request.request_with_authority().request() {
        iroha_data_model::query::QueryRequest::Continue(_) => SignedQueryScope::AuthorityRouted,
        iroha_data_model::query::QueryRequest::Singular(query) => {
            target_scope_singular_query(query).unwrap_or(SignedQueryScope::CrossDataspaceFanout)
        }
        iroha_data_model::query::QueryRequest::Start(query)
            if is_public_control_plane_query(query) =>
        {
            SignedQueryScope::PublicControlPlane
        }
        iroha_data_model::query::QueryRequest::Start(query)
            if is_trigger_inventory_query(query) =>
        {
            SignedQueryScope::LocalReplicated
        }
        iroha_data_model::query::QueryRequest::Start(query) => target_domain_iterable_query(query)
            .map(SignedQueryScope::TargetDomain)
            .or_else(|| target_account_iterable_query(query).map(SignedQueryScope::TargetAccount))
            .unwrap_or_else(|| {
                if is_authority_routed_iterable_query(query) {
                    SignedQueryScope::AuthorityRouted
                } else {
                    SignedQueryScope::CrossDataspaceFanout
                }
            }),
    }
}
fn signed_query_scope_for_app(
    app: &AppState,
    request: &impl SignedQueryScopeInput,
) -> SignedQueryScope {
    match request.request_with_authority().request() {
        iroha_data_model::query::QueryRequest::Continue(_) => SignedQueryScope::AuthorityRouted,
        iroha_data_model::query::QueryRequest::Singular(query) => {
            target_scope_singular_query_for_app(app, query)
                .unwrap_or(SignedQueryScope::CrossDataspaceFanout)
        }
        iroha_data_model::query::QueryRequest::Start(query)
            if is_public_control_plane_query(query) =>
        {
            SignedQueryScope::PublicControlPlane
        }
        iroha_data_model::query::QueryRequest::Start(query)
            if is_trigger_inventory_query(query) =>
        {
            SignedQueryScope::LocalReplicated
        }
        iroha_data_model::query::QueryRequest::Start(query) => {
            target_domain_iterable_query_for_app(app, query)
                .map(SignedQueryScope::TargetDomain)
                .or_else(|| {
                    target_account_iterable_query(query).map(SignedQueryScope::TargetAccount)
                })
                .unwrap_or_else(|| {
                    if is_authority_routed_iterable_query(query) {
                        SignedQueryScope::AuthorityRouted
                    } else {
                        SignedQueryScope::CrossDataspaceFanout
                    }
                })
        }
    }
}
fn signed_query_scope_for_app_bounded(
    app: &AppState,
    request: &impl SignedQueryScopeInput,
    memory_limits: QueryScopeMemoryLimits,
) -> Result<SignedQueryScope, Response> {
    let scope = match request.request_with_authority().request() {
        iroha_data_model::query::QueryRequest::Continue(_) => SignedQueryScope::AuthorityRouted,
        iroha_data_model::query::QueryRequest::Singular(query) => {
            target_scope_singular_query_for_app(app, query)
                .unwrap_or(SignedQueryScope::CrossDataspaceFanout)
        }
        iroha_data_model::query::QueryRequest::Start(query) => {
            if is_public_control_plane_query_bounded(query, memory_limits)? {
                SignedQueryScope::PublicControlPlane
            } else if is_trigger_inventory_query_bounded(query, memory_limits)? {
                SignedQueryScope::LocalReplicated
            } else if let Some(domain_id) =
                target_domain_iterable_query_for_app_bounded(app, query, memory_limits)?
            {
                SignedQueryScope::TargetDomain(domain_id)
            } else if let Some(account_id) =
                target_account_iterable_query_bounded(query, memory_limits)?
            {
                SignedQueryScope::TargetAccount(account_id)
            } else if is_authority_routed_iterable_query_bounded(query, memory_limits)? {
                SignedQueryScope::AuthorityRouted
            } else {
                SignedQueryScope::CrossDataspaceFanout
            }
        }
    };
    Ok(scope)
}
fn torii_authorized_signed_query_routes(
    app: &AppState,
    request: &impl SignedQueryScopeInput,
    scope: &SignedQueryScope,
) -> Result<Vec<RoutingDecision>, Response> {
    if matches!(scope, SignedQueryScope::PublicControlPlane) {
        return Ok(Vec::new());
    }
    if matches!(scope, SignedQueryScope::LocalReplicated) {
        torii_authorize_signed_query_routes(
            app,
            request,
            &SignedQueryScope::AuthorityRouted,
            torii_all_dataspace_routes(app),
        )?;
        return Ok(Vec::new());
    }
    if matches!(scope, SignedQueryScope::AuthorityRouted) {
        torii_authorize_signed_query_routes(app, request, scope, torii_all_dataspace_routes(app))?;
        let authority = &request.request_with_authority().authority;
        return Ok(vec![
            resolve_signed_query_authority_routing(app, authority).map_err(|_| {
                torii_proxy_error_response(
                    StatusCode::SERVICE_UNAVAILABLE,
                    "route_unavailable",
                    "failed to resolve signed-query authority route",
                )
            })?,
        ]);
    }
    let routes = match scope {
        SignedQueryScope::PublicControlPlane => Vec::new(),
        SignedQueryScope::LocalReplicated => Vec::new(),
        SignedQueryScope::AuthorityRouted => unreachable!("handled above"),
        SignedQueryScope::CrossDataspaceFanout => torii_all_dataspace_routes(app),
        SignedQueryScope::TargetAccount(account_id) => {
            torii_target_account_routes(app, account_id)?
        }
        SignedQueryScope::TargetAlias(alias) => torii_target_alias_routes(app, alias)?,
        SignedQueryScope::TargetDomain(domain_id) => torii_target_domain_routes(app, domain_id)?,
    };
    torii_authorize_signed_query_routes(app, request, scope, routes)
}
