#[cfg(feature = "app_api")]
async fn handler_list_proofs(
    State(app): State<SharedAppState>,
    headers: axum::http::HeaderMap,
    axum::extract::ConnectInfo(remote): axum::extract::ConnectInfo<std::net::SocketAddr>,
    AxQuery(q): AxQuery<crate::routing::ProofListQuery>,
) -> Result<impl IntoResponse, Error> {
    let remote_ip = remote.ip();
    if limits::is_allowed_by_cidr(&headers, Some(remote_ip), &app.api_rate_limit_bypass_nets) {
        let admission = acquire_query_admission(app.as_ref(), true).await?;
        return crate::routing::handle_list_proofs_admitted(
            app.state.clone(),
            app.proof_limits,
            app.telemetry.clone(),
            AxQuery(q),
            admission,
        )
        .await;
    }
    let mut q = q;
    let requested_limit = q.limit.unwrap_or(app.proof_limits.max_list_limit);
    if requested_limit == 0 || requested_limit > app.proof_limits.max_list_limit {
        return Err(Error::Query(iroha_data_model::ValidationFail::QueryFailed(
            iroha_data_model::query::error::QueryExecutionFail::Conversion(format!(
                "limit must be between 1 and {}",
                app.proof_limits.max_list_limit
            )),
        )));
    }
    q.limit = Some(requested_limit);
    let cost = u64::from(requested_limit).div_ceil(50);
    check_proof_access(
        &app,
        &headers,
        Some(remote_ip),
        "v1/zk/proofs",
        cost.max(1),
        true,
    )
    .await?;
    let admission = acquire_query_admission(app.as_ref(), true).await?;
    crate::routing::handle_list_proofs_admitted(
        app.state.clone(),
        app.proof_limits,
        app.telemetry.clone(),
        AxQuery(q),
        admission,
    )
    .await
}
