#[cfg(feature = "app_api")]
async fn handler_post_contract_call_simulate(
    State(app): State<SharedAppState>,
    headers: axum::http::HeaderMap,
    axum::extract::ConnectInfo(remote): axum::extract::ConnectInfo<std::net::SocketAddr>,
    request: NoritoJson<crate::routing::ContractCallSimulateDto>,
) -> Result<AxResponse, Error> {
    check_public_contract_route_rate_limit(
        &app,
        &headers,
        remote.ip(),
        "v1/contracts/call/simulate",
        "call_simulate",
    )
    .await?;
    let retry_after_secs = app.proof_limits.retry_after.as_secs().max(1);
    let tooling_permit = app
        .zk_ivm_prove_inflight
        .clone()
        .try_acquire_owned()
        .map_err(|_| Error::ProofRateLimited {
            endpoint: "v1/contracts/call/simulate",
            retry_after_secs,
        })?;
    let state = app.state.clone();
    let simulation_task = crate::panic_recovery::spawn_blocking_recoverable(move || {
        // Retain capacity until physical VM completion even if the awaiting
        // request future times out or is cancelled.
        let _tooling_permit = tooling_permit;
        crate::routing::handle_post_contract_call_simulate(state, request)
    });
    match tokio::time::timeout(
        app.ivm_tooling_timeout,
        crate::panic_recovery::join_recoverable(simulation_task),
    )
    .await
    {
        Ok(Ok(Ok(body))) => {
            proof_cached_json_response_with_egress(
                &app,
                &headers,
                Some(remote.ip()),
                "v1/contracts/call/simulate",
                Bytes::from(body),
                true,
            )
            .await
        }
        Ok(Ok(Err(err))) => {
            app.telemetry
                .with_metrics(|tel| tel.inc_torii_contract_error("call_simulate"));
            Err(err)
        }
        Ok(Err(err)) => {
            app.telemetry
                .with_metrics(|tel| tel.inc_torii_contract_error("call_simulate"));
            Err(Error::Query(
                iroha_data_model::ValidationFail::InternalError(format!(
                    "contract simulation worker panicked: {err}"
                )),
            ))
        }
        Err(_) => Err(Error::Query(iroha_data_model::ValidationFail::QueryFailed(
            iroha_data_model::query::error::QueryExecutionFail::Conversion(
                "contract simulation timed out; capacity remains reserved until the worker exits"
                    .to_owned(),
            ),
        ))),
    }
}
#[cfg(feature = "app_api")]
async fn handler_post_bridge_proof_submit(
    State(app): State<SharedAppState>,
    axum::Extension(admission): axum::Extension<Arc<SccpSubmitAdmission>>,
    headers: axum::http::HeaderMap,
    axum::extract::ConnectInfo(remote): axum::extract::ConnectInfo<std::net::SocketAddr>,
) -> Result<AxResponse, Error> {
    let SccpSubmitWork { permit, body } = admission.take()?;
    match crate::routing::handle_post_bridge_proof_submit(
        app.chain_id.clone(),
        app.queue.clone(),
        app.state.clone(),
        app.telemetry.clone(),
        body,
        permit,
    )
    .await
    {
        Ok((response, true)) => {
            proof_response_with_exact_egress(
                app.as_ref(),
                &headers,
                Some(remote.ip()),
                "v1/bridge/proofs/submit",
                response,
                true,
            )
            .await
        }
        // A direct submission has already mutated the local queue. Never turn
        // its success into a retry-inducing egress rejection after the fact.
        Ok((response, false)) => Ok(response),
        Err(err) => {
            app.telemetry
                .with_metrics(|tel| tel.inc_torii_contract_error("bridge_proof"));
            Err(err)
        }
    }
}
