#[cfg(feature = "app_api")]
async fn handler_post_contract_view(
    State(app): State<SharedAppState>,
    headers: axum::http::HeaderMap,
    axum::extract::ConnectInfo(remote): axum::extract::ConnectInfo<std::net::SocketAddr>,
    request: NoritoJson<crate::routing::ContractViewDto>,
) -> Result<AxResponse, Error> {
    check_public_contract_route_rate_limit(
        &app,
        &headers,
        remote.ip(),
        "v1/contracts/view",
        "view",
    )
    .await?;
    if let Some(route) = torii_contract_target_read_route(
        app.as_ref(),
        request.0.contract_address.as_ref(),
        request.0.contract_alias.as_ref(),
    ) {
        let body = norito::json::to_vec(&request.0).map_err(|error| {
            Error::Query(iroha_data_model::ValidationFail::InternalError(format!(
                "failed to encode routed contract view request: {error}"
            )))
        })?;
        return Ok(execute_torii_single_route_read(
            &app,
            route,
            ToriiReadEndpointV1::ContractViewPost,
            Vec::new(),
            None,
            body,
        )
        .await
        .into_response());
    }
    match execute_bounded_contract_view_work(
        &app,
        "v1/contracts/view",
        BoundedContractViewWork::Single(request.0),
    )
    .await
    {
        Ok(BoundedContractViewOutput::Single { status, body }) => {
            let mut response = proof_cached_json_response_with_egress(
                &app,
                &headers,
                Some(remote.ip()),
                "v1/contracts/view",
                Bytes::from(body),
                true,
            )
            .await?;
            *response.status_mut() = status;
            Ok(response)
        }
        Ok(BoundedContractViewOutput::Batch { .. }) => Err(Error::Query(
            iroha_data_model::ValidationFail::InternalError(
                "contract view worker returned a batch response".to_owned(),
            ),
        )),
        Err(err) => {
            app.telemetry
                .with_metrics(|tel| tel.inc_torii_contract_error("view"));
            Err(err)
        }
    }
}
#[cfg(feature = "app_api")]
async fn handler_post_contract_view_batch(
    State(app): State<SharedAppState>,
    headers: axum::http::HeaderMap,
    axum::extract::ConnectInfo(remote): axum::extract::ConnectInfo<std::net::SocketAddr>,
    request: NoritoJson<crate::routing::ContractViewBatchDto>,
) -> Result<AxResponse, Error> {
    check_public_contract_route_rate_limit(
        &app,
        &headers,
        remote.ip(),
        "v1/contracts/view/batch",
        "view_batch",
    )
    .await?;
    crate::routing::validate_contract_view_batch_request(&request.0)?;
    let mut batch_route = None;
    let mut batch_route_conflict = false;
    let mut all_items_routed = !request.0.items.is_empty();
    for item in &request.0.items {
        let item_route = torii_contract_target_read_route(
            app.as_ref(),
            item.contract_address.as_ref(),
            item.contract_alias.as_ref(),
        );
        match item_route {
            Some(item_route) => match batch_route {
                Some(existing) if existing != item_route => {
                    batch_route_conflict = true;
                    break;
                }
                Some(_) => {}
                None => batch_route = Some(item_route),
            },
            None => {
                all_items_routed = false;
                break;
            }
        }
    }
    if let Some(route) = batch_route
        && all_items_routed
        && !batch_route_conflict
    {
        let body = norito::json::to_vec(&request.0).map_err(|error| {
            Error::Query(iroha_data_model::ValidationFail::InternalError(format!(
                "failed to encode routed contract view batch request: {error}"
            )))
        })?;
        return Ok(execute_torii_single_route_read(
            &app,
            route,
            ToriiReadEndpointV1::ContractViewBatchPost,
            Vec::new(),
            None,
            body,
        )
        .await
        .into_response());
    }
    match execute_bounded_contract_view_work(
        &app,
        "v1/contracts/view/batch",
        BoundedContractViewWork::Batch(request.0),
    )
    .await
    {
        Ok(BoundedContractViewOutput::Batch { body }) => {
            proof_cached_json_response_with_egress(
                &app,
                &headers,
                Some(remote.ip()),
                "v1/contracts/view/batch",
                Bytes::from(body),
                true,
            )
            .await
        }
        Ok(BoundedContractViewOutput::Single { .. }) => Err(Error::Query(
            iroha_data_model::ValidationFail::InternalError(
                "contract view batch worker returned a single response".to_owned(),
            ),
        )),
        Err(err) => {
            app.telemetry
                .with_metrics(|tel| tel.inc_torii_contract_error("view_batch"));
            Err(err)
        }
    }
}
