async fn iso_status_for_outbox(
    app: &SharedAppState,
    authenticated_operator: &iroha_crypto::PublicKey,
    headers: &axum::http::HeaderMap,
    remote_ip: std::net::IpAddr,
    msg_id: &str,
    access_context: &'static str,
) -> Result<(Arc<Iso20022BridgeRuntime>, IsoMessageStatus), Error> {
    check_access(app.as_ref(), headers, Some(remote_ip), access_context).await?;
    let runtime = match &app.iso_bridge {
        Some(rt) => rt.clone(),
        None => {
            return Err(Error::Query(
                iroha_data_model::ValidationFail::NotPermitted("iso20022 bridge disabled".into()),
            ));
        }
    };
    let status = runtime
        .authorized_message_status(authenticated_operator, msg_id)
        .ok_or_else(|| {
            Error::Query(iroha_data_model::ValidationFail::NotPermitted(
                "unknown ISO 20022 message identifier".into(),
            ))
        })?;
    Ok((runtime, status))
}
fn signed_iso_xml_response(
    runtime: &Iso20022BridgeRuntime,
    xml: String,
) -> Result<Response, Error> {
    let signed = runtime
        .sign_outbound_document(xml)
        .map_err(|error| Error::Query(map_iso_error(error)))?;
    let mut response = (StatusCode::OK, signed.xml).into_response();
    response.headers_mut().insert(
        axum::http::header::CONTENT_TYPE,
        axum::http::HeaderValue::from_static("application/xml; charset=utf-8"),
    );
    response.headers_mut().insert(
        axum::http::HeaderName::from_static("x-iroha-iso-signer"),
        signed.public_key.parse().map_err(|_| {
            Error::Query(iroha_data_model::ValidationFail::InternalError(
                "invalid ISO bridge signer response header".into(),
            ))
        })?,
    );
    response.headers_mut().insert(
        axum::http::HeaderName::from_static("x-iroha-iso-signature"),
        signed.signature.parse().map_err(|_| {
            Error::Query(iroha_data_model::ValidationFail::InternalError(
                "invalid ISO bridge signature response header".into(),
            ))
        })?,
    );
    response.headers_mut().insert(
        axum::http::HeaderName::from_static("x-iroha-iso-signature-domain"),
        axum::http::HeaderValue::from_static("iroha.iso20022.outbound.v2"),
    );
    Ok(response)
}
fn iso_pacs002_xml(status: &IsoMessageStatus) -> String {
    let msg_id = xml_escape(status.message_id());
    let message_name = xml_escape(
        status
            .metadata()
            .message_type()
            .unwrap_or("unknown.iso20022.message"),
    );
    let tx_id = xml_escape(
        status
            .transaction_hash()
            .or_else(|| status.metadata().business_message_id())
            .unwrap_or_else(|| status.message_id()),
    );
    let status_code = status.pacs002_code();
    let created_at = xml_timestamp(SystemTime::now());
    let original_created_at = xml_timestamp(status.updated_at());
    let group_reason = iso_status_reason_xml("      ", status);
    let tx_reason = iso_status_reason_xml("      ", status);
    format!(
        concat!(
            r#"<?xml version="1.0" encoding="UTF-8"?>"#,
            "\n",
            r#"<Document xmlns="urn:iso:std:iso:20022:tech:xsd:pacs.002.001.10">"#,
            "\n  <FIToFIPmtStsRpt>",
            "\n    <GrpHdr>",
            "\n      <MsgId>IROHA-PACS002-{msg_id}</MsgId>",
            "\n      <CreDtTm>{created_at}</CreDtTm>",
            "\n    </GrpHdr>",
            "\n    <OrgnlGrpInfAndSts>",
            "\n      <OrgnlMsgId>{msg_id}</OrgnlMsgId>",
            "\n      <OrgnlMsgNmId>{message_name}</OrgnlMsgNmId>",
            "\n      <OrgnlCreDtTm>{original_created_at}</OrgnlCreDtTm>",
            "\n      <OrgnlNbOfTxs>1</OrgnlNbOfTxs>",
            "\n      <GrpSts>{status_code}</GrpSts>",
            "{group_reason}",
            "\n    </OrgnlGrpInfAndSts>",
            "\n    <TxInfAndSts>",
            "\n      <OrgnlTxId>{tx_id}</OrgnlTxId>",
            "\n      <TxSts>{status_code}</TxSts>",
            "{tx_reason}",
            "\n    </TxInfAndSts>",
            "\n  </FIToFIPmtStsRpt>",
            "\n</Document>\n"
        ),
        msg_id = msg_id,
        created_at = created_at,
        message_name = message_name,
        original_created_at = original_created_at,
        status_code = status_code,
        group_reason = group_reason,
        tx_id = tx_id,
        tx_reason = tx_reason,
    )
}
fn iso_pacs004_xml(status: &IsoMessageStatus) -> Result<String, Error> {
    let amount =
        require_iso_outbox_field(status.settlement_amount(), "settlement_amount", "pacs.004")?;
    let currency = require_iso_outbox_field(
        status.settlement_currency(),
        "settlement_currency",
        "pacs.004",
    )?;
    let msg_id = xml_escape(status.message_id());
    let message_name = xml_escape(iso_original_message_name(status));
    let tx_id = xml_escape(&iso_original_transaction_id(status));
    let amount = xml_escape(amount);
    let currency = xml_escape(currency);
    let created_at = xml_timestamp(SystemTime::now());
    let original_created_at = xml_timestamp(status.updated_at());
    let return_reason = iso_return_reason_xml("      ", status);
    Ok(format!(
        concat!(
            r#"<?xml version="1.0" encoding="UTF-8"?>"#,
            "\n",
            r#"<Document xmlns="urn:iso:std:iso:20022:tech:xsd:pacs.004.001.09">"#,
            "\n  <PmtRtr>",
            "\n    <GrpHdr>",
            "\n      <MsgId>IROHA-PACS004-{msg_id}</MsgId>",
            "\n      <CreDtTm>{created_at}</CreDtTm>",
            "\n      <NbOfTxs>1</NbOfTxs>",
            "\n    </GrpHdr>",
            "\n    <OrgnlGrpInf>",
            "\n      <OrgnlMsgId>{msg_id}</OrgnlMsgId>",
            "\n      <OrgnlMsgNmId>{message_name}</OrgnlMsgNmId>",
            "\n      <OrgnlCreDtTm>{original_created_at}</OrgnlCreDtTm>",
            "\n    </OrgnlGrpInf>",
            "\n    <TxInf>",
            "\n      <OrgnlInstrId>{tx_id}</OrgnlInstrId>",
            "\n      <RtrdIntrBkSttlmAmt Ccy=\"{currency}\">{amount}</RtrdIntrBkSttlmAmt>",
            "\n      <ChrgBr>SLEV</ChrgBr>",
            "{return_reason}",
            "\n    </TxInf>",
            "\n  </PmtRtr>",
            "\n</Document>\n"
        ),
        msg_id = msg_id,
        created_at = created_at,
        message_name = message_name,
        original_created_at = original_created_at,
        tx_id = tx_id,
        amount = amount,
        currency = currency,
        return_reason = return_reason,
    ))
}
