#[cfg(feature = "app_api")]
fn validate_account_onboarding_readiness(
    state: &CoreState,
    signer: &AccountOnboardingSigner,
) -> iroha_data_model::alias_setup::AliasSetupReportV1 {
    use iroha_data_model::alias_setup::{
        AliasSetupDiagnosticV1, AliasSetupReportV1, AliasSetupSeverityV1, AliasSetupStatusV1,
        AliasSetupValidationPhaseV1,
    };
    let world = state.world_view();
    let nexus = state.nexus_snapshot();
    let catalog = nexus.dataspace_catalog.clone();
    let has_committed_block = state.view().latest_block().is_some();
    let now_ms = state.view().latest_block().map_or(0, |block| {
        u64::try_from(block.header().creation_time().as_millis()).unwrap_or(u64::MAX)
    });
    let mut diagnostics = Vec::new();
    let mut blocked =
        |code: &str, resource: Option<String>, config_path: &str, remediation: &str| {
            diagnostics.push(AliasSetupDiagnosticV1 {
                phase: AliasSetupValidationPhaseV1::WorldState,
                code: code.to_owned(),
                severity: AliasSetupSeverityV1::Error,
                resource,
                config_path: Some(config_path.to_owned()),
                expected: None,
                actual: None,
                remediation: remediation.to_owned(),
            });
        };
    if world.accounts().get(&signer.authority).is_none() {
        blocked(
            "alias.onboarding.authority_missing",
            Some(signer.authority.to_string()),
            "torii.account_onboarding.authority",
            "register and fund the configured onboarding authority before enabling sponsored onboarding",
        );
    }
    let account_alias_policy =
        iroha_core::sns::policy_by_id(&world, iroha_data_model::sns::ACCOUNT_ALIAS_SUFFIX_ID);
    match account_alias_policy.as_ref() {
        Err(error) => blocked(
            "alias.onboarding.policy_invalid",
            Some(error.to_string()),
            "torii.account_onboarding",
            "replace the malformed account-alias SNS policy through an explicit ledger transition",
        ),
        Ok(None) => blocked(
            "alias.onboarding.policy_missing",
            Some(iroha_data_model::sns::ACCOUNT_ALIAS_SUFFIX_ID.to_string()),
            "torii.account_onboarding",
            "install the account-alias SNS policy in genesis or committed world state",
        ),
        Ok(Some(policy)) => {
            if !matches!(policy.status, iroha_data_model::sns::SuffixStatus::Active) {
                blocked(
                    "alias.onboarding.policy_inactive",
                    Some(policy.suffix.clone()),
                    "torii.account_onboarding",
                    "activate the account-alias SNS policy before accepting onboarding requests",
                );
            }
            let lease_term_supported = signer.alias_lease_term_years >= policy.min_term_years
                && signer.alias_lease_term_years <= policy.max_term_years
                && policy.pricing.iter().any(|tier| {
                    signer.alias_lease_term_years >= tier.min_duration_years
                        && signer.alias_lease_term_years <= tier.max_duration_years
                });
            if !lease_term_supported {
                blocked(
                    "alias.onboarding.lease_term_unsupported",
                    Some(signer.alias_lease_term_years.to_string()),
                    "torii.account_onboarding.lease_term_years",
                    "choose a lease term accepted by the live account-alias policy and at least one pricing tier",
                );
            }
            if let Some(defaults) = signer.owner_auto_renew.as_ref() {
                let renewal_term_supported = defaults.term_years >= policy.min_term_years
                    && defaults.term_years <= policy.max_term_years
                    && policy.pricing.iter().any(|tier| {
                        defaults.term_years >= tier.min_duration_years
                            && defaults.term_years <= tier.max_duration_years
                    });
                if !renewal_term_supported {
                    blocked(
                        "alias.onboarding.auto_renew_term_unsupported",
                        Some(defaults.term_years.to_string()),
                        "torii.account_onboarding.auto_renew.term_years",
                        "choose an auto-renew term accepted by the live account-alias policy and at least one pricing tier",
                    );
                }
            }
            if let Err(error) =
                iroha_core::sns::ensure_namespace_policy_payment_asset_matches_configured(
                    &world,
                    iroha_core::sns::SnsNamespace::AccountAlias,
                    &nexus.fees.fee_asset_id,
                )
            {
                blocked(
                    "alias.onboarding.payment_asset_mismatch",
                    Some(policy.payment_asset_id.clone()),
                    "nexus.fees.fee_asset_id",
                    &format!(
                        "align the account-alias policy and pricing tiers with the registered configured fee asset: {error}"
                    ),
                );
            } else if let Ok(payment_asset) =
                AssetDefinitionId::parse_address_literal(&policy.payment_asset_id)
            {
                let payer_asset = AssetId::of(payment_asset, signer.authority.clone());
                let payer_balance = world
                    .asset(&payer_asset)
                    .ok()
                    .map(|asset| asset.value().as_ref().clone())
                    .unwrap_or_else(Quantity::zero);
                if payer_balance <= Quantity::zero() {
                    blocked(
                        "alias.onboarding.payer_unfunded",
                        Some(payer_asset.to_string()),
                        "torii.account_onboarding.authority",
                        "fund the onboarding authority with the configured fee asset before accepting sponsored onboarding",
                    );
                }
            }
        }
    }
    for permission in &signer.allowed_permissions {
        if !world
            .executor_data_model()
            .permissions()
            .iter()
            .any(|known| known.as_str() == permission)
        {
            blocked(
                "alias.onboarding.additional_permission_unknown",
                Some(permission.clone()),
                "torii.account_onboarding.additional_permissions",
                "remove the permission or install an executor data model that declares it",
            );
        }
    }
    if let Some(program_id) = signer.fee_sponsor_program_id.as_ref() {
        if world.fee_sponsor_programs().get(program_id).is_none() {
            blocked(
                "alias.onboarding.sponsor_program_missing",
                Some(program_id.to_string()),
                "torii.account_onboarding.fee_sponsor_program_id",
                "register the configured fee sponsor program or remove it from onboarding configuration",
            );
        }
        let enrollment_permission = Permission::from(CanEnrollFeeSponsorProgram {
            program_id: program_id.clone(),
        });
        if !torii_account_has_permission(&world, &signer.authority, &enrollment_permission) {
            blocked(
                "alias.onboarding.sponsor_permission_missing",
                Some(program_id.to_string()),
                "torii.account_onboarding.authority",
                "grant the configured authority exact CanEnrollFeeSponsorProgram permission",
            );
        }
    }
    for domain in signer.api_token_hashes_by_domain.keys() {
        let dataspace = match iroha_core::sns::resolve_active_dataspace_id_by_alias(
            &world,
            &catalog,
            domain.dataspace().as_ref(),
            now_ms,
        ) {
            Ok(dataspace) => dataspace,
            Err(error) => {
                let message = error.to_string();
                blocked(
                    if message.contains(iroha_core::sns::ALIAS_CATALOG_MAPPING_CONFLICT_CODE) {
                        iroha_core::sns::ALIAS_CATALOG_MAPPING_CONFLICT_CODE
                    } else {
                        "alias.onboarding.credential_dataspace_unknown"
                    },
                    Some(domain.to_string()),
                    "torii.account_onboarding.credentials[].scope.domain",
                    "repair the static/active SNS dataspace mapping or correct the credential scope",
                );
                continue;
            }
        };
        if world.domain(domain).is_err() {
            blocked(
                "alias.onboarding.credential_domain_missing",
                Some(domain.to_string()),
                "torii.account_onboarding.credentials[].scope.domain",
                "create the configured onboarding domain before accepting sponsored onboarding",
            );
        }
        match iroha_core::sns::get_name_record(
            &world,
            &catalog,
            iroha_core::sns::SnsNamespace::Domain,
            &domain.to_string(),
            now_ms,
        ) {
            Ok(record) if matches!(record.status, iroha_data_model::sns::NameStatus::Active) => {}
            Ok(_) => blocked(
                "alias.onboarding.credential_domain_lease_inactive",
                Some(domain.to_string()),
                "torii.account_onboarding.credentials[].scope.domain",
                "activate or renew the exact parent-domain SNS lease before accepting onboarding",
            ),
            Err(error) => blocked(
                "alias.onboarding.credential_domain_lease_missing",
                Some(domain.to_string()),
                "torii.account_onboarding.credentials[].scope.domain",
                &format!(
                    "create the exact active parent-domain SNS lease before accepting onboarding: {error}"
                ),
            ),
        }
        if !iroha_core::alias::authority_can_manage_account_alias_scope(
            &world,
            &signer.authority,
            dataspace,
            Some(domain),
        ) {
            blocked(
                "alias.onboarding.manage_permission_missing",
                Some(domain.to_string()),
                "torii.account_onboarding.authority",
                "grant the onboarding authority exact domain-scoped CanManageAccountAlias permission",
            );
        }
    }
    for dataspace_name in signer.api_token_hashes_by_dataspace.keys() {
        let dataspace = match iroha_core::sns::resolve_active_dataspace_id_by_alias(
            &world,
            &catalog,
            dataspace_name.as_ref(),
            now_ms,
        ) {
            Ok(dataspace) => dataspace,
            Err(error) => {
                let message = error.to_string();
                blocked(
                    if message.contains(iroha_core::sns::ALIAS_CATALOG_MAPPING_CONFLICT_CODE) {
                        iroha_core::sns::ALIAS_CATALOG_MAPPING_CONFLICT_CODE
                    } else {
                        "alias.onboarding.credential_dataspace_unknown"
                    },
                    Some(dataspace_name.to_string()),
                    "torii.account_onboarding.credentials[].scope.dataspace",
                    "repair the static/active SNS dataspace mapping or correct the credential scope",
                );
                continue;
            }
        };
        match iroha_core::sns::get_name_record(
            &world,
            &catalog,
            iroha_core::sns::SnsNamespace::Dataspace,
            dataspace_name.as_ref(),
            now_ms,
        ) {
            Ok(record) if matches!(record.status, iroha_data_model::sns::NameStatus::Active) => {}
            Ok(_) => blocked(
                "alias.onboarding.credential_dataspace_lease_inactive",
                Some(dataspace_name.to_string()),
                "torii.account_onboarding.credentials[].scope.dataspace",
                "activate or renew the exact parent-dataspace SNS lease before accepting onboarding",
            ),
            Err(error) => blocked(
                "alias.onboarding.credential_dataspace_lease_missing",
                Some(dataspace_name.to_string()),
                "torii.account_onboarding.credentials[].scope.dataspace",
                &format!(
                    "create the exact active parent-dataspace SNS lease before accepting onboarding: {error}"
                ),
            ),
        }
        if !iroha_core::alias::authority_can_manage_account_alias_scope(
            &world,
            &signer.authority,
            dataspace,
            None,
        ) {
            blocked(
                "alias.onboarding.manage_permission_missing",
                Some(dataspace_name.to_string()),
                "torii.account_onboarding.authority",
                "grant the onboarding authority exact dataspace-root CanManageAccountAlias permission",
            );
        }
    }
    drop(blocked);
    let status = if diagnostics.is_empty() {
        AliasSetupStatusV1::Ready
    } else if !has_committed_block
        && world.accounts().iter().next().is_none()
        && diagnostics.iter().all(|diagnostic| {
            matches!(
                diagnostic.code.as_str(),
                "alias.onboarding.authority_missing"
                    | "alias.onboarding.policy_missing"
                    | "alias.onboarding.payer_unfunded"
                    | "alias.onboarding.additional_permission_unknown"
                    | "alias.onboarding.sponsor_program_missing"
                    | "alias.onboarding.credential_dataspace_unknown"
                    | "alias.onboarding.credential_domain_missing"
                    | "alias.onboarding.credential_domain_selector_missing"
                    | "alias.onboarding.credential_domain_lease_missing"
                    | "alias.onboarding.credential_dataspace_lease_missing"
                    | "alias.onboarding.manage_permission_missing"
            )
        })
    {
        AliasSetupStatusV1::Pending
    } else {
        AliasSetupStatusV1::Blocked
    };
    AliasSetupReportV1::new(status, diagnostics)
}
#[cfg(feature = "app_api")]
#[derive(Clone)]
struct SoraFsAppealSettlementSubmitter {
    bindings: Vec<iroha_config::parameters::actual::SorafsAppealFinanceSignerBinding>,
    runtime_signers: Option<Arc<SoraFsAppealFinanceRuntimeSignersV1>>,
    forwarder: sorafs_node::appeal_finance_transaction_forwarder::AppealFinanceTransactionForwarder,
    worker_scan_interval: Duration,
}
#[cfg(feature = "app_api")]
impl SoraFsAppealSettlementSubmitter {
    fn from_config(
        config: &iroha_config::parameters::actual::SorafsAppealFinanceSettlement,
        storage_data_dir: &Path,
        runtime_signers: Option<Arc<SoraFsAppealFinanceRuntimeSignersV1>>,
        finalized_startup_height: u64,
        checkpoint_runtime: Arc<
            dyn sorafs_node::appeal_finance_transaction_forwarder::AppealFinanceCheckpointRuntime,
        >,
    ) -> Result<Self, ToriiBuildError> {
        use sorafs_node::appeal_finance_transaction_forwarder::{
            APPEAL_FINANCE_CHECKPOINT_AUTHENTICATION_POLICY_VERSION_V1,
            APPEAL_FINANCE_TRANSACTION_MAX_CANONICAL_BYTES_V1,
            AppealFinanceCheckpointAuthenticationPolicyV1,
            AppealFinanceRuntimeProviderQualificationV1, AppealFinanceTransactionForwarder,
            AppealFinanceTransactionForwarderPolicyV1,
        };
        qualify_appeal_finance_runtime_signer_inventory(
            &config.submitter_signers,
            runtime_signers.as_deref(),
            finalized_startup_height,
        )
        .map_err(|error| {
            ToriiBuildError::invalid_runtime_dependency(
                "sorafs.appeal_finance.submitter_signers",
                format!("{error:?}"),
            )
        })?;
        let checkpoint_binding = config.checkpoint_provider.as_ref().ok_or_else(|| {
            ToriiBuildError::invalid_configuration(
                "sorafs.appeal_finance.checkpoint_provider",
                "submitters require an independent configured checkpoint signer binding",
            )
        })?;
        if config.submitter_signers.iter().any(|binding| {
            binding.handle == checkpoint_binding.handle
                || binding.public_key == checkpoint_binding.public_key
        }) {
            return Err(ToriiBuildError::invalid_configuration(
                "sorafs.appeal_finance.checkpoint_provider",
                "checkpoint and transaction signer bindings must be independently administered",
            ));
        }
        let checkpoint_public_key = checkpoint_binding
            .public_key
            .try_to_bytes()
            .ok()
            .and_then(|(algorithm, bytes)| {
                if algorithm != iroha_crypto::Algorithm::Ed25519 {
                    return None;
                }
                <[u8; 32]>::try_from(bytes).ok()
            })
            .ok_or_else(|| {
                ToriiBuildError::invalid_configuration(
                    "sorafs.appeal_finance.checkpoint_provider.public_key",
                    "checkpoint binding must carry a strict Ed25519 public key",
                )
            })?;
        let expected_checkpoint_qualification = AppealFinanceRuntimeProviderQualificationV1::new(
            checkpoint_binding.revision,
            checkpoint_binding.policy_digest,
        );
        let authentication_policy = AppealFinanceCheckpointAuthenticationPolicyV1 {
            version: APPEAL_FINANCE_CHECKPOINT_AUTHENTICATION_POLICY_VERSION_V1,
            provider_handle: checkpoint_binding.handle.clone(),
            public_key: checkpoint_public_key,
            revision: checkpoint_binding.revision,
            policy_digest: checkpoint_binding.policy_digest,
        };
        authentication_policy.validate().map_err(|error| {
            ToriiBuildError::invalid_configuration(
                "sorafs.appeal_finance.checkpoint_provider",
                error,
            )
        })?;
        let checkpoint_identity = checkpoint_runtime.identity().map_err(|error| {
            ToriiBuildError::invalid_runtime_dependency(
                "sorafs.appeal_finance.checkpoint_provider",
                format!("checkpoint identity is unavailable: {error:?}"),
            )
        })?;
        if checkpoint_identity.provider_handle != checkpoint_binding.handle
            || checkpoint_identity.public_key != checkpoint_public_key
            || checkpoint_identity.qualification != expected_checkpoint_qualification
        {
            return Err(ToriiBuildError::invalid_runtime_dependency(
                "sorafs.appeal_finance.checkpoint_provider",
                "checkpoint binding is substituted or stale",
            ));
        }
        let state_dir = storage_data_dir.join("appeal-finance-transaction-forwarder");
        let policy = AppealFinanceTransactionForwarderPolicyV1 {
            max_pending: config.worker_max_pending,
            max_completed: config.worker_max_completed,
            max_dead_letters: config.worker_max_dead_letters,
            max_attempts: config.worker_max_retry_attempts,
            max_transaction_bytes: APPEAL_FINANCE_TRANSACTION_MAX_CANONICAL_BYTES_V1,
            checkpoint_max_bytes: config.worker_checkpoint_max_bytes,
        };
        let forwarder = AppealFinanceTransactionForwarder::open(
            &state_dir,
            policy,
            authentication_policy,
            checkpoint_runtime,
        )
        .map_err(|error| {
            ToriiBuildError::component_initialization(
                "sorafs.appeal_finance.transaction_forwarder",
                format!(
                    "failed to open durable state at {}: {error}",
                    state_dir.display()
                ),
            )
        })?;
        Ok(Self {
            bindings: config.submitter_signers.clone(),
            runtime_signers,
            forwarder,
            worker_scan_interval: config.worker_scan_interval,
        })
    }
    fn active_binding_for<'a>(
        &'a self,
        authority: &AccountId,
        finalized_height: u64,
    ) -> Result<
        &'a iroha_config::parameters::actual::SorafsAppealFinanceSignerBinding,
        SoraFsAppealFinanceSignerSelectionError,
    > {
        let binding = self
            .bindings
            .iter()
            .filter(|binding| {
                &binding.authority == authority
                    && binding.valid_from_block_height <= finalized_height
                    && binding
                        .revoked_at_block_height
                        .is_none_or(|height| finalized_height < height)
            })
            .max_by_key(|binding| binding.valid_from_block_height);
        let Some(binding) = binding else {
            return Err(
                if self.bindings.iter().any(|binding| {
                    &binding.authority == authority
                        && binding.valid_from_block_height > finalized_height
                }) {
                    SoraFsAppealFinanceSignerSelectionError::NotYetActive
                } else {
                    SoraFsAppealFinanceSignerSelectionError::NoActiveBinding
                },
            );
        };
        Ok(binding)
    }
    fn signer_for(
        &self,
        authority: &AccountId,
        finalized_height: u64,
    ) -> Result<SoraFsAppealFinanceQualifiedSignerV1, SoraFsAppealFinanceSignerSelectionError> {
        let binding = self.active_binding_for(authority, finalized_height)?;
        let provider = self
            .runtime_signers
            .as_ref()
            .and_then(|registry| registry.get(&binding.handle))
            .ok_or(SoraFsAppealFinanceSignerSelectionError::ProviderMissing)?;
        SoraFsAppealFinanceQualifiedSignerV1::try_new(binding, provider)
    }
    fn signer_count(&self, finalized_height: u64) -> usize {
        self.bindings
            .iter()
            .filter(|binding| {
                binding.valid_from_block_height <= finalized_height
                    && binding
                        .revoked_at_block_height
                        .is_none_or(|height| finalized_height < height)
            })
            .count()
    }
    fn worker_scan_interval(&self) -> Duration {
        self.worker_scan_interval
    }
}
/// Runtime-only signer for durable appeal-finance asset-lock transactions.
///
/// Implementations are expected to delegate to an independently administered
/// external signing service. They receive only a fully constructed fee-quoted
/// payload and have no queue or outbox capability.
#[cfg(feature = "app_api")]
pub trait SoraFsAppealFinanceTransactionSigner: Send + Sync {
    /// Stable opaque provider handle matching the non-secret configured binding.
    fn handle(&self) -> &str;
    /// Exact public key controlled by this provider.
    fn public_key(&self) -> Result<PublicKey, SoraFsAppealFinanceSigningError>;
    /// Qualify the active adapter and exact public-policy revision.
    fn qualification(
        &self,
    ) -> Result<
        sorafs_node::appeal_finance_transaction_forwarder::AppealFinanceRuntimeProviderQualificationV1,
        SoraFsAppealFinanceSigningError,
    >;
    /// Sign the exact transaction payload.
    fn sign(
        &self,
        payload: TransactionPayload,
    ) -> Result<SignedTransaction, SoraFsAppealFinanceSigningError>;
}
/// Payload-free appeal-finance signer failure.
#[cfg(feature = "app_api")]
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum SoraFsAppealFinanceSigningError {
    /// External signing service is temporarily unavailable.
    Unavailable,
    /// Provider refused or failed the signing operation.
    Refused,
    /// Provider identity, revision, or public policy changed around the request.
    QualificationChanged,
}
#[cfg(feature = "app_api")]
#[derive(Clone)]
struct SoraFsAppealFinanceQualifiedSignerV1 {
    signer: Arc<dyn SoraFsAppealFinanceTransactionSigner>,
    handle: String,
    public_key: PublicKey,
    qualification:
        sorafs_node::appeal_finance_transaction_forwarder::AppealFinanceRuntimeProviderQualificationV1,
}
#[cfg(feature = "app_api")]
impl SoraFsAppealFinanceQualifiedSignerV1 {
    fn try_new(
        binding: &iroha_config::parameters::actual::SorafsAppealFinanceSignerBinding,
        signer: Arc<dyn SoraFsAppealFinanceTransactionSigner>,
    ) -> Result<Self, SoraFsAppealFinanceSignerSelectionError> {
        let qualified = Self {
            signer,
            handle: binding.handle.clone(),
            public_key: binding.public_key.clone(),
            qualification:
                sorafs_node::appeal_finance_transaction_forwarder::AppealFinanceRuntimeProviderQualificationV1::new(
                    binding.revision,
                    binding.policy_digest,
                ),
        };
        qualified.revalidate()?;
        if AccountId::new(qualified.public_key.clone()) != binding.authority {
            return Err(SoraFsAppealFinanceSignerSelectionError::IdentityMismatch);
        }
        Ok(qualified)
    }
    fn public_key(&self) -> &PublicKey {
        &self.public_key
    }
    fn revalidate(&self) -> Result<(), SoraFsAppealFinanceSignerSelectionError> {
        if self.signer.handle() != self.handle {
            return Err(SoraFsAppealFinanceSignerSelectionError::IdentityMismatch);
        }
        let qualification = self
            .signer
            .qualification()
            .map_err(|_| SoraFsAppealFinanceSignerSelectionError::ProviderUnavailable)?;
        qualification
            .validate()
            .map_err(|_| SoraFsAppealFinanceSignerSelectionError::IdentityMismatch)?;
        if self.signer.handle() != self.handle || qualification != self.qualification {
            return Err(SoraFsAppealFinanceSignerSelectionError::IdentityMismatch);
        }
        let public_key_result = self.signer.public_key();
        let qualification_after_key = self
            .signer
            .qualification()
            .map_err(|_| SoraFsAppealFinanceSignerSelectionError::ProviderUnavailable)?;
        let public_key = public_key_result
            .map_err(|_| SoraFsAppealFinanceSignerSelectionError::ProviderUnavailable)?;
        if self.signer.handle() != self.handle
            || qualification_after_key != self.qualification
            || public_key != self.public_key
        {
            return Err(SoraFsAppealFinanceSignerSelectionError::IdentityMismatch);
        }
        Ok(())
    }
    fn sign(
        &self,
        payload: TransactionPayload,
    ) -> Result<SignedTransaction, SoraFsAppealFinanceSigningError> {
        self.revalidate()
            .map_err(|_| SoraFsAppealFinanceSigningError::QualificationChanged)?;
        let result = self.signer.sign(payload);
        self.revalidate()
            .map_err(|_| SoraFsAppealFinanceSigningError::QualificationChanged)?;
        result
    }
}
/// Validated runtime registry of opaque appeal-finance signer providers.
#[cfg(feature = "app_api")]
#[derive(Clone, Default)]
pub struct SoraFsAppealFinanceRuntimeSignersV1 {
    signers: BTreeMap<String, Arc<dyn SoraFsAppealFinanceTransactionSigner>>,
}
#[cfg(feature = "app_api")]
impl SoraFsAppealFinanceRuntimeSignersV1 {
    /// Validate and construct one runtime signer registry.
    pub fn new(
        signers: Vec<Arc<dyn SoraFsAppealFinanceTransactionSigner>>,
    ) -> Result<Self, SoraFsAppealFinanceRuntimeSignerRegistryError> {
        let mut registry = BTreeMap::new();
        for signer in signers {
            let handle = signer.handle().to_owned();
            validate_production_runtime_handle(&handle).map_err(|error| match error {
                ProductionRuntimeHandleError::InvalidSyntax
                | ProductionRuntimeHandleError::TestMarked => {
                    SoraFsAppealFinanceRuntimeSignerRegistryError::InvalidHandle
                }
            })?;
            let qualification = signer
                .qualification()
                .map_err(|_| SoraFsAppealFinanceRuntimeSignerRegistryError::ProviderUnavailable)?;
            qualification
                .validate()
                .map_err(|_| SoraFsAppealFinanceRuntimeSignerRegistryError::InvalidQualification)?;
            if signer.handle() != handle.as_str() {
                return Err(SoraFsAppealFinanceRuntimeSignerRegistryError::IdentityDrift);
            }
            let public_key_result = signer.public_key();
            let qualification_after_key = signer
                .qualification()
                .map_err(|_| SoraFsAppealFinanceRuntimeSignerRegistryError::ProviderUnavailable)?;
            let public_key = public_key_result
                .map_err(|_| SoraFsAppealFinanceRuntimeSignerRegistryError::ProviderUnavailable)?;
            if signer.handle() != handle.as_str() || qualification_after_key != qualification {
                return Err(SoraFsAppealFinanceRuntimeSignerRegistryError::IdentityDrift);
            }
            if !matches!(
                public_key.try_algorithm(),
                Ok(iroha_crypto::Algorithm::Ed25519)
            ) {
                return Err(SoraFsAppealFinanceRuntimeSignerRegistryError::InvalidPublicKey);
            }
            if registry.insert(handle, signer).is_some() {
                return Err(SoraFsAppealFinanceRuntimeSignerRegistryError::DuplicateHandle);
            }
        }
        Ok(Self { signers: registry })
    }
    fn get(&self, handle: &str) -> Option<Arc<dyn SoraFsAppealFinanceTransactionSigner>> {
        self.signers.get(handle).cloned()
    }
}
/// Appeal-finance runtime signer registry error.
#[cfg(feature = "app_api")]
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum SoraFsAppealFinanceRuntimeSignerRegistryError {
    /// Handle is empty, unbounded, noncanonical, or test-marked.
    InvalidHandle,
    /// Handle is duplicated.
    DuplicateHandle,
    /// Provider key is not Ed25519.
    InvalidPublicKey,
    /// Provider could not prove current production readiness.
    ProviderUnavailable,
    /// Provider returned a zero or unsupported public qualification.
    InvalidQualification,
    /// Provider identity or public policy changed during registry construction.
    IdentityDrift,
}
#[cfg(feature = "app_api")]
fn qualify_appeal_finance_runtime_signer_inventory(
    bindings: &[iroha_config::parameters::actual::SorafsAppealFinanceSignerBinding],
    registry: Option<&SoraFsAppealFinanceRuntimeSignersV1>,
    finalized_startup_height: u64,
) -> Result<(), SoraFsAppealFinanceRuntimeSignerQualificationError> {
    if bindings.is_empty() {
        return Ok(());
    }
    let registry =
        registry.ok_or(SoraFsAppealFinanceRuntimeSignerQualificationError::RegistryMissing)?;
    for binding in bindings.iter().filter(|binding| {
        binding
            .revoked_at_block_height
            .is_none_or(|height| finalized_startup_height < height)
    }) {
        let provider = registry.get(&binding.handle).ok_or_else(|| {
            SoraFsAppealFinanceRuntimeSignerQualificationError::ProviderMissing {
                handle: binding.handle.clone(),
            }
        })?;
        if provider.handle() != binding.handle {
            return Err(
                SoraFsAppealFinanceRuntimeSignerQualificationError::HandleMismatch {
                    handle: binding.handle.clone(),
                },
            );
        }
        let qualification = provider.qualification().map_err(|_| {
            SoraFsAppealFinanceRuntimeSignerQualificationError::ProviderUnavailable {
                handle: binding.handle.clone(),
            }
        })?;
        let expected_qualification =
            sorafs_node::appeal_finance_transaction_forwarder::AppealFinanceRuntimeProviderQualificationV1::new(
                binding.revision,
                binding.policy_digest,
            );
        if qualification.validate().is_err() || qualification != expected_qualification {
            return Err(
                SoraFsAppealFinanceRuntimeSignerQualificationError::QualificationMismatch {
                    handle: binding.handle.clone(),
                },
            );
        }
        let public_key_result = provider.public_key();
        let qualification_after_key = provider.qualification().map_err(|_| {
            SoraFsAppealFinanceRuntimeSignerQualificationError::ProviderUnavailable {
                handle: binding.handle.clone(),
            }
        })?;
        let public_key = public_key_result.map_err(|_| {
            SoraFsAppealFinanceRuntimeSignerQualificationError::ProviderUnavailable {
                handle: binding.handle.clone(),
            }
        })?;
        if provider.handle() != binding.handle || qualification_after_key != expected_qualification
        {
            return Err(
                SoraFsAppealFinanceRuntimeSignerQualificationError::QualificationChanged {
                    handle: binding.handle.clone(),
                },
            );
        }
        if public_key != binding.public_key {
            return Err(
                SoraFsAppealFinanceRuntimeSignerQualificationError::PublicKeyMismatch {
                    handle: binding.handle.clone(),
                },
            );
        }
        if AccountId::new(public_key) != binding.authority {
            return Err(
                SoraFsAppealFinanceRuntimeSignerQualificationError::AccountIdMismatch {
                    handle: binding.handle.clone(),
                },
            );
        }
    }
    Ok(())
}
#[cfg(feature = "app_api")]
#[derive(Debug, Clone, PartialEq, Eq)]
enum SoraFsAppealFinanceRuntimeSignerQualificationError {
    RegistryMissing,
    ProviderMissing { handle: String },
    HandleMismatch { handle: String },
    PublicKeyMismatch { handle: String },
    AccountIdMismatch { handle: String },
    ProviderUnavailable { handle: String },
    QualificationMismatch { handle: String },
    QualificationChanged { handle: String },
}
