    #[cfg(feature = "app_api")]
    fn spawn_pin_registry_metrics_worker(
        &self,
        shutdown_signal: ShutdownSignal,
    ) -> Option<tokio::task::JoinHandle<ToriiCriticalWorkerExit>> {
        if !self.telemetry.allows_metrics() {
            return None;
        }
        let state = self.state.clone();
        let telemetry = self.telemetry.clone();
        Some(tokio::spawn(async move {
            const PIN_REGISTRY_METRICS_INTERVAL_SECS: u64 = 30;
            let mut ticker =
                tokio::time::interval(Duration::from_secs(PIN_REGISTRY_METRICS_INTERVAL_SECS));
            ticker.set_missed_tick_behavior(tokio::time::MissedTickBehavior::Skip);
            loop {
                tokio::select! {
                    biased;
                    _ = shutdown_signal.receive() => {
                        return ToriiCriticalWorkerExit::StoppedByShutdown;
                    }
                    _ = ticker.tick() => {
                        if shutdown_signal.is_sent() {
                            return ToriiCriticalWorkerExit::StoppedByShutdown;
                        }
                        if let Err(err) = Self::sample_pin_registry_metrics(&state, &telemetry) {
                            iroha_logger::error!(?err, "failed to read SoraFS pin resource summary");
                        }
                    }
                }
            }
        }))
    }
    #[cfg(feature = "app_api")]
    fn sample_pin_registry_metrics(
        state: &Arc<CoreState>,
        telemetry: &routing::MaybeTelemetry,
    ) -> Result<(), String> {
        const PIN_GLOBAL_USAGE_STATE_KEY_V1: &str = "sorafs_pin_accounting_v1/global";
        const PIN_GLOBAL_USAGE_MAX_BYTES_V1: usize = 128;
        let key = iroha_data_model::state_path::StatePath::from_str(PIN_GLOBAL_USAGE_STATE_KEY_V1)
            .map_err(|error| format!("invalid pin resource summary state path: {error:?}"))?;
        let world = state.world_view();
        let usage = match world.smart_contract_state().get(&key) {
            None => iroha_data_model::sorafs::pin_registry::PinResourceUsage::default(),
            Some(bytes) => {
                if bytes.len() > PIN_GLOBAL_USAGE_MAX_BYTES_V1 {
                    return Err(format!(
                        "pin resource summary exceeds {PIN_GLOBAL_USAGE_MAX_BYTES_V1} bytes"
                    ));
                }
                let usage = norito::decode_from_bytes::<
                    iroha_data_model::sorafs::pin_registry::PinResourceUsage,
                >(bytes)
                .map_err(|error| format!("failed to decode pin resource summary: {error}"))?;
                let canonical = norito::to_bytes(&usage)
                    .map_err(|error| format!("failed to encode pin resource summary: {error}"))?;
                if canonical.as_slice() != bytes.as_slice() {
                    return Err("pin resource summary is not canonical Norito".to_owned());
                }
                usage
            }
        };
        telemetry.with_metrics(|metrics| {
            metrics.record_sorafs_pin_resource_usage(usage.manifest_count, usage.content_bytes);
        });
        Ok(())
    }
    #[cfg(feature = "app_api")]
    fn spawn_por_ingestion_metrics_worker(
        &self,
        shutdown_signal: ShutdownSignal,
    ) -> Option<tokio::task::JoinHandle<ToriiCriticalWorkerExit>> {
        if !self.telemetry.allows_metrics() || !self.sorafs_node.is_enabled() {
            return None;
        }
        let telemetry = self.telemetry.clone();
        let sorafs_node = self.sorafs_node.clone();
        Some(tokio::spawn(async move {
            const POR_INGEST_METRICS_INTERVAL_SECS: u64 = 30;
            let mut ticker =
                tokio::time::interval(Duration::from_secs(POR_INGEST_METRICS_INTERVAL_SECS));
            ticker.set_missed_tick_behavior(tokio::time::MissedTickBehavior::Skip);
            let mut known_pairs: HashSet<([u8; 32], [u8; 32])> = HashSet::new();
            loop {
                tokio::select! {
                    biased;
                    _ = shutdown_signal.receive() => {
                        return ToriiCriticalWorkerExit::StoppedByShutdown;
                    }
                    _ = ticker.tick() => {
                        if shutdown_signal.is_sent() {
                            return ToriiCriticalWorkerExit::StoppedByShutdown;
                        }
                        Self::sample_por_ingestion_metrics(
                            &sorafs_node,
                            &telemetry,
                            &mut known_pairs,
                        );
                    }
                }
            }
        }))
    }
    #[cfg(feature = "app_api")]
    fn spawn_evidence_viewer_compaction_worker(
        &self,
        shutdown_signal: ShutdownSignal,
    ) -> Option<EvidenceViewerCompactionWorkerHandle> {
        let Some(service) = self.sorafs_evidence_viewer.clone() else {
            return None;
        };
        let Some(transparency_producer) = self.sorafs_evidence_viewer_transparency_producer.clone()
        else {
            return None;
        };
        let task = tokio::spawn(async move {
            let mut ticker =
                tokio::time::interval(Duration::from_millis(service.compaction_interval_ms()));
            ticker.set_missed_tick_behavior(tokio::time::MissedTickBehavior::Skip);
            let mut transparency_failure_streak = 0_u8;
            let mut transparency_backoff_ticks = 0_u8;
            while wait_for_evidence_viewer_compaction_tick(&shutdown_signal, &mut ticker).await {
                if transparency_backoff_ticks > 0 {
                    transparency_backoff_ticks -= 1;
                } else {
                    match publish_evidence_viewer_transparency_tick(
                        service.as_ref(),
                        transparency_producer.as_ref(),
                    ) {
                        Ok(()) => {
                            transparency_failure_streak = 0;
                        }
                        Err(failure) => {
                            transparency_failure_streak =
                                transparency_failure_streak.saturating_add(1);
                            transparency_backoff_ticks = evidence_viewer_transparency_backoff_ticks(
                                transparency_failure_streak,
                            );
                            iroha_logger::warn!(
                                code = failure.code(),
                                retry_after_ticks = transparency_backoff_ticks,
                                "bounded evidence-viewer transparency publication tick failed"
                            );
                        }
                    }
                }
                let now_unix_ms = match SystemTime::now().duration_since(UNIX_EPOCH) {
                    Ok(duration) => match u64::try_from(duration.as_millis()) {
                        Ok(timestamp) => timestamp,
                        Err(_) => {
                            iroha_logger::error!(
                                "evidence-viewer compaction clock exceeded the supported range"
                            );
                            continue;
                        }
                    },
                    Err(_) => {
                        iroha_logger::error!(
                            "evidence-viewer compaction clock preceded the Unix epoch"
                        );
                        continue;
                    }
                };
                if let Err(error) = service.compact_expired_tick(now_unix_ms) {
                    iroha_logger::warn!(
                        ?error,
                        "bounded evidence-viewer archive compaction tick failed"
                    );
                }
            }
        });
        Some(EvidenceViewerCompactionWorkerHandle::new(task))
    }
    #[cfg(feature = "app_api")]
    fn sample_por_ingestion_metrics(
        sorafs_node: &sorafs_node::NodeHandle,
        telemetry: &routing::MaybeTelemetry,
        known_pairs: &mut HashSet<([u8; 32], [u8; 32])>,
    ) {
        let statuses = sorafs_node.por_ingestion_overview();
        let mut active_pairs: HashSet<([u8; 32], [u8; 32])> = HashSet::new();
        telemetry.with_metrics(|metrics| {
            for status in &statuses {
                let pair = (status.manifest_digest, status.provider_id);
                active_pairs.insert(pair);
                let manifest_hex = hex::encode(status.manifest_digest);
                let provider_hex = hex::encode(status.provider_id);
                metrics.record_sorafs_por_ingestion_backlog(
                    &provider_hex,
                    &manifest_hex,
                    status.pending_challenges,
                );
                metrics.record_sorafs_por_ingestion_failures(
                    &provider_hex,
                    &manifest_hex,
                    status.failures_total,
                );
            }
        });
        telemetry.with_metrics(|metrics| {
            for pair in known_pairs.iter() {
                if active_pairs.contains(pair) {
                    continue;
                }
                let manifest_hex = hex::encode(pair.0);
                let provider_hex = hex::encode(pair.1);
                metrics.record_sorafs_por_ingestion_backlog(&provider_hex, &manifest_hex, 0);
                metrics.record_sorafs_por_ingestion_failures(&provider_hex, &manifest_hex, 0);
            }
        });
        *known_pairs = active_pairs;
    }
