#[cfg(feature = "app_api")]
fn build_sorafs_quota_config(
    config: &iroha_config::parameters::actual::SorafsQuota,
) -> sorafs::SorafsQuotaConfig {
    fn convert_window(
        window: &iroha_config::parameters::actual::SorafsQuotaWindow,
    ) -> sorafs::SorafsQuotaWindow {
        sorafs::SorafsQuotaWindow {
            max_events: window.max_events.map(std::num::NonZeroU32::get),
            window: window.window,
        }
    }
    sorafs::SorafsQuotaConfig {
        capacity_declaration: convert_window(&config.capacity_declaration),
        capacity_telemetry: convert_window(&config.capacity_telemetry),
        capacity_dispute: convert_window(&config.capacity_dispute),
        por_submission: convert_window(&config.por_submission),
    }
}
#[cfg(feature = "app_api")]
fn por_runtime_readiness_error(
    config: &iroha_config::parameters::actual::SorafsPor,
) -> Option<String> {
    if !config.enabled {
        return None;
    }
    let drand = &config.drand;
    if drand.scheme != iroha_crypto::drand::UNCHAINED_G1_RFC9380_SCHEME {
        return Some("pinned drand scheme is missing or unsupported".to_owned());
    }
    if drand.chain_hash.iter().all(|byte| *byte == 0)
        || drand.public_key.iter().all(|byte| *byte == 0)
        || drand.genesis_time == 0
        || drand.period_secs == 0
    {
        return Some(
            "pinned drand chain hash, public key, genesis, and period are required".to_owned(),
        );
    }
    if drand.endpoints.len() < 3
        || drand.endpoints.len() > drand.max_endpoints
        || usize::from(drand.quorum) <= drand.endpoints.len() / 2
        || usize::from(drand.quorum) >= drand.endpoints.len()
    {
        return Some(
            "drand endpoints require a bounded strict-majority quorum that tolerates one outage"
                .to_owned(),
        );
    }
    if config.vrf_max_entries == 0
        || config.vrf_retention_epochs == 0
        || config.vrf_submission_deadline_secs >= config.epoch_interval_secs
    {
        return Some("provider VRF bounds/deadline are invalid".to_owned());
    }
    None
}
#[cfg(feature = "app_api")]
fn validate_por_runtime_ready(
    config: &iroha_config::parameters::actual::SorafsPor,
) -> Result<(), ToriiBuildError> {
    if let Some(detail) = por_runtime_readiness_error(config) {
        return Err(ToriiBuildError::invalid_configuration(
            "sorafs.por",
            format!(
                "{detail}; configure complete pinned drand trust, quorum, persistence, and provider VRF policy"
            ),
        ));
    }
    Ok(())
}
#[cfg(feature = "app_api")]
fn build_por_components(
    config: &Config,
    network_id: &NetworkId,
    sorafs_node: &sorafs_node::NodeHandle,
    admission: Option<Arc<sorafs::AdmissionRegistry>>,
) -> Result<
    (
        Arc<sorafs::PorCoordinator>,
        Option<Arc<sorafs::PorCoordinatorRuntime>>,
    ),
    ToriiBuildError,
> {
    let por_cfg = &config.sorafs_por;
    validate_por_runtime_ready(por_cfg)?;
    let snapshot_path = por_cfg
        .state_dir
        .join(iroha_config::parameters::defaults::sorafs::por::COORDINATOR_STATE_FILE);
    let status_record_limit = config.sorafs_storage.runtime.state_entry_limit;
    let coordinator_result = sorafs::PorCoordinator::with_persistence_and_record_limit(
        &snapshot_path,
        status_record_limit,
    );
    let coordinator = match coordinator_result {
        Ok(coord) => Arc::new(coord),
        Err(err) if !por_cfg.enabled => {
            iroha_logger::warn!(
                ?err,
                path = ?snapshot_path,
                "failed to load PoR report-publication state while PoR is disabled; lifecycle reads remain unavailable"
            );
            Arc::new(sorafs::PorCoordinator::with_record_limit(
                status_record_limit,
            ))
        }
        Err(error) => {
            return Err(ToriiBuildError::component_initialization(
                "sorafs.por.coordinator_state",
                format!("failed to load {}: {error}", snapshot_path.display()),
            ));
        }
    };
    if !por_cfg.enabled {
        return Ok((coordinator, None));
    }
    if !sorafs_node.is_enabled() {
        return Err(ToriiBuildError::invalid_configuration(
            "sorafs.por",
            "enabled PoR requires embedded SoraFS storage",
        ));
    }
    let authoritative_snapshot = sorafs_node
        .por_status_authority_snapshot()
        .map_err(|error| {
            ToriiBuildError::component_initialization(
                "sorafs.por.authoritative_projection",
                format!("failed to load checkpoint projection: {error}"),
            )
        })?;
    coordinator
        .install_authoritative_projection(authoritative_snapshot)
        .map_err(|error| {
            ToriiBuildError::component_initialization(
                "sorafs.por.authoritative_projection",
                format!("failed to install checkpoint projection: {error}"),
            )
        })?;
    coordinator
        .retire_lifecycle_persistence()
        .map_err(|error| {
            ToriiBuildError::component_initialization(
                "sorafs.por.coordinator_state",
                format!("failed to retire duplicate lifecycle state: {error}"),
            )
        })?;
    let admission = admission.ok_or_else(|| {
        ToriiBuildError::invalid_runtime_dependency(
            "sorafs.por.admission",
            "enabled PoR requires the council-verified provider admission registry",
        )
    })?;
    if admission.is_empty() {
        return Err(ToriiBuildError::invalid_runtime_dependency(
            "sorafs.por.admission",
            "enabled PoR requires at least one admitted provider",
        ));
    }
    let randomness = Arc::new(
        sorafs::DrandHttpRandomnessProvider::from_config(
            &por_cfg.drand,
            por_cfg.epoch_interval_secs,
        )
        .map_err(|error| ToriiBuildError::component_initialization("sorafs.por.drand", error))?,
    );
    let vrf_provider = Arc::new(
        sorafs::VerifiedVrfProvider::with_persistence(
            admission,
            *network_id,
            por_cfg.vrf_state_path.clone(),
            por_cfg.vrf_max_entries,
            por_cfg.vrf_retention_epochs,
            por_cfg.vrf_max_clock_skew_secs,
        )
        .map_err(|error| {
            ToriiBuildError::component_initialization("sorafs.por.vrf_state", error)
        })?,
    );
    let runtime = sorafs::PorCoordinatorRuntime::new(
        Arc::new(sorafs_node.clone()),
        coordinator.clone(),
        randomness,
        vrf_provider.clone(),
        Arc::new(sorafs_node.clone()),
        por_cfg.epoch_interval_secs,
        por_cfg.response_window_secs,
        por_cfg.vrf_submission_deadline_secs,
    )
    .with_verified_vrf_provider(vrf_provider);
    Ok((coordinator, Some(Arc::new(runtime))))
}
#[cfg(all(test, feature = "app_api"))]
mod por_runtime_readiness_tests {
    use super::{por_runtime_readiness_error, validate_por_runtime_ready};
    fn configured_por() -> iroha_config::parameters::actual::SorafsPor {
        let mut config = iroha_config::parameters::actual::SorafsPor {
            enabled: true,
            ..Default::default()
        };
        config.drand.scheme = iroha_crypto::drand::UNCHAINED_G1_RFC9380_SCHEME.to_owned();
        config.drand.chain_hash =
            hex::decode("52db9ba70e0cc0f6eaf7803dd07447a1f5477735fd3f661792ba94600c84e971")
                .expect("chain hash")
                .try_into()
                .expect("32-byte chain hash");
        config.drand.public_key = hex::decode(concat!(
            "83cf0f2896adee7eb8b5f01fcad3912212c437e0073e911fb90022d3e760183c",
            "8c4b450b6a0a6c3ac6a5776a2d1064510d1fec758c921cc22b0e17e63aaf4bcb",
            "5ed66304de9cf809bd274ca73bab4af5a6e9c76a4bc09e76eae8991ef5ece45a"
        ))
        .expect("public key")
        .try_into()
        .expect("96-byte public key");
        config.drand.genesis_time = 1_692_803_367;
        config.drand.period_secs = 3;
        let chain = hex::encode(config.drand.chain_hash);
        config.drand.endpoints = ["api.drand.sh", "api2.drand.sh", "drand.cloudflare.com"]
            .into_iter()
            .map(|host| format!("https://{host}/v2/chains/{chain}"))
            .collect();
        config.drand.quorum = 2;
        config
    }
    #[test]
    fn por_runtime_is_disabled_or_requires_complete_verified_entropy_config() {
        let mut config = iroha_config::parameters::actual::SorafsPor::default();
        assert_eq!(por_runtime_readiness_error(&config), None);
        config.enabled = true;
        assert!(por_runtime_readiness_error(&config).is_some());
        let error = validate_por_runtime_ready(&config)
            .expect_err("enabled incomplete PoR runtime must fail construction");
        assert!(matches!(
            error,
            ToriiBuildError::InvalidConfiguration {
                component: "sorafs.por",
                ..
            }
        ));
        let configured = configured_por();
        assert_eq!(por_runtime_readiness_error(&configured), None);
        validate_por_runtime_ready(&configured).expect("complete PoR configuration");
        let mut missing_key = configured.clone();
        missing_key.drand.public_key = [0; 96];
        assert!(por_runtime_readiness_error(&missing_key).is_some());
        let mut no_quorum = configured.clone();
        no_quorum.drand.quorum = 1;
        assert!(por_runtime_readiness_error(&no_quorum).is_some());
        let mut late_vrf = configured;
        late_vrf.vrf_submission_deadline_secs = late_vrf.epoch_interval_secs;
        assert!(por_runtime_readiness_error(&late_vrf).is_some());
    }
}
#[cfg(feature = "app_api")]
fn build_gc_runtime(
    sorafs_node: &sorafs_node::NodeHandle,
    state: Arc<CoreState>,
) -> Option<Arc<sorafs::GcSweeperRuntime>> {
    let config = sorafs_node.gc_config();
    if !config.enabled() {
        return None;
    }
    if !sorafs_node.is_enabled() {
        iroha_logger::warn!("GC runtime disabled: SoraFS storage is not enabled for this node");
        return None;
    }
    let runtime = Arc::new(sorafs::GcSweeperRuntime::new(
        sorafs_node.clone(),
        state,
        config,
    ));
    iroha_logger::info!(
        interval_secs = config.interval_secs(),
        max_deletions = config.max_deletions_per_run(),
        retention_grace_secs = config.retention_grace_secs(),
        "SoraFS GC runtime initialised"
    );
    Some(runtime)
}
/// Torii errors.
#[derive(thiserror::Error, displaydoc::Display, pretty_error_debug::Debug)]
pub enum Error {
    /// Failed to process query
    Query(#[from] iroha_data_model::ValidationFail),
    /// Validation error for app-facing query parameters `{code}`: {message}
    AppQueryValidation {
        /// Stable machine-readable code.
        code: &'static str,
        /// Human-readable error message.
        message: String,
    },
    /// Account onboarding validation failed `{code}`: {message}; hint: {hint:?}
    #[cfg(feature = "app_api")]
    AccountOnboardingValidation {
        /// Stable machine-readable code.
        code: &'static str,
        /// Human-readable error message.
        message: String,
        /// Optional operator-facing remediation hint.
        hint: Option<&'static str>,
    },
    /// Authentication is required for app-facing operation `{code}`: {message}
    AppUnauthorized {
        /// Stable machine-readable code.
        code: &'static str,
        /// Human-readable error message.
        message: String,
    },
    /// Forbidden error for app-facing operation `{code}`: {message}
    AppForbidden {
        /// Stable machine-readable code.
        code: &'static str,
        /// Human-readable error message.
        message: String,
    },
    /// Not-found error for app-facing operation `{code}`: {message}
    AppNotFound {
        /// Stable machine-readable code.
        code: &'static str,
        /// Human-readable error message.
        message: String,
    },
    /// Conflict error for app-facing operation `{code}`: {message}
    AppConflict {
        /// Stable machine-readable code.
        code: &'static str,
        /// Human-readable error message.
        message: String,
    },
    /// Temporarily unavailable app-facing operation `{code}`: {message}
    AppServiceUnavailable {
        /// Stable machine-readable code.
        code: &'static str,
        /// Human-readable error message.
        message: String,
    },
    /// Proof endpoint `{endpoint}` throttled the request; retry after {retry_after_secs}s
    ProofRateLimited {
        /// Logical endpoint label.
        endpoint: &'static str,
        /// Retry hint in whole seconds.
        retry_after_secs: u64,
    },
    /// Failed to accept transaction
    AcceptTransaction(#[from] iroha_core::tx::AcceptTransactionFail),
    /// Failed to get or set configuration
    Config(#[source] eyre::Report),
    /// SoraFS moderation runtime startup failed `{code}`
    #[cfg(feature = "app_api")]
    SorafsModerationStartup {
        /// Stable payload-free startup failure code.
        code: &'static str,
    },
    /// SoraFS evidence-viewer runtime startup failed `{code}`
    #[cfg(feature = "app_api")]
    SorafsEvidenceViewerStartup {
        /// Stable payload-free startup failure code.
        code: &'static str,
    },
    /// Transaction-history runtime configuration failed during startup: {reason}
    #[cfg(feature = "app_api")]
    TxHistoryStartup {
        /// Operator-facing configuration failure reason.
        reason: String,
    },
    /// Failed to serialize response payload for `{context}`: {source}
    SerializationFailure {
        /// Logical context for the serialization failure.
        context: &'static str,
        /// Underlying Norito JSON or binary-codec error.
        #[source]
        source: Box<dyn std::error::Error + Send + Sync>,
    },
    /// Failed to apply Nexus lane lifecycle plan: {reason}
    LaneLifecycle {
        /// Human-readable reason for the failure.
        reason: String,
    },
    /// Failed to push into queue ({source}; backpressure={backpressure:?})
    PushIntoQueue {
        /// Root cause from the core queue implementation.
        #[source]
        source: Box<queue::Error>,
        /// Snapshot of queue load when the error happened.
        backpressure: queue::BackpressureState,
    },
    #[cfg(feature = "telemetry")]
    /// Failed to get Prometheus metrics
    Prometheus(#[source] eyre::Report),
    #[cfg(feature = "profiling")]
    /// Failed to get pprof profile
    Pprof(#[source] eyre::Report),
    #[cfg(feature = "telemetry")]
    /// Failed to get status
    StatusFailure(#[source] eyre::Report),
    #[cfg(feature = "telemetry")]
    /// Telemetry endpoint {endpoint} disabled by active profile {profile:?}
    TelemetryProfileRestricted {
        /// Logical endpoint or capability name
        endpoint: &'static str,
        /// Active telemetry profile when denied
        profile: TelemetryProfile,
    },
    /// Failure caused by configuration subsystem
    ConfigurationFailure(#[from] KisoError),
    /// Failed to start Torii
    StartServer,
    /// Torii server terminated with an error
    FailedExit,
}
fn kagemusha_reject_code_from_message(message: &str) -> Option<&str> {
    use iroha_data_model::kagemusha::KAGEMUSHA_V1_REJECTION_REASON_PREFIX;
    let start = message.find(KAGEMUSHA_V1_REJECTION_REASON_PREFIX)?;
    let rest = &message[start + KAGEMUSHA_V1_REJECTION_REASON_PREFIX.len()..];
    let (label, _) = rest.split_once(':')?;
    if label.is_empty() { None } else { Some(label) }
}
fn kagemusha_reject_code_from_query_fail(
    fail: &iroha_data_model::query::error::QueryExecutionFail,
) -> Option<&str> {
    use iroha_data_model::query::error::QueryExecutionFail as Q;
    match fail {
        Q::Conversion(message) => kagemusha_reject_code_from_message(message),
        _ => None,
    }
}
fn kagemusha_reject_code_from_instruction_fail(
    fail: &iroha_data_model::isi::error::InstructionExecutionError,
) -> Option<&str> {
    use iroha_data_model::isi::error::InstructionExecutionError as I;
    match fail {
        I::Conversion(message) => kagemusha_reject_code_from_message(message),
        I::InvariantViolation(message) => kagemusha_reject_code_from_message(message.as_ref()),
        I::Query(fail) => kagemusha_reject_code_from_query_fail(fail),
        _ => None,
    }
}
fn kagemusha_reject_code_from_validation_fail(
    fail: &iroha_data_model::ValidationFail,
) -> Option<&str> {
    use iroha_data_model::ValidationFail as V;
    match fail {
        V::NotPermitted(message) => kagemusha_reject_code_from_message(message),
        V::QueryFailed(fail) => kagemusha_reject_code_from_query_fail(fail),
        V::InstructionFailed(fail) => kagemusha_reject_code_from_instruction_fail(fail),
        _ => None,
    }
}
fn validation_fail_message(fail: &iroha_data_model::ValidationFail) -> String {
    use iroha_data_model::{
        ValidationFail as V, isi::error::InstructionExecutionError as I,
        query::error::QueryExecutionFail as Q,
    };
    match fail {
        V::QueryFailed(Q::Conversion(message))
        | V::InstructionFailed(I::Query(Q::Conversion(message))) => message.clone(),
        V::QueryFailed(query_error) | V::InstructionFailed(I::Query(query_error)) => {
            query_error.to_string()
        }
        other => other.to_string(),
    }
}
fn public_validation_fail_envelope(
    fail: &iroha_data_model::ValidationFail,
    status: StatusCode,
) -> ErrorEnvelope {
    if status.is_server_error() {
        iroha_logger::error!(
            ?fail,
            "Internal validation failure was redacted from the public Torii response"
        );
        return ErrorEnvelope::new(
            "internal_server_error",
            "Torii could not complete the request.",
        );
    }
    ErrorEnvelope::new("query_validation_failed", validation_fail_message(fail))
}
impl IntoResponse for Error {
    fn into_response(self) -> Response {
        let format = utils::current_response_format();
        match self {
            Self::Query(err) => {
                let status = Self::query_status_code(&err);
                if status.is_server_error() {
                    return utils::respond_with_status_and_format(
                        status,
                        public_validation_fail_envelope(&err, status),
                        format,
                    );
                }
                let kagemusha_reason =
                    kagemusha_reject_code_from_validation_fail(&err).map(str::to_owned);
                let axt = match &err {
                    iroha_data_model::ValidationFail::AxtReject(ctx) => Some(ctx.clone()),
                    _ => None,
                };
                let mut details = ErrorDetails {
                    reject_code: kagemusha_reason.clone(),
                    ..Default::default()
                };
                details.axt = axt.as_ref().map(|ctx| AxtErrorDetails {
                    code: Some(ctx.reason.code().to_owned()),
                    reason: Some(ctx.reason.label().to_owned()),
                    snapshot_version: ctx.snapshot_version,
                    dataspace: ctx.dataspace.map(|dsid| dsid.as_u64()),
                    lane: ctx.lane.map(|lane| lane.as_u32()),
                    active_handle_era: ctx.active_handle_era,
                    next_handle_counter: ctx.next_handle_counter,
                });
                let mut envelope = public_validation_fail_envelope(&err, status);
                if !details.is_empty() {
                    envelope = envelope.with_details(details);
                }
                let mut response = utils::respond_with_status_and_format(status, envelope, format);
                let headers = response.headers_mut();
                if let Some(ctx) = axt {
                    headers.insert(
                        HeaderName::from_static("x-iroha-axt-code"),
                        HeaderValue::from_static(ctx.reason.code()),
                    );
                    headers.insert(
                        HeaderName::from_static("x-iroha-axt-reason"),
                        HeaderValue::from_static(ctx.reason.label()),
                    );
                    if let Some(snapshot_version) = ctx.snapshot_version {
                        if let Ok(value) = HeaderValue::from_str(&snapshot_version.to_string()) {
                            headers.insert(
                                HeaderName::from_static("x-iroha-axt-snapshot-version"),
                                value,
                            );
                        }
                    }
                    if let Some(dsid) = ctx.dataspace {
                        if let Ok(value) = HeaderValue::from_str(&dsid.as_u64().to_string()) {
                            headers.insert(HeaderName::from_static("x-iroha-axt-dataspace"), value);
                        }
                    }
                    if let Some(lane) = ctx.lane {
                        if let Ok(value) = HeaderValue::from_str(&lane.as_u32().to_string()) {
                            headers.insert(HeaderName::from_static("x-iroha-axt-lane"), value);
                        }
                    }
                    if let Some(hint) = ctx.active_handle_era {
                        if let Ok(value) = HeaderValue::from_str(&hint.to_string()) {
                            headers.insert(
                                HeaderName::from_static("x-iroha-axt-active-handle-era"),
                                value,
                            );
                        }
                    }
                    if let Some(hint) = ctx.next_handle_counter {
                        if let Ok(value) = HeaderValue::from_str(&hint.to_string()) {
                            headers.insert(
                                HeaderName::from_static("x-iroha-axt-next-handle-counter"),
                                value,
                            );
                        }
                    }
                }
                if headers.get("x-iroha-reject-code").is_none() {
                    if let Some(code) = kagemusha_reason {
                        if let Ok(header) = HeaderValue::from_str(&code) {
                            headers.insert(HeaderName::from_static("x-iroha-reject-code"), header);
                        }
                    }
                }
                response
            }
            Self::AppQueryValidation { code, message } => {
                let payload = ErrorEnvelope::new(code, message);
                let status = if code == "type_mismatch" {
                    StatusCode::UNPROCESSABLE_ENTITY
                } else {
                    StatusCode::BAD_REQUEST
                };
                let mut response = utils::respond_with_status_and_format(status, payload, format);
                if let Ok(header) = HeaderValue::from_str(code) {
                    response
                        .headers_mut()
                        .insert(HeaderName::from_static("x-iroha-reject-code"), header);
                }
                response
            }
            #[cfg(feature = "app_api")]
            Self::AccountOnboardingValidation {
                code,
                message,
                hint,
            } => {
                let payload = ErrorEnvelope::new(code, message).with_details(ErrorDetails {
                    hint: hint.map(str::to_owned),
                    ..Default::default()
                });
                utils::respond_with_status_and_format(StatusCode::BAD_REQUEST, payload, format)
            }
            Self::AppUnauthorized { code, message } => {
                let payload = ErrorEnvelope::new(code, message);
                let mut response = utils::respond_with_status_and_format(
                    StatusCode::UNAUTHORIZED,
                    payload,
                    format,
                );
                response.headers_mut().insert(
                    axum::http::header::WWW_AUTHENTICATE,
                    HeaderValue::from_static("Signature"),
                );
                if let Ok(header) = HeaderValue::from_str(code) {
                    response
                        .headers_mut()
                        .insert(HeaderName::from_static("x-iroha-reject-code"), header);
                }
                response
            }
            Self::AppForbidden { code, message } => {
                let payload = ErrorEnvelope::new(code, message);
                let mut response =
                    utils::respond_with_status_and_format(StatusCode::FORBIDDEN, payload, format);
                if let Ok(header) = HeaderValue::from_str(code) {
                    response
                        .headers_mut()
                        .insert(HeaderName::from_static("x-iroha-reject-code"), header);
                }
                response
            }
            Self::AppNotFound { code, message } => {
                let payload = ErrorEnvelope::new(code, message);
                let mut response =
                    utils::respond_with_status_and_format(StatusCode::NOT_FOUND, payload, format);
                if let Ok(header) = HeaderValue::from_str(code) {
                    response
                        .headers_mut()
                        .insert(HeaderName::from_static("x-iroha-reject-code"), header);
                }
                response
            }
            Self::AppConflict { code, message } => {
                let payload = ErrorEnvelope::new(code, message);
                let mut response =
                    utils::respond_with_status_and_format(StatusCode::CONFLICT, payload, format);
                if let Ok(header) = HeaderValue::from_str(code) {
                    response
                        .headers_mut()
                        .insert(HeaderName::from_static("x-iroha-reject-code"), header);
                }
                response
            }
            Self::AppServiceUnavailable { code, message } => {
                let payload = ErrorEnvelope::new(code, message);
                let mut response = utils::respond_with_status_and_format(
                    StatusCode::SERVICE_UNAVAILABLE,
                    payload,
                    format,
                );
                if let Ok(header) = HeaderValue::from_str(code) {
                    response
                        .headers_mut()
                        .insert(HeaderName::from_static("x-iroha-reject-code"), header);
                }
                response
            }
            Self::ProofRateLimited {
                endpoint,
                retry_after_secs,
            } => {
                let payload = ErrorEnvelope::new(
                    "proof_rate_limited",
                    format!(
                        "proof endpoint `{endpoint}` throttled; retry after {retry_after_secs}s"
                    ),
                )
                .with_details(ErrorDetails {
                    endpoint: Some(endpoint.to_owned()),
                    retry_after_seconds: Some(retry_after_secs),
                    ..Default::default()
                });
                let mut resp = utils::respond_with_status_and_format(
                    StatusCode::TOO_MANY_REQUESTS,
                    payload,
                    format,
                );
                if let Ok(header) = HeaderValue::from_str(&retry_after_secs.to_string()) {
                    resp.headers_mut()
                        .insert(axum::http::header::RETRY_AFTER, header);
                }
                resp
            }
            Self::LaneLifecycle { reason } => utils::respond_with_status_and_format(
                StatusCode::BAD_REQUEST,
                ErrorEnvelope::new("lane_lifecycle_error", reason),
                format,
            ),
            Self::PushIntoQueue {
                source,
                backpressure,
            } => {
                let status = Self::status_code_for_queue_error(source.as_ref());
                let envelope = Self::queue_error_envelope(source.as_ref(), Some(backpressure));
                let mut response = utils::respond_with_status_and_format(status, envelope, format);
                let headers = response.headers_mut();
                let (reject_code, _detail) = queue_rejection_metadata(source.as_ref());
                if let Ok(header) = HeaderValue::from_str(reject_code) {
                    headers.insert(HeaderName::from_static("x-iroha-reject-code"), header);
                }
                if let Ok(depth) = HeaderValue::from_str(&backpressure.queued().to_string()) {
                    headers.insert("X-Iroha-Queue-Depth", depth);
                }
                if let Ok(capacity) =
                    HeaderValue::from_str(&backpressure.capacity().get().to_string())
                {
                    headers.insert("X-Iroha-Queue-Capacity", capacity);
                }
                headers.insert(
                    "X-Iroha-Queue-State",
                    if backpressure.is_saturated() {
                        HeaderValue::from_static("saturated")
                    } else {
                        HeaderValue::from_static("healthy")
                    },
                );
                if matches!(
                    source.as_ref(),
                    queue::Error::Full
                        | queue::Error::LatencySaturated
                        | queue::Error::MaximumTransactionsPerUser
                ) {
                    headers.insert("Retry-After", HeaderValue::from_static("1"));
                }
                response
            }
            Self::AcceptTransaction(err) => {
                let (code, detail) = accept_transaction_metadata(&err);
                let details = ErrorDetails {
                    reject_code: Some(code.to_owned()),
                    ..Default::default()
                };
                let mut response = utils::respond_with_status_and_format(
                    StatusCode::BAD_REQUEST,
                    ErrorEnvelope::new(code, detail).with_details(details),
                    format,
                );
                if let Ok(header) = HeaderValue::from_str(code) {
                    response
                        .headers_mut()
                        .insert(HeaderName::from_static("x-iroha-reject-code"), header);
                }
                response
            }
            other => {
                let status = other.status_code();
                let payload = other.into_envelope();
                utils::respond_with_status_and_format(status, payload, format)
            }
        }
    }
}
#[allow(dead_code)]
fn _assert_torii_types_are_send_sync() {
    fn assert_send_sync<T: Send + Sync>() {}
    assert_send_sync::<Error>();
    assert_send_sync::<AppState>();
}
// Textual inclusion keeps runtime test helpers at their original module path.
